-- 17/11/2026 — Nâng chất lượng 36 bài kiến thức hẹn giờ (0077_bai_kien_thuc_hen_gio): mỗi bài thêm phần chuyên sâu (bảng so sánh,
--     lịch chăm / quy trình từng bước, sai lầm thường gặp) và mục "Câu hỏi thường gặp" — từ ~270–490 chữ lên ~800–1.100 chữ.
--     Giữ nguyên tiêu đề, đường dẫn, ảnh, khối sản phẩm, ngày đăng; chỉ cập nhật body + read_minutes. Phần thêm chèn trước
--     đoạn "Xem thêm…" / khối sản phẩm cuối bài. CHỈ ghi bài chưa ai sửa ở admin (updated_by = 'Hệ thống') — bài đã sửa tay không bị đè.
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Lật mặt dưới lá cà chua, ớt, bông giấy hay cây kiểng mà thấy một đám \"ruồi\" trắng nhỏ xíu bay tung lên như bụi phấn — đó là **bọ phấn trắng** (còn gọi ruồi trắng). Một vài con không đáng lo, nhưng chúng sinh sản rất nhanh, mùa khô nóng chỉ vài tuần là phủ kín mặt dưới lá."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Bemisia_tabaci_from_USDA_1.jpg/960px-Bemisia_tabaci_from_USDA_1.jpg","caption":"Bọ phấn trắng trưởng thành ở mặt dưới lá"},{"type":"h2","text":"🔍 Nhận biết bọ phấn trắng"},{"type":"list","items":["Con trưởng thành dài 1–2mm, cánh trắng phủ bột sáp, đậu ở **mặt dưới lá**, bay lên khi lay cây.","Trứng và ấu trùng là những chấm dẹt màu vàng nhạt, trong suốt, bám chặt mặt dưới lá, không di chuyển.","Lá có lớp mật dính bóng, sau đó đen lại như bồ hóng ([muội đen](/benh-cay/muoi-den)).","Lá vàng lốm đốm, cây chậm lớn; rau, ớt, cà chua có thể bị xoăn lá."],"ordered":false},{"type":"p","text":"Dễ nhầm với [rệp muội](/benh-cay/rep-muoi) (không có cánh trắng, bám đọt non thành đám) và [rệp sáp](/benh-cay/rep-sap) (phủ sáp như bông, gần như đứng yên)."},{"type":"h2","text":"🔎 Bọ phấn trắng gây hại thế nào?"},{"type":"p","text":"Chúng chích hút nhựa lá, tiết mật làm nấm muội đen phát triển, che ánh sáng của lá. Nguy hiểm hơn, bọ phấn **truyền virus** gây [vàng xoăn lá](/benh-cay/xoan-la-virus) trên cà chua, ớt, bí — bệnh virus không có thuốc chữa, chỉ nhổ bỏ cây. Vì vậy với rau ăn trái, phải diệt bọ phấn sớm."},{"type":"h2","text":"🛠️ Cách diệt bọ phấn trắng"},{"type":"list","items":["**Bẫy dính màu vàng**: bọ phấn bị màu vàng hút. Treo bẫy ngang tầm tán, cách 1–2m một tấm; vừa diệt vừa báo mật độ.","**Xịt nước mạnh mặt dưới lá** vào sáng sớm, 2–3 ngày một lần trong 2 tuần, rửa trôi trứng và ấu trùng.","**Cắt bỏ lá bị nặng** (nhiều ấu trùng) cho vào túi kín rồi bỏ đi, không vứt tại chỗ.","**Xà phòng sinh học hoặc dầu neem** pha theo hướng dẫn, phun kỹ mặt dưới lá lúc chiều mát; lặp lại sau 5–7 ngày vì trứng nở lứa mới.","Bị nặng trên rau, cây ăn trái mới dùng thuốc có đăng ký cho bọ phấn, đọc kỹ nhãn và thời gian cách ly."],"ordered":true},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Với rau và cây ăn trái, ưu tiên bẫy dính, xịt nước, xà phòng sinh học. Nếu phải dùng thuốc bảo vệ thực vật: chọn thuốc có đăng ký, dùng đúng liều, đeo găng tay khẩu trang và chỉ thu hoạch sau thời gian cách ly ghi trên nhãn. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."},{"type":"h2","text":"🛡️ Phòng bọ phấn quay lại"},{"type":"list","items":["Kiểm tra mặt dưới lá mỗi tuần, nhất là mùa khô.","Không bón dư đạm — đọt non mềm mập là món khoái khẩu của bọ phấn.","Cây mới mua về để riêng 1 tuần, kiểm tra kỹ rồi mới đặt cạnh cây khác.","Nhổ cỏ dại quanh vườn rau, nơi bọ phấn trú ẩn."],"ordered":false},{"type":"h2","text":"🔄 Vòng đời bọ phấn: vì sao phải xử lý nhiều lần?"},{"type":"p","text":"Một con bọ phấn cái đẻ trứng thành vòng cung ở mặt dưới lá non. Trứng nở ra ấu trùng bò một đoạn ngắn rồi bám chặt một chỗ, hút nhựa cho tới khi hóa nhộng và vũ hóa thành con trưởng thành có cánh. Trong điều kiện nóng ẩm như miền Tây, cả vòng đời chỉ mất khoảng 3–4 tuần, nên trên cùng một lá lúc nào cũng có đủ trứng, ấu trùng, nhộng và con trưởng thành."},{"type":"p","text":"Đây là lý do phun một lần thấy \"sạch\" mà một tuần sau đàn bọ lại bay tung: bẫy dính và nước xịt diệt được con trưởng thành, nhưng trứng và nhộng thì gần như không hề hấn gì. Muốn cắt đứt vòng đời phải **lặp lại đều đặn ít nhất 3–4 tuần** và kết hợp nhiều cách cùng lúc."},{"type":"h2","text":"📅 Lịch xử lý 4 tuần gợi ý"},{"type":"table","rows":[["Thời điểm","Việc cần làm"],["Ngày 1","Cắt bỏ lá bị nặng, treo bẫy dính vàng, xịt nước mạnh mặt dưới lá"],["Ngày 3–4","Phun xà phòng sinh học hoặc dầu neem lúc chiều mát, phun kỹ mặt dưới lá"],["Tuần 2","Xịt nước 2–3 lần; phun lặp lại lần 2; thay bẫy đã dính kín"],["Tuần 3","Phun lần 3; đếm số bọ trên bẫy để biết mật độ đã giảm chưa"],["Tuần 4 trở đi","Kiểm tra mặt dưới lá mỗi tuần; chỉ xử lý lại khi thấy bọ tăng"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Đếm số con dính trên bẫy mỗi tuần là cách đơn giản nhất để biết mình xử lý có hiệu quả hay không: số con giảm dần qua từng tuần là đúng hướng."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chỉ phun mặt trên lá**: bọ phấn và ấu trùng sống gần như hoàn toàn ở mặt dưới, phun mặt trên gần như vô ích.","**Phun một lần rồi thôi**: trứng nở lứa mới chỉ sau vài ngày.","**Đổi thuốc hóa học liên tục, tăng liều**: bọ phấn quen thuốc rất nhanh, càng phun mạnh càng diệt luôn thiên địch như bọ rùa, ong ký sinh.","**Để cây bị virus đứng chung với cây khỏe**: bọ phấn mang virus sang cây khác; cây đã xoăn vàng nặng nên nhổ bỏ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Bọ phấn trắng có bay sang cây trong nhà không?"},{"type":"p","text":"Có. Chúng bay khá xa và hay theo cây mới mua về. Cây kiểng lá trong nhà ít bị hơn rau ngoài trời, nhưng bông giấy, dâm bụt, cây có lá mềm đặt ban công vẫn thường bị. Cách ly cây mới 1 tuần là biện pháp rẻ và hiệu quả nhất."},{"type":"h3","text":"Có cần phun thuốc cho cây kiểng không?"},{"type":"p","text":"Thường là không. Với cây kiểng, bẫy dính, xịt nước và xà phòng sinh học đủ kiểm soát. Thuốc hóa học chỉ nên tính khi mật độ rất cao trên cây trồng ngoài trời, và phải là thuốc có đăng ký cho bọ phấn."},{"type":"h3","text":"Bẫy dính vàng có bắt nhầm côn trùng có ích không?"},{"type":"p","text":"Có bắt một ít, nhất là ong nhỏ. Vì vậy chỉ treo đủ số bẫy cần thiết, treo ngang tán cây, và gỡ bớt khi mật độ bọ phấn đã thấp."},{"type":"p","text":"Xem thêm [cách đọc nhãn thuốc trước khi dùng](/goc-cham-cay/doc-nhan-thuoc-bvtv-truoc-khi-dung) và [trồng ớt chậu tại nhà](/goc-cham-cay/trong-ot-chau)."}]$j$::jsonb, "read_minutes" = 6, "updated_at" = now()
  WHERE "slug" = $j$bo-phan-trang-tren-cay-canh-rau$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Cùng một cây, cùng lượng nước, nhưng tưới bằng nước khác nhau có thể cho kết quả khác nhau: lá xanh mướt hay cháy đầu lá, đất tơi hay đóng váng trắng. Ở miền Tây, nước giếng nhiễm phèn, mặn càng khiến chuyện chọn nước tưới quan trọng hơn."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Watering_plants_with_a_green_watering_can_during_a_sunny_day_in_a_garden_setting.jpg/960px-Watering_plants_with_a_green_watering_can_during_a_sunny_day_in_a_garden_setting.jpg","caption":"Bình tưới cây. Ảnh: Shixart1985, CC BY 2.0, Wikimedia Commons"},{"type":"h2","text":"🌧️ Nước mưa: tốt nhất"},{"type":"p","text":"Nước mưa mềm, hơi chua nhẹ, không có clo hay muối khoáng tích tụ — gần như loại cây nào cũng thích. Hứng nước mưa vào lu, thùng có nắp (tránh muỗi đẻ trứng), bỏ đi nước mưa đầu mùa vì cuốn theo bụi mái nhà."},{"type":"h2","text":"🚰 Nước máy: dùng được, nên để qua đêm"},{"type":"list","items":["Nước máy có clo khử trùng. Phần lớn cây chịu được, nhưng cây nhạy như [lan chi](/san-pham/lan-chi), [đuôi công](/san-pham/duoi-cong-xanh), [lan ý](/san-pham/lan-y) dễ cháy đầu lá.","Hứng nước ra xô, để mở nắp qua đêm cho clo bay bớt và nước bằng nhiệt độ phòng.","Mỗi vài tháng tưới thật đẫm cho nước chảy qua đáy chậu để rửa muối khoáng tích tụ."],"ordered":false},{"type":"h2","text":"🪣 Nước giếng: cần thử trước"},{"type":"list","items":["**Nước nhiễm phèn** (có mùi tanh, để lâu đóng váng vàng, lắng cặn đỏ): để lắng, lọc qua cát rồi mới tưới; phèn nặng làm đất chua, rễ thâm.","**Nước nhiễm mặn** (mùa khô, vùng ven biển): cây cảnh bị cháy mép lá, rụng lá. Đo độ mặn trước khi tưới — xem [phòng mặn cho cây mùa khô](/goc-cham-cay/phong-man-cho-cay-san-vuon).","Nước giếng sạch, không phèn mặn thì tưới tốt."],"ordered":false},{"type":"h2","text":"🍚 Nước vo gạo: dùng loãng, thỉnh thoảng"},{"type":"p","text":"Nước vo gạo có ít tinh bột, vitamin nhóm B, khoáng. Dùng loãng 1 phần nước vo với 2–3 phần nước sạch, khoảng 1–2 tuần một lần thì không hại. Dùng đặc và thường xuyên dễ làm đất chua, bốc mùi, sinh nấm mốc và ruồi nấm — nhất là chậu để trong nhà. Đây không phải là phân bón thay thế."},{"type":"h2","text":"❓ Các loại nước khác"},{"type":"table","rows":[["Loại nước","Có nên dùng?"],["Nước đá lạnh","Không — lạnh đột ngột làm sốc rễ cây nhiệt đới"],["Nước nóng, nước luộc rau","Để nguội hẳn mới dùng; nước luộc có muối thì không dùng"],["Nước rửa cá, rửa thịt","Hôi, dễ sinh giòi — không dùng cho chậu trong nhà"],["Nước máy lọc RO","Dùng được, nhưng không có khoáng — cần bón phân đều"],["Nước hồ cá cảnh khi thay","Tốt cho cây ngoài trời, có chất hữu cơ"]]},{"type":"h2","text":"🧪 Thử nước giếng tại nhà như thế nào?"},{"type":"p","text":"Không có máy đo vẫn có vài cách đơn giản để biết nước giếng có dùng tưới cây được không:"},{"type":"list","items":["**Để lắng**: hứng một xô nước trong, để yên 1 đêm. Đáy có cặn vàng, đỏ gạch, mặt nước có váng ánh dầu là nước nhiễm phèn sắt.","**Nếm thử một chút** (nhổ ra): vị mặn, lợ rõ là nước nhiễm mặn — không dùng tưới cây cảnh.","**Thử trên một cây**: tưới thử một chậu cây khỏe trong 2–3 tuần; mép lá cháy, đất đóng váng trắng là dấu hiệu nước có nhiều muối khoáng.","**Mượn bút đo độ mặn**: mùa khô nhiều xã ven biển có phát hoặc cho mượn bút đo; một số cửa hàng vật tư nông nghiệp cũng bán loại giá rẻ."],"ordered":true},{"type":"h2","text":"🌿 Cây nào nhạy với nước nhất?"},{"type":"table","rows":[["Nhóm cây","Mức nhạy","Nên dùng nước gì"],["Đuôi công, lan chi, lan ý, dương xỉ","Cao — dễ cháy đầu lá","Nước mưa hoặc nước máy để qua đêm"],["Lan, cây ưa đất chua","Cao với nước cứng, nước phèn","Nước mưa, nước lọc"],["Trầu bà, ngọc ngân, phú quý","Trung bình","Nước máy để qua đêm"],["Lưỡi hổ, ngọc bích, xương rồng","Thấp","Hầu hết loại nước sạch"],["Rau ăn lá","Trung bình","Nước sạch, không mặn, không phèn nặng"]]},{"type":"h2","text":"⏰ Nhiệt độ và giờ tưới cũng quan trọng"},{"type":"p","text":"Nước để ngoài nắng trong ống, trong thùng nhựa có thể nóng tới mức làm sốc rễ. Trước khi tưới, xả bỏ phần nước nóng đọng trong vòi. Nên tưới sáng sớm hoặc chiều mát; tưới giữa trưa nắng gắt vừa phí nước vừa dễ làm cây sốc nhiệt. Với cây trong nhà, nước để bằng nhiệt độ phòng là tốt nhất."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Tưới nước vo gạo đặc mỗi ngày** cho cây trong nhà: đất chua, có mùi, sinh ruồi nấm.","**Dùng nước giếng mùa khô mà không kiểm tra**: nhiều vùng ven biển nước giếng bị nhiễm mặn theo mùa, cây cháy lá hàng loạt chỉ sau vài lần tưới.","**Tưới ít mà tưới nhiều lần**: muối khoáng tích lại ở mặt đất; nên tưới đẫm cho nước chảy qua đáy chậu rồi chờ đất khô mới tưới tiếp.","**Đổ nước còn đọng trong đĩa lót trở lại chậu**: nước này đã mang muối khoáng rửa từ đất ra."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Nước lọc bình (nước uống đóng bình) có tưới được không?"},{"type":"p","text":"Được, nhưng tốn kém và không có lợi hơn nước máy để qua đêm. Chỉ nên dùng cho vài chậu cây rất nhạy như đuôi công khi nước nhà quá cứng."},{"type":"h3","text":"Đất mặt chậu đóng lớp váng trắng là do nước à?"},{"type":"p","text":"Thường là do muối khoáng trong nước và phân bón tích lại. Cạo bỏ lớp mặt, tưới đẫm vài lần cho nước chảy qua đáy, và giảm liều phân bón."},{"type":"h3","text":"Nước mưa hứng từ mái tôn có dùng được không?"},{"type":"p","text":"Được, nhưng bỏ đi những trận mưa đầu mùa vì cuốn theo bụi, lá mục. Lu chứa cần có nắp hoặc lưới để không thành chỗ muỗi đẻ trứng."},{"type":"p","text":"Xem thêm [tưới cây trong nhà bao lâu một lần](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach) và [lá cháy mép, khô đầu lá do đâu](/goc-cham-cay/la-chay-mep-kho-dau-la)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$tuoi-cay-bang-nuoc-gi-tot$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Rau dền (dền đỏ, dền xanh, dền cơm) mọc khỏe, ít sâu bệnh, lại thích nắng nóng — rất hợp trồng sân thượng, ban công ở miền Tây. Một thùng xốp nhỏ là đủ có rau nấu canh cho gia đình vài bữa."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Amaranthus_tricolor_4zz.jpg/960px-Amaranthus_tricolor_4zz.jpg","caption":"Rau dền trồng tại vườn nhà. Ảnh: Photo by David J. Stang, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🪴 Chuẩn bị thùng và đất"},{"type":"list","items":["Thùng xốp, chậu sâu 15–20cm, khoan nhiều lỗ thoát nước ở đáy.","Đất: đất thịt tơi trộn phân trùn quế hoặc phân chuồng hoai (khoảng 3 phần đất, 1 phần phân), thêm xơ dừa cho tơi.","Đặt nơi có nắng ít nhất 5–6 giờ/ngày."],"ordered":false},{"type":"h2","text":"🌱 Gieo hạt rau dền"},{"type":"list","items":["Hạt dền rất nhỏ: trộn hạt với ít cát khô cho dễ rải đều.","Rải đều lên mặt đất đã tưới ẩm, phủ một lớp đất mịn thật mỏng (khoảng 0,5cm) hoặc chỉ ém nhẹ tay.","Tưới bằng bình phun sương để hạt không trôi.","Hạt nảy mầm sau 3–5 ngày."],"ordered":true},{"type":"h2","text":"💧 Tưới và bón"},{"type":"list","items":["Tưới nhẹ mỗi ngày vào sáng sớm hoặc chiều mát, giữ đất ẩm, không để đọng nước.","Khi cây có 3–4 lá thật, tỉa bớt cây mọc dày, cây cách cây khoảng 5–7cm (cây tỉa ăn được).","Sau khi tỉa 1 tuần, tưới thêm nước phân hữu cơ loãng hoặc phân trùn quế hòa nước."],"ordered":false},{"type":"h2","text":"✂️ Thu hoạch"},{"type":"p","text":"Khoảng 25–30 ngày sau gieo, cây cao 20–25cm là cắt được. Cắt cách gốc 5–7cm, chừa vài lá, bón thêm ít phân hữu cơ — rau sẽ ra nhánh cho lứa sau. Dền ra hoa thì lá cứng, nên thu trước khi trổ bông."},{"type":"h2","text":"🐛 Sâu bệnh thường gặp"},{"type":"p","text":"Sâu ăn lá, rệp ở đọt non mùa khô; thối gốc khi mưa dầm đọng nước. Phần lớn xử lý bằng bắt tay, xịt nước, giữ thùng thoát nước tốt. Xem [lá thủng lỗ do sâu hay ốc](/benh-cay/sau-an-la) và [ốc sên ăn lá](/goc-cham-cay/oc-sen-an-la-ban-cong)."},{"type":"h2","text":"🌈 Chọn giống dền nào để trồng?"},{"type":"table","rows":[["Giống","Đặc điểm","Hợp với"],["Dền đỏ (dền tía)","Lá đỏ tím, nấu canh nước đỏ, lá mềm","Nấu canh, luộc"],["Dền xanh","Lá xanh, mọc nhanh, cây cao","Luộc, xào tỏi"],["Dền cơm","Lá nhỏ, thân mềm, mùi thơm nhẹ","Nấu canh tôm, canh cua"],["Dền gai","Mọc hoang, có gai ở nách lá","Không nên trồng thùng — dễ đâm tay"]]},{"type":"p","text":"Hạt giống mua ở cửa hàng vật tư nông nghiệp nên còn hạn sử dụng, bao bì nguyên. Hạt để lâu, bảo quản ẩm sẽ nảy mầm kém, mọc không đều."},{"type":"h2","text":"📅 Lịch chăm thùng dền 30 ngày"},{"type":"table","rows":[["Thời gian","Việc cần làm"],["Ngày 0","Trộn đất, tưới ẩm, gieo hạt, phủ đất mỏng"],["Ngày 3–5","Hạt nảy mầm; phun sương nhẹ, che bớt nắng trưa nếu trời quá gắt"],["Ngày 10–12","Tỉa lần 1 khi có 2–3 lá thật; cây tỉa dùng làm rau non"],["Ngày 15–18","Tỉa lần 2 để cây cách cây 5–7cm; tưới nước phân hữu cơ loãng"],["Ngày 25–30","Thu hoạch lứa đầu; bón thêm phân, giữ ẩm để ra lứa sau"]]},{"type":"h2","text":"☀️ Trồng dền theo mùa ở miền Tây"},{"type":"p","text":"Dền chịu nóng tốt nên mùa khô là mùa dền đẹp nhất, miễn là tưới đủ nước. Mùa mưa vẫn trồng được nhưng cần thùng thoát nước thật tốt, kê cao khỏi nền, và che mưa bằng tấm nhựa trong vào những tuần mưa dầm để cây không bị thối gốc, đốm lá. Trên sân thượng mái tôn nóng hắt, nên kê thùng lên kệ cao để đáy thùng không bị nung."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Gieo quá dày, không tỉa**: cây vống, thân nhỏ như cọng tăm, lá ít.","**Phủ đất quá dày**: hạt dền rất nhỏ, phủ dày là hạt không lên nổi.","**Tưới vòi mạnh lúc mới gieo**: hạt trôi dồn về một góc thùng.","**Bón phân đạm hóa học nhiều cho rau ăn tại nhà**: rau lớn nhanh nhưng giòn, dễ dập, lại không cần thiết khi đất đã có phân hữu cơ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Một thùng xốp trồng được bao nhiêu rau dền?"},{"type":"p","text":"Thùng xốp cỡ thông dụng (khoảng 60×40cm) gieo dày rồi tỉa dần, mỗi lứa thường đủ vài bữa canh cho gia đình 3–4 người. Gieo gối 2–3 thùng cách nhau 1–2 tuần sẽ có rau ăn đều."},{"type":"h3","text":"Cắt rồi dền có mọc lại không?"},{"type":"p","text":"Có, nếu cắt chừa gốc 5–7cm với vài lá và bón thêm phân. Thường thu được 2–3 lứa; sau đó cây già, ra hoa nhiều thì nên nhổ, trộn lại đất và gieo mới."},{"type":"h3","text":"Có để hạt dền làm giống được không?"},{"type":"p","text":"Được. Chọn vài cây khỏe, để trổ bông tới khi bông khô vàng, cắt bông phơi rồi vò lấy hạt đen bóng, cất nơi khô ráo trong hũ kín."},{"type":"p","text":"Trồng thêm rau khác: [rau muống thùng xốp](/goc-cham-cay/trong-rau-muong-thung-xop), [rau cải](/goc-cham-cay/trong-rau-cai-thung-xop), [rau thơm ban công](/goc-cham-cay/trong-rau-thom-ban-cong)."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$trong-rau-den-tai-nha$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Mạng xã hội đầy mẹo \"bón cây bằng đồ bỏ đi\": vỏ trứng giã nhỏ, bã cà phê, vỏ chuối ngâm nước. Có mẹo đúng một phần, có mẹo gần như vô ích, và có cách dùng còn làm chậu cây hỏng. Cùng xem từng thứ."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Cangkang_telur_ayam_sebagai_bahan_pembuatan_kompos.jpg/960px-Cangkang_telur_ayam_sebagai_bahan_pembuatan_kompos.jpg","caption":"Vỏ trứng và rác bếp dùng để ủ phân. Ảnh: Ahmad Mukhlis, CC BY 4.0, Wikimedia Commons"},{"type":"h2","text":"🥚 Vỏ trứng"},{"type":"list","items":["Chứa chủ yếu **canxi**, gần như không có đạm, lân, kali.","Vỏ nguyên mảnh nằm trong đất hàng năm không tan — cây gần như không hưởng được.","Dùng đúng: rửa sạch, phơi khô, **xay thật mịn** rồi trộn vào đất khi thay chậu hoặc cho vào thùng ủ.","Hữu ích nhất với cà chua, ớt (giảm thối đáy trái do thiếu canxi) — nhưng chỉ khi tưới đều đặn."],"ordered":false},{"type":"h2","text":"☕ Bã cà phê"},{"type":"list","items":["Có ít đạm, hơi chua; tốt khi **ủ cùng rác bếp** thành phân hữu cơ.","Rải dày trực tiếp lên mặt chậu: bã kết lại thành lớp cứng, nước khó thấm, dễ mốc xanh.","Không dùng nhiều cho cây ưa đất trung tính, cây mọng nước.","Rải mỏng quanh luống rau ngoài trời thì không sao."],"ordered":false},{"type":"h2","text":"🍌 Vỏ chuối"},{"type":"list","items":["Có **kali**, ít lân — hợp cây ra hoa, ra trái khi đã phân giải.","Chôn vỏ tươi vào chậu: thối, hôi, kéo ruồi, kiến, chuột; cây chưa kịp dùng.","\"Nước ngâm vỏ chuối\" chứa rất ít dinh dưỡng, lại dễ lên men chua.","Dùng đúng: cắt nhỏ, ủ hoai rồi mới bón; hoặc phơi khô giòn, xay vụn trộn đất."],"ordered":false},{"type":"h2","text":"📋 So sánh nhanh"},{"type":"table","rows":[["Thứ","Dinh dưỡng chính","Cách dùng đúng","Sai lầm hay gặp"],["Vỏ trứng","Canxi","Xay mịn, trộn đất, ủ","Bỏ nguyên mảnh lên mặt chậu"],["Bã cà phê","Ít đạm","Ủ cùng rác bếp","Rải dày lên chậu → mốc"],["Vỏ chuối","Kali","Ủ hoai hoặc phơi khô xay","Chôn vỏ tươi → hôi, ruồi"]]},{"type":"h2","text":"💡 Cách tốt nhất: ủ chung thành phân hữu cơ"},{"type":"p","text":"Gom vỏ trứng, bã cà phê, vỏ chuối, rau thừa vào thùng ủ cùng lá khô, sau 2–3 tháng có phân hữu cơ tơi xốp, không mùi — xem [ủ phân hữu cơ từ rác bếp tại nhà](/goc-cham-cay/u-phan-huu-co-tu-rac-bep). Cây cảnh trồng chậu vẫn cần phân bón đầy đủ đạm – lân – kali; xem [phân tan chậm hay phân hòa tan](/goc-cham-cay/phan-tan-cham-va-phan-hoa-tan) và [đọc chỉ số NPK](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan)."},{"type":"h2","text":"🔬 Vì sao \"bỏ thẳng vào chậu\" lại không hiệu quả?"},{"type":"p","text":"Cây không \"ăn\" vỏ trứng hay vỏ chuối. Rễ chỉ hút được chất dinh dưỡng ở dạng hòa tan trong nước đất. Muốn vỏ trứng, bã cà phê, vỏ chuối thành thứ cây dùng được, chúng phải được **vi sinh vật phân giải** trước. Quá trình đó cần độ ẩm, không khí và thời gian — đúng là những gì đống ủ cung cấp, còn chậu cây trong nhà thì không."},{"type":"p","text":"Khi vật liệu tươi bị vùi vào chậu, vi sinh vật phân giải chúng sẽ dùng luôn đạm có sẵn trong đất. Kết quả là trong vài tuần đầu cây còn có thể bị **thiếu đạm tạm thời**, lá nhạt màu, trong khi chậu lại có mùi và sinh ruồi."},{"type":"h2","text":"🍳 Các \"mẹo nhà bếp\" khác: đúng hay sai?"},{"type":"table","rows":[["Mẹo","Thực tế","Nên dùng không?"],["Nước vo gạo","Ít dinh dưỡng, dùng đặc dễ chua đất","Dùng loãng, thỉnh thoảng"],["Nước luộc rau (không muối)","Có ít khoáng hòa tan","Được, khi đã nguội hẳn"],["Sữa hết hạn","Dễ thối, bốc mùi, sinh nấm mốc","Không nên cho cây trong chậu"],["Bia, nước ngọt","Đường làm đất lên men, kéo kiến","Không"],["Tro bếp củi","Có kali, canxi, tính kiềm","Dùng ít, không cho cây ưa chua"],["Bã trà","Tương tự bã cà phê, ít đạm","Ủ chung, không rải dày"]]},{"type":"h2","text":"🗑️ Ủ nhanh trong thùng nhỏ ở căn hộ"},{"type":"list","items":["Dùng thùng nhựa có nắp, khoan lỗ quanh thành và đáy, đặt trên khay hứng nước.","Lót đáy lớp lá khô, xơ dừa hoặc giấy carton xé nhỏ.","Mỗi lần bỏ rác bếp (vỏ trái cây, rau thừa, vỏ trứng xay, bã cà phê) thì phủ thêm một lớp vật liệu khô tương đương.","Đảo trộn 1 tuần 1 lần cho thoáng khí; đống ủ ẩm như miếng bọt biển vắt ráo là vừa.","Có thể thêm chế phẩm vi sinh ủ phân (như Trichoderma) theo hướng dẫn trên bao để ủ nhanh và ít mùi hơn."],"ordered":true},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Đống ủ có mùi hôi thối là đang quá ướt hoặc quá nhiều rác tươi — thêm lá khô, giấy carton và đảo trộn. Mùi đất rừng dễ chịu là ủ đúng."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Bỏ vào thùng ủ thịt, cá, dầu mỡ, xương**: đống ủ hôi, kéo chuột, ruồi.","**Nghĩ rằng đồ bỏ đi thay thế được phân bón**: phân ủ chủ yếu cải tạo đất; cây vẫn cần nguồn đạm – lân – kali đều đặn.","**Dùng phân ủ chưa hoai cho chậu trong nhà**: dễ mốc trắng, ruồi nấm đất."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Vỏ trứng có trị được ốc sên không?"},{"type":"p","text":"Hiệu quả rất thấp. Ốc sên vẫn bò qua lớp vỏ trứng vụn. Bắt tay ban đêm, đặt bẫy và dọn chỗ ẩm trú ẩn hiệu quả hơn nhiều."},{"type":"h3","text":"Bã cà phê có làm đất chua không?"},{"type":"p","text":"Bã cà phê đã pha chỉ hơi chua, ảnh hưởng nhỏ. Vấn đề lớn hơn là bã kết thành lớp cứng và dễ mốc khi rải dày, chứ không phải độ chua."},{"type":"h3","text":"Phân ủ tại nhà bao lâu thì dùng được?"},{"type":"p","text":"Thường 2–3 tháng tùy vật liệu và cách đảo. Phân dùng được khi tơi vụn, màu nâu sẫm, không còn nhận ra rác ban đầu và có mùi đất."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$vo-trung-ba-ca-phe-vo-chuoi-bon-cay$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Một chậu cây xanh trên bệ cửa sổ hay góc kệ làm phòng tắm tươi mát hẳn. Độ ẩm cao là lợi thế với nhiều cây kiểng lá — nhưng ánh sáng ít và nước bắn tung tóe là hai điều phải tính."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Ecosystem_in_bathroom_-_51442495643.jpg/960px-Ecosystem_in_bathroom_-_51442495643.jpg","caption":"Cây xanh trang trí phòng tắm. Ảnh: The Urban Botanist Images, CC BY 2.0, Wikimedia Commons"},{"type":"h2","text":"🛒 Cây hợp phòng tắm"},{"type":"table","rows":[["Cây","Vì sao hợp","Lưu ý"],["Dương xỉ","Ưa ẩm cao, lá mềm mại","Cần sáng tán xạ"],["Lan ý","Ưa ẩm, chịu bóng, có hoa trắng","Nhựa gây ngứa — đặt cao"],["Trầu bà, đế vương","Chịu bóng, chịu ẩm","Lau lá định kỳ"],["Lưỡi hổ","Chịu tối, ít tưới","Hợp phòng không cửa sổ; đừng tưới nhiều"],["Lan chi","Treo đẹp, chịu ẩm","Cần sáng nhẹ"]]},{"type":"h2","text":"☀️ Phòng tắm không cửa sổ thì sao?"},{"type":"list","items":["Bóng đèn trong phòng tắm thường chỉ bật vài phút — không đủ cho cây.","Chọn lưỡi hổ và **luân phiên**: mỗi tuần đem cây ra chỗ sáng 2–3 ngày.","Hoặc gắn một bóng LED trồng cây bật theo hẹn giờ.","Không đủ sáng lâu ngày, cây vống và rụng lá dần."],"ordered":false},{"type":"h2","text":"📍 Đặt cây ở đâu cho đúng?"},{"type":"list","items":["Bệ cửa sổ, kệ cao, góc xa vòi sen — tránh nước nóng, xà phòng bắn vào lá.","Không đặt sát máy nước nóng, đèn sưởi.","Dùng chậu có đĩa lót, kê cao để đáy chậu không đọng nước, không làm ố kệ.","Giỏ treo gần cửa sổ là cách tiết kiệm chỗ."],"ordered":false},{"type":"h2","text":"💧 Tưới ít hơn bạn nghĩ"},{"type":"p","text":"Không khí ẩm làm đất khô chậm. Kiểm tra đất bằng ngón tay, chỉ tưới khi mặt đất đã khô — tưới theo thói quen dễ làm cây [thối rễ](/benh-cay/thoi-re). Mở cửa, bật quạt hút sau khi tắm để phòng thoáng, hạn chế [đốm lá do nấm](/benh-cay/dom-la-nam)."},{"type":"h2","text":"🔎 Đánh giá ánh sáng phòng tắm trong 1 phút"},{"type":"p","text":"Vào lúc 10–11 giờ sáng, tắt đèn phòng tắm rồi thử đọc một trang báo ở chỗ định đặt cây:"},{"type":"table","rows":[["Kết quả","Mức sáng","Chọn cây"],["Đọc dễ dàng, có bóng đổ rõ","Sáng tán xạ tốt","Dương xỉ, lan chi, lan ý, trầu bà"],["Đọc được nhưng hơi mờ","Sáng yếu","Trầu bà đế vương, lưỡi hổ"],["Gần như không đọc được","Quá tối","Lưỡi hổ luân phiên, hoặc thêm đèn LED trồng cây"]]},{"type":"p","text":"Kính mờ, kính dán decal vẫn cho ánh sáng tán xạ đi qua — thường là điều kiện khá tốt cho cây kiểng lá."},{"type":"h2","text":"🧴 Hóa chất tẩy rửa và cây"},{"type":"p","text":"Nước tẩy bồn cầu, thuốc tẩy javel, nước lau kính có thể làm cháy lá nếu bắn trực tiếp hoặc bay hơi nhiều trong phòng kín. Khi dọn vệ sinh bằng hóa chất mạnh, nên đưa chậu cây ra ngoài hoặc ít nhất là bật quạt hút và mở cửa. Không đặt cây ngay trên nắp bồn cầu, nơi hóa chất và nước xả hay văng lên."},{"type":"h2","text":"🗓️ Lịch chăm cây phòng tắm"},{"type":"list","items":["**Mỗi tuần**: kiểm tra đất bằng ngón tay, tưới khi lớp mặt 2–3cm đã khô; đổ nước đọng dưới đĩa.","**2 tuần một lần**: lau lá bằng khăn ẩm, xem mặt dưới lá có rệp sáp, nhện không.","**Mỗi tháng**: xoay chậu để cây mọc đều; cây ở phòng tối mang ra chỗ sáng vài ngày.","**2–3 tháng**: bón phân pha loãng (cây phòng tắm lớn chậm, cần ít phân hơn cây ngoài trời)."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Nghĩ phòng tắm ẩm thì không cần tưới**: không khí ẩm nhưng đất vẫn khô dần, chỉ là chậm hơn.","**Dùng chậu không lỗ thoát nước** cho đẹp: nước dư đọng đáy, rễ thối mà không biết.","**Đặt cây ngay đường nước vòi sen**: lá dính xà phòng, dầu gội, cháy đốm.","**Chọn cây ưa nắng như sen đá, xương rồng**: phòng tắm vừa thiếu sáng vừa ẩm, cây mọng nước thối nhanh."],"ordered":false},{"type":"h2","text":"🪝 Tận dụng chỗ trong phòng tắm nhỏ"},{"type":"p","text":"Phòng tắm nhà phố, chung cư thường chật. Vài cách đặt cây không chiếm diện tích: treo giỏ cây lan chi hoặc trầu bà ở góc trần gần cửa sổ; dùng kệ góc nhiều tầng đặt chậu nhỏ; gắn giá treo lên thanh rèm phía trên bồn tắm, tránh đường nước. Ưu tiên chậu nhựa nhẹ để giá treo không bị quá tải."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây trong phòng tắm có hút được mùi hôi không?"},{"type":"p","text":"Cây không khử mùi phòng tắm một cách đáng kể. Mùi hôi cần xử lý bằng thông gió, quạt hút và vệ sinh. Cây chủ yếu làm phòng dễ chịu hơn về mặt thị giác."},{"type":"h3","text":"Lá cây phòng tắm bị đốm đen là sao?"},{"type":"p","text":"Thường do nước đọng trên lá lâu và phòng thiếu thoáng, tạo điều kiện cho nấm. Cắt lá bị nặng, giữ lá khô, bật quạt hút sau khi tắm."},{"type":"h3","text":"Nhà có trẻ nhỏ nên chọn cây nào cho phòng tắm?"},{"type":"p","text":"Dương xỉ và lan chi được xem là an toàn hơn. Lan ý, trầu bà có nhựa gây ngứa nên đặt cao, ngoài tầm với của trẻ."},{"type":"products","title":"Cây hợp phòng tắm","slugs":["duong-xi","lan-y","luoi-ho","lan-chi","trau-ba-de-vuong-xanh"]},{"type":"p","text":"Xem thêm [trang trí bằng cây treo, giỏ treo](/goc-cham-cay/cay-treo-gio-treo-trang-tri) và [cây đặt phòng ngủ](/goc-cham-cay/cay-dat-phong-ngu)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-xanh-cho-phong-tam-nha-ve-sinh$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Hàng rào cây xanh mềm mại hơn tường gạch, che bụi, che tầm nhìn từ đường vào nhà và làm khoảng sân mát hẳn. Chọn đúng cây ngay từ đầu giúp rào kín nhanh, ít phải trồng dặm và dễ giữ dáng."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Hedge_in_Brussels.jpg/960px-Hedge_in_Brussels.jpg","caption":"Hàng rào cây xanh cắt tỉa gọn. Ảnh: IsouM, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"📏 Chọn theo chiều cao mong muốn"},{"type":"table","rows":[["Mục đích","Chiều cao","Gợi ý"],["Viền lối đi, bồn hoa","Dưới 60cm","Cây hoa bụi thấp (mai địa thảo, cúc), cỏ viền"],["Rào thấp phân khu sân","60cm–1m","Cây bụi lá nhỏ chịu cắt tỉa"],["Che chắn tầm nhìn","1,5–2m","Cau trắng trồng hàng, trúc, cây bụi lá dày"],["Rào có rau ăn","1–1,5m","Rau ngót, mồng tơi leo lưới"]]},{"type":"h2","text":"☀️ Chịu nắng hay chịu bóng?"},{"type":"p","text":"Hầu hết hàng rào nhà phố hứng nắng gắt cả ngày, nên ưu tiên cây chịu nắng. Rào dưới bóng cây lớn, hướng Bắc thì chọn cây bụi chịu bóng. Xem thêm [cây cho ban công nắng gắt](/goc-cham-cay/cay-ban-cong-nang-gat)."},{"type":"h2","text":"🪴 Trồng thế nào để rào nhanh kín?"},{"type":"list","items":["Đào rãnh rộng 40–50cm, trộn phân chuồng hoai vào đất.","Cây bụi trồng cách nhau 30–50cm; trồng so le hai hàng nếu muốn kín nhanh.","Cây dạng cau, trúc: cách nhau 50–80cm tùy cỡ.","Tưới mỗi ngày 1–2 tháng đầu cho bén rễ — xem [chăm cây công trình mới trồng](/goc-cham-cay/cham-cay-cong-trinh-moi-trong)."],"ordered":false},{"type":"h2","text":"✂️ Cắt tỉa giữ dáng"},{"type":"list","items":["**Cắt ngọn sớm** khi cây còn nhỏ để cây đâm nhánh từ gốc — rào kín chân, không bị \"trống chân\".","Cắt dáng hơi thang: chân rộng hơn ngọn để phần gốc vẫn nhận được nắng.","Mùa mưa cây mọc nhanh, tỉa 3–4 tuần một lần; mùa khô thưa hơn."],"ordered":false},{"type":"h2","text":"⚠️ Lưu ý"},{"type":"list","items":["Tránh cây có gai nhọn sát lối đi có trẻ nhỏ.","Hỏi quy định của khu dân cư về chiều cao rào, khoảng lùi.","Cây lớn cho bóng mát nên trồng cách tường, móng nhà đủ xa — xem [chọn cây công trình cho đường phố, khu dân cư](/goc-cham-cay/chon-cay-cong-trinh-duong-pho-san-truong)."],"ordered":false},{"type":"h2","text":"🌳 So sánh vài loại cây làm rào phổ biến"},{"type":"table","rows":[["Kiểu rào","Mau kín","Công cắt tỉa","Ghi chú"],["Cây bụi lá nhỏ chịu cắt","Trung bình","Nhiều — 3–4 tuần/lần mùa mưa","Tạo khối gọn, vuông vức đẹp"],["Cau trắng trồng hàng","Nhanh theo chiều cao","Ít — chỉ cắt tàu lá khô","Chân rào thưa, có thể trồng thêm cây bụi thấp"],["Trúc, tre cảnh","Nhanh","Trung bình","Rễ lan mạnh — nên trồng trong bồn hoặc có tấm chắn rễ"],["Cây hoa bụi (mai địa thảo…)","Nhanh ở chiều thấp","Trung bình","Hợp viền thấp, có hoa quanh năm"],["Dây leo trên lưới","Nhanh","Trung bình","Tốn ít diện tích, hợp nhà phố hẹp"]]},{"type":"h2","text":"📐 Tính số cây cần mua"},{"type":"p","text":"Số cây cho mỗi hàng ≈ chiều dài rào chia khoảng cách trồng, cộng thêm 1. Ví dụ rào dài 10m, cây bụi trồng cách 40cm: 10 ÷ 0,4 + 1 = 26 cây một hàng; trồng so le hai hàng thì khoảng 50 cây. Nên mua dư 5–10% để trồng dặm cây chết trong tháng đầu."},{"type":"note","title":"💡 Mẹo khi đặt cây số lượng lớn","text":"Với công trình, dự án cần số lượng lớn và đồng đều kích cỡ, nên đặt trước để nhà vườn chọn lô cây cùng chiều cao, cùng tuổi — hàng rào lên sẽ đều ngay từ đầu."},{"type":"h2","text":"🌧️ Chăm hàng rào theo mùa ở miền Tây"},{"type":"list","items":["**Đầu mùa mưa** là thời điểm trồng tốt nhất: cây bén rễ nhanh, đỡ công tưới.","**Mùa mưa**: cây mọc mạnh, cắt tỉa thường xuyên; khơi rãnh thoát nước để gốc không ngập lâu.","**Mùa khô**: tưới đều 2–3 ngày/lần với rào đã ổn định, phủ gốc bằng rơm, xơ dừa để giữ ẩm.","**Vùng nhiễm mặn mùa khô**: kiểm tra nước tưới — xem [phòng mặn cho cây sân vườn](/goc-cham-cay/phong-man-cho-cay-san-vuon)."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Để cây cao rồi mới cắt ngọn**: chân rào trống, không thể sửa lại cho kín.","**Trồng quá sát tường, sát móng**: rễ phát triển chèn móng, ẩm tường, khó cắt tỉa mặt trong.","**Trồng một loại duy nhất cho cả dãy dài**: khi gặp sâu bệnh, cả hàng rào bị cùng lúc; xen 2 loại cây hợp nhau giúp rào bền hơn.","**Bón ít, tỉa nhiều**: cây bị cắt liên tục cần được bón phân định kỳ mới ra lá dày."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Bao lâu thì hàng rào cây bụi kín?"},{"type":"p","text":"Tùy loại cây và cỡ cây trồng ban đầu; với cây bụi chịu cắt trồng so le và chăm đều, thường sau một mùa mưa rào đã khá kín. Trồng cây cỡ lớn hơn thì kín nhanh hơn nhưng chi phí cao hơn."},{"type":"h3","text":"Rào cây có cần làm thêm lưới, hàng rào sắt phía trong không?"},{"type":"p","text":"Nhà cần an ninh nên có lưới B40 hoặc hàng rào sắt thấp phía trong để cây phủ lên. Cây che tầm nhìn và tạo cảnh quan, còn lưới mới thực sự ngăn người và chó mèo."},{"type":"h3","text":"Cây rào bị vàng lá, rụng lá chân thì làm sao?"},{"type":"p","text":"Thường do thiếu nắng ở chân (cắt dáng ngọn rộng hơn chân), ngập úng hoặc thiếu phân. Cắt lại dáng hình thang, khơi thoát nước, bón phân hữu cơ quanh gốc."},{"type":"products","title":"Cây sân vườn, công trình tại vườn","slugs":["cau-trang","mai-dia-thao","bang-dai-loan","chuoi-re-quat"]},{"type":"p","text":"Cần số lượng lớn cho dự án: [gửi yêu cầu báo giá sỉ](/bao-gia-si)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$chon-cay-lam-hang-rao-nha-pho$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"\"Hướng Đông đặt cây gì, hướng Tây đặt cây gì?\" là câu hỏi rất nhiều người gửi tới shop. Bài này tóm tắt quan niệm phong thủy dân gian về hướng — và quan trọng không kém: **mỗi hướng nhận bao nhiêu nắng**, vì cây hợp hướng mà thiếu sáng thì cũng không đẹp nổi."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Bright_windowsill_%28Unsplash%29.jpg/960px-Bright_windowsill_%28Unsplash%29.jpg","caption":"Cây cảnh đặt cạnh cửa sổ có nắng"},{"type":"h2","text":"🍀 Hướng và ngũ hành theo quan niệm dân gian"},{"type":"table","rows":[["Hướng","Hành","Màu cây thường được chọn","Gợi ý cây"],["Đông, Đông Nam","Mộc","Lá xanh","Trầu bà đế vương xanh, lan ý, dương xỉ"],["Nam","Hỏa","Lá đỏ, hồng","Phú quý, vạn lộc, đế vương đỏ"],["Tây, Tây Bắc","Kim","Lá trắng, bạc","Ngân hậu, ngọc ngân, bạch mã"],["Bắc","Thủy","Lá xanh đậm, trắng","Lưỡi hổ, lan ý"],["Tây Nam, Đông Bắc, trung tâm","Thổ","Lá vàng, nâu","Đế vương vàng, đế vương nâu"]]},{"type":"p","text":"Đây là quan niệm dân gian để tham khảo khi bày trí, không có cơ sở khoa học. Xem thêm [chọn cây theo mệnh ngũ hành](/goc-cham-cay/chon-cay-theo-menh-ngu-hanh)."},{"type":"h2","text":"☀️ Ánh sáng thật của từng hướng (ở Việt Nam)"},{"type":"table","rows":[["Cửa sổ hướng","Ánh sáng","Cây hợp"],["Đông","Nắng sáng dịu, hết nắng trước trưa","Hầu hết cây kiểng lá, cây ra hoa"],["Nam","Sáng nhiều, mùa khô có nắng xiên","Cây ưa sáng; cây chịu bóng đặt lùi vào trong"],["Tây","Nắng chiều gắt, nóng","Cây chịu nắng; cây lá mỏng dễ cháy"],["Bắc","Sáng tán xạ, ít nắng trực tiếp","Cây chịu bóng"]]},{"type":"h2","text":"🛠️ Kết hợp hai điều"},{"type":"list","items":["Chọn hướng / vị trí theo ý muốn phong thủy.","Đo ánh sáng thực tế ở chỗ đó (xem [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)).","Trong các cây \"hợp hướng\", chọn loài chịu được ánh sáng đó.","Ví dụ: muốn cây lá đỏ (Hỏa) ở cửa sổ hướng Tây nắng gắt → đặt lùi 1–2m, có rèm, tránh [cháy lá do nắng](/benh-cay/chay-la-do-nang)."],"ordered":false},{"type":"h2","text":"⚠️ Những điều nên tránh"},{"type":"list","items":["Đừng vì \"hợp hướng\" mà đặt cây ưa bóng sát cửa kính nắng chiều.","Cây héo, cây chết nên thay sớm — theo dân gian là điều không tốt, theo thực tế là chỗ sinh sâu bệnh.","Xem thêm [những điều kiêng kỵ khi đặt cây trong nhà](/goc-cham-cay/kieng-ky-khi-dat-cay-trong-nha)."],"ordered":false},{"type":"h2","text":"📍 Vị trí trong nhà quan trọng không kém hướng"},{"type":"table","rows":[["Vị trí","Điều kiện thực tế","Gợi ý"],["Cạnh cửa chính","Gió lùa, người qua lại, có thể có nắng xiên","Cây dáng thẳng, lá dày: kim tiền, lưỡi hổ, trầu bà đế vương"],["Phòng khách xa cửa sổ","Sáng yếu, có máy lạnh","Ngân hậu, bạch mã, trầu bà đế vương"],["Bàn làm việc","Đèn trần, không khí khô","Cây nhỏ chịu bóng: ngọc ngân, lưỡi hổ mini"],["Ban công hướng Tây","Nắng chiều gắt, nóng","Cây chịu nắng; cây lá màu đặt lùi trong bóng"],["Phòng ngủ","Ít sáng, đóng kín ban ngày","1–2 chậu nhỏ chịu bóng, không đặt quá nhiều"]]},{"type":"h2","text":"🧭 Cách xác định hướng chính xác"},{"type":"p","text":"Đứng trong nhà, quay mặt ra cửa sổ hoặc cửa chính, mở ứng dụng la bàn trên điện thoại để biết hướng. Cũng có thể quan sát: nắng sáng chiếu vào cửa nào thì đó là phía Đông, nắng chiều chiếu vào cửa nào là phía Tây. Ở Việt Nam, cửa hướng Nam vào mùa khô thường nhận nắng xiên khá sâu, còn hướng Bắc chủ yếu chỉ có ánh sáng tán xạ."},{"type":"h2","text":"🔄 Khi cây \"hợp hướng\" không hợp ánh sáng"},{"type":"list","items":["**Muốn cây lá đỏ ở góc tối**: chọn loại phú quý, vạn lộc chịu bóng khá, đặt gần đèn, mỗi tháng đưa ra chỗ sáng vài ngày để giữ màu.","**Muốn cây lá bạc (hành Kim) ở cửa sổ Tây nắng gắt**: lùi chậu vào trong, có rèm mỏng.","**Không có chỗ sáng nào**: dùng đèn LED trồng cây hẹn giờ — xem [đèn LED trồng cây trong nhà](/goc-cham-cay/den-led-trong-cay-trong-nha)."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đặt quá nhiều cây trong một phòng nhỏ** vì \"càng nhiều càng tốt\": phòng bí, khó chăm, cây tranh sáng.","**Chọn cây hoàn toàn theo màu lá** mà bỏ qua điều kiện chăm: cây đẹp tuần đầu rồi héo dần.","**Để cây giả thay cây thật** ở chỗ tối: theo quan niệm dân gian vẫn được, nhưng nhớ lau bụi thường xuyên."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Có nhất thiết phải đặt cây theo hướng không?"},{"type":"p","text":"Không. Đây là quan niệm dân gian để tham khảo khi bày trí. Điều quyết định cây có đẹp, có khỏe hay không vẫn là ánh sáng, nước và cách chăm."},{"type":"h3","text":"Một phòng nên đặt bao nhiêu cây?"},{"type":"p","text":"Không có con số chuẩn. Phòng khách 15–20m² thường đặt 1 cây lớn ở góc và 1–2 cây nhỏ trên kệ, bàn là vừa mắt, dễ chăm."},{"type":"h3","text":"Cây chết có phải điềm xấu không?"},{"type":"p","text":"Theo dân gian nên thay sớm. Theo thực tế, cây chết là dấu hiệu chỗ đặt hoặc cách chăm chưa hợp — tìm hiểu nguyên nhân trước khi mua cây mới để cây sau không bị lại."},{"type":"products","title":"Cây theo màu lá","slugs":["trau-ba-de-vuong-xanh","phu-quy","ngan-hau","luoi-ho","trau-ba-de-vuong-vang"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$dat-cay-theo-huong-nha-phong-thuy$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Lặt lá mai là việc mà nhà nào chưng mai vàng ở miền Nam cũng hồi hộp mỗi năm: lặt sớm quá hoa nở trước Tết, lặt muộn quá thì mùng 1 mai vẫn còn nụ. Không có ngày \"chuẩn\" cho mọi cây, nhưng có những nguyên tắc nhà vườn vẫn dùng."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Ochna_integerrima_02.JPG/960px-Ochna_integerrima_02.JPG","caption":"Mai vàng nở hoa ngày Tết. Ảnh: Prenn, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"📅 Lặt lá mai vào ngày nào?"},{"type":"list","items":["Thông thường: khoảng **giữa tháng Chạp âm lịch** (ngày 10–20 tháng Chạp), tức **25–35 ngày trước Tết**.","**Trời nóng, nắng nhiều**: mai nở nhanh — lặt muộn hơn (gần 25 ngày).","**Trời se lạnh, âm u**: mai nở chậm — lặt sớm hơn (gần 35 ngày).","Cây trồng đất khỏe nở nhanh hơn cây trồng chậu, cây già cỗi.","Quan sát nụ: nụ đã to bằng hạt tiêu tới hạt đậu xanh, vảy nụ căng là cây sẵn sàng."],"ordered":false},{"type":"h2","text":"🛠️ Chuẩn bị trước khi lặt"},{"type":"list","items":["1–2 tuần trước lặt: bón phân có lân, kali để nụ chắc, hoa bền màu.","Vài ngày trước lặt: giảm tưới cho lá hơi rũ, lặt dễ và cây \"đánh thức\" nụ khi tưới lại.","Cắt tỉa cành khô, cành sâu bệnh trước."],"ordered":false},{"type":"h2","text":"🍃 Cách lặt lá"},{"type":"list","items":["Dùng tay bẻ ngang cuống lá, **chừa lại một đoạn cuống ngắn**, không giật làm tróc vỏ, gãy nụ.","Lặt sạch hết lá trên cây (trừ khi muốn giữ vài lá non ở ngọn theo ý thích).","Ngay sau lặt: tưới đẫm để cây kích nụ phát triển.","Có thể phun nước rửa sạch thân cành."],"ordered":true},{"type":"h2","text":"🔍 Theo dõi và điều chỉnh sau lặt"},{"type":"table","rows":[["Tình trạng nụ","Cách xử lý dân gian thường dùng"],["Nụ lớn nhanh, có thể nở sớm","Che bớt nắng, giảm tưới, đưa vào chỗ mát"],["Nụ chậm, có thể nở muộn","Tưới nước ấm, tăng nắng, bón thêm phân kali theo hướng dẫn"],["Nụ khô, rụng","Kiểm tra sâu bệnh, thiếu nước, nắng gắt"]]},{"type":"note","title":"💡 Lưu ý","text":"Thời gian trên là kinh nghiệm phổ biến của nhà vườn miền Nam, thay đổi theo giống mai, tuổi cây và thời tiết từng năm. Cây mai lâu năm có nhật ký các năm trước là tài liệu chính xác nhất cho chính cây đó."},{"type":"h2","text":"🌱 Sau Tết chăm mai thế nào?"},{"type":"p","text":"Hoa tàn thì cắt bỏ hết nụ, hoa, trái non; tỉa cành, bón phân hữu cơ để cây ra lá mới hồi sức. Xem thêm [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet) và [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet)."},{"type":"h2","text":"📒 Ghi nhật ký mai từng năm"},{"type":"p","text":"Nhà vườn lâu năm thường ghi lại cho từng cây: ngày lặt lá, thời tiết sau lặt, ngày nụ nhú vàng, ngày hoa nở rộ. Chỉ sau 2–3 năm, bạn sẽ biết cây nhà mình cần bao nhiêu ngày từ lúc lặt tới lúc nở — chính xác hơn mọi lời khuyên chung."},{"type":"table","rows":[["Mục ghi","Ví dụ"],["Ngày lặt (âm lịch)","15 tháng Chạp"],["Thời tiết 2 tuần sau lặt","Nắng nóng, ít mây"],["Ngày nụ hé vàng","25 tháng Chạp"],["Ngày nở rộ","Mùng 1 Tết"],["Điều chỉnh năm sau","Lặt muộn hơn 2–3 ngày nếu năm đó lại nóng"]]},{"type":"h2","text":"🪴 Mai trồng chậu khác mai trồng đất"},{"type":"list","items":["**Mai chậu** khô đất nhanh, rễ ít hơn: ngừng tưới trước lặt ngắn hơn (chỉ 2–3 ngày), theo dõi để lá rũ nhẹ chứ không héo khô.","**Mai trồng đất** rễ sâu, khó làm lá rũ bằng cách ngừng tưới; nhà vườn thường lặt đúng ngày mà không cần \"xiết nước\" nhiều.","**Mai cổ thụ, cây già** ra nụ chậm hơn cây tơ đang sung sức, thường cần lặt sớm hơn vài ngày."],"ordered":false},{"type":"h2","text":"🌡️ Thời tiết bất thường thì làm gì?"},{"type":"p","text":"Có năm cuối tháng Chạp nắng nóng bất thường, có năm lại âm u lạnh kéo dài. Theo dõi nụ mỗi ngày sau lặt: nụ bung vảy, lộ màu vàng sớm hơn dự tính 7–10 ngày là có nguy cơ nở sớm; nụ vẫn xanh chặt khi Tết chỉ còn khoảng 10 ngày là có nguy cơ nở muộn. Điều chỉnh từ từ bằng che nắng, tưới, chỗ đặt; tránh các cách \"kích\" quá mạnh làm nụ khô, rụng."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Giật lá cả cuống**: tróc vỏ, gãy mầm nụ ở nách lá.","**Tưới phân đạm sau lặt**: cây đâm lá non thay vì nở hoa.","**Chép y ngày lặt của nhà hàng xóm**: khác giống, khác tuổi cây, khác chỗ trồng nên kết quả khác.","**Phơi mai chậu giữa nắng gắt sau khi lặt** khi đất khô: nụ dễ bị khô, rụng."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Mai không có nụ thì lặt lá có ra hoa không?"},{"type":"p","text":"Không. Lặt lá chỉ giúp nụ có sẵn phát triển. Mai không có nụ thường do bón, tỉa chưa đúng trong năm, hoặc cây yếu — năm nay nên giữ lá cho cây khỏe, chuẩn bị cho năm sau."},{"type":"h3","text":"Có nên lặt lá mai mua ở chợ hoa Tết không?"},{"type":"p","text":"Mai mua chợ hoa thường đã được nhà vườn lặt và canh ngày nở. Chỉ cần đặt chỗ thoáng, tưới đều, không cần lặt thêm."},{"type":"h3","text":"Sau Tết lá mai có mọc lại không?"},{"type":"p","text":"Có. Sau khi cắt bỏ hoa tàn và bón phân, cây sẽ ra lứa lá non mới trong vài tuần."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$lat-la-mai-vang-truoc-tet$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Sáng ra thấy lá cây lỗ chỗ như bị ai bấm lỗ, mép lá khuyết từng mảng — mà nhìn mãi không thấy con gì. Thủ phạm thường trốn kỹ ban ngày. Chỉ cần đọc dấu vết là đoán được khá chính xác, khỏi phun thuốc bừa."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Rumex_acetosa_var._hortensis_%28Gem%C3%BCse_Ampfer%29_mit_einem_Raupen_%28Ametastegia_equiseti%29_Befall-2-Josef_Schlaghecken.jpg/960px-Rumex_acetosa_var._hortensis_%28Gem%C3%BCse_Ampfer%29_mit_einem_Raupen_%28Ametastegia_equiseti%29_Befall-2-Josef_Schlaghecken.jpg","caption":"Lá bị sâu ăn khuyết, thủng nhiều lỗ. Ảnh: Schlaghecken Josef, CC BY 4.0, Wikimedia Commons"},{"type":"h2","text":"🔍 Đọc dấu vết để đoán thủ phạm"},{"type":"table","rows":[["Dấu vết trên cây","Thủ phạm thường gặp","Ăn lúc nào"],["Lỗ to, mép lá khuyết nham nhở, có viên phân đen dưới lá","Sâu ăn lá (sâu non của bướm, ngài)","Ngày lẫn đêm, trốn mặt dưới lá"],["Lỗ to giữa lá, có vệt nhớt khô sáng bóng","Ốc sên, sên trần","Ban đêm, sau mưa"],["Nhiều lỗ nhỏ tròn li ti như kim châm","Bọ nhảy, bọ cánh cứng nhỏ","Ban ngày, nhảy đi khi chạm"],["Lá bị cắt rời từng mảnh hình bán nguyệt đều","Ong cắt lá","Ban ngày — ít hại, không cần xử lý"],["Đường ngoằn ngoèo trắng bạc trong lá","Sâu vẽ bùa (không phải lỗ thủng)","—"]]},{"type":"h2","text":"🔦 Bắt quả tang vào ban đêm"},{"type":"p","text":"Khoảng 8–9 giờ tối, cầm đèn pin soi mặt dưới lá, đọt non, mép chậu và đáy chậu. Ốc sên, sâu ăn đêm sẽ lộ diện. Bắt tay bỏ vào hũ nước muối là cách diệt sạch, an toàn nhất cho cây trong nhà và rau."},{"type":"h2","text":"🛠️ Xử lý theo từng thủ phạm"},{"type":"h3","text":"Sâu ăn lá"},{"type":"list","items":["Bắt tay sâu buổi sáng sớm, kiểm tra mặt dưới lá, nơi có ổ trứng thì ngắt bỏ cả lá.","Rau và cây ăn trái bị nhiều: dùng chế phẩm sinh học trị sâu (như chế phẩm vi khuẩn Bt) theo hướng dẫn trên bao bì.","Xem chi tiết ở [sâu ăn lá](/benh-cay/sau-an-la)."],"ordered":false},{"type":"h3","text":"Ốc sên, sên trần"},{"type":"p","text":"Dọn lá mục, gạch đá ẩm quanh chậu; rải vòng tro bếp hoặc cát khô quanh gốc; đặt bẫy bằng lá rau úp sát đất để sáng ra gom. Hướng dẫn kỹ ở bài [ốc sên ăn lá cây ban công](/goc-cham-cay/oc-sen-an-la-ban-cong)."},{"type":"h3","text":"Bọ nhảy, bọ cánh cứng nhỏ"},{"type":"p","text":"Hay gặp trên rau cải. Che lưới mịn cho luống rau từ lúc gieo, xới đất phơi nắng trước khi trồng vụ mới, không trồng cải liên tục trên cùng một chỗ."},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Ưu tiên bắt tay, bẫy, che lưới. Nếu phải dùng thuốc trên rau: chọn thuốc có đăng ký cho đúng loại sâu, đọc kỹ nhãn, tuân thủ thời gian cách ly trước khi hái. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."},{"type":"h2","text":"❓ Lá thủng rồi có lành lại không?"},{"type":"p","text":"Không — lỗ đã thủng thì giữ nguyên, nhưng cây vẫn quang hợp bằng phần lá còn lại. Chỉ cần diệt được thủ phạm, lá mới ra sẽ lành lặn. Lá bị ăn quá nửa có thể cắt bỏ cho cây gọn đẹp."},{"type":"h2","text":"🧭 Ba câu hỏi để đoán nhanh"},{"type":"list","items":["**Lỗ to hay nhỏ?** Lỗ li ti như kim châm thường do bọ nhảy, bọ cánh cứng nhỏ; lỗ to, khuyết mép thường do sâu, ốc sên.","**Có dấu vết gì quanh lỗ?** Phân đen viên nhỏ là sâu; vệt nhớt khô sáng bóng là ốc sên; không có gì và mép lỗ đều là côn trùng có cánh.","**Lá non hay lá già?** Ốc sên, sâu non thích lá non mềm; lá già thủng lỗ có viền vàng, nâu thì có thể là đốm bệnh đã khô rụng — không phải côn trùng."],"ordered":true},{"type":"h2","text":"🍂 Khi lỗ thủng không phải do côn trùng"},{"type":"p","text":"Có những đốm bệnh do nấm, vi khuẩn khi khô sẽ rụng phần mô giữa, để lại lỗ thủng tròn có viền nâu hoặc vàng — gọi là \"thủng lá do bệnh\". Dấu hiệu nhận biết: trước khi thủng có đốm màu, quanh lỗ có quầng vàng, và không có dấu vết ăn. Trường hợp này cần xử lý như bệnh đốm lá: cắt lá bệnh, giữ lá khô, tưới gốc. Xem [đốm lá do nấm](/benh-cay/dom-la-nam)."},{"type":"p","text":"Ngoài ra, mưa đá, gió mạnh làm lá va vào nhau cũng gây rách, thủng — nhưng vết rách thường dài, không đều và xuất hiện đồng loạt sau cơn mưa giông."},{"type":"h2","text":"🌿 Mức độ nào cần xử lý?"},{"type":"table","rows":[["Mức hại","Gợi ý xử lý"],["Vài lá có lỗ, cây vẫn ra lá mới bình thường","Bắt tay, theo dõi — chưa cần phun gì"],["Nhiều lá non bị ăn, ngọn bị cụt","Bắt tay buổi tối, đặt bẫy, che lưới cho rau"],["Cả luống rau bị ăn trụi trong vài ngày","Kết hợp bắt tay với chế phẩm sinh học; cân nhắc gieo lại"]]},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Phun thuốc ban ngày cho ốc sên, sâu ăn đêm**: chúng đang trốn dưới chậu, dưới lá mục — thuốc không chạm tới.","**Dùng một loại thuốc cho mọi thủ phạm**: thuốc trị sâu không có tác dụng với ốc sên và ngược lại.","**Để lá mục, gạch đá ẩm quanh chậu**: đó là \"nhà\" của ốc sên, sên trần."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Lá cây trong nhà cũng bị thủng lỗ là do đâu?"},{"type":"p","text":"Cây trong nhà ít bị sâu ăn lá. Lỗ thủng thường do ốc sên theo chậu từ nhà vườn về, hoặc đốm bệnh khô rụng. Kiểm tra đáy chậu và soi đèn vào buổi tối vài hôm."},{"type":"h3","text":"Gà, chim có ăn sâu giúp không?"},{"type":"p","text":"Có, với vườn rộng thả gà là cách diệt sâu tự nhiên tốt — nhưng gà cũng mổ rau non, nên chỉ thả khi rau đã lớn hoặc có lưới che luống."},{"type":"h3","text":"Có nên cắt hết lá bị thủng?"},{"type":"p","text":"Không cần. Lá còn trên một nửa diện tích xanh vẫn giúp cây quang hợp. Chỉ cắt lá bị ăn quá nửa hoặc lá có ổ trứng, sâu non."},{"type":"p","text":"Xem thêm [trồng rau cải thùng xốp không cần thuốc](/goc-cham-cay/trong-rau-cai-thung-xop) và [thư viện bệnh cây](/benh-cay)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$la-cay-bi-thung-lo-nguyen-nhan$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Cây đặt văn phòng thường đẹp được vài tuần đầu rồi bắt đầu khô mép lá, rụng lá, đất lúc khô nứt lúc úng. Nguyên nhân hầu như không phải cây \"không hợp phòng\", mà là ba thứ: **gió máy lạnh, không khí khô và lịch tưới thất thường**."},{"type":"image","file":"https://cdn.stocksnap.io/img-thumbs/960w/UDIGU0A2SN.jpg","caption":"Cây xanh trên bàn làm việc văn phòng"},{"type":"h2","text":"🔎 Máy lạnh ảnh hưởng cây thế nào?"},{"type":"list","items":["Máy lạnh hút ẩm: độ ẩm phòng có thể xuống thấp, lá thoát nước nhanh, mép lá khô cháy.","Gió lạnh thổi thẳng làm lá cây nhiệt đới bị sốc, quăn, rụng.","Không khí khô là điều kiện ưa thích của [nhện đỏ](/benh-cay/nhen-do).","Cuối tuần, ngày lễ máy lạnh tắt, phòng kín nóng bí — cây chịu chênh lệch lớn."],"ordered":false},{"type":"h2","text":"📍 Đặt cây ở đâu trong văn phòng?"},{"type":"list","items":["Cách cửa gió máy lạnh **ít nhất 2m**, không nằm trên đường gió thổi.","Gần cửa sổ có rèm là tốt nhất; cây xa cửa sổ cần chọn loại chịu bóng.","Bàn làm việc dưới đèn huỳnh quang, LED: hợp cây nhỏ chịu bóng.","Tránh đặt trên nóc máy in, cạnh máy tính tỏa nhiệt."],"ordered":false},{"type":"p","text":"Xem thêm [cây văn phòng chịu bóng theo từng vị trí](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi)."},{"type":"h2","text":"💧 Tưới cây văn phòng thế nào?"},{"type":"list","items":["Tưới khi mặt đất khô 2–3cm — thử bằng ngón tay, không tưới theo lịch cố định.","Phòng lạnh đất khô chậm hơn ngoài trời, cây thường cần ít nước hơn bạn nghĩ.","Giao cho **một người** phụ trách tưới, tránh mỗi người tưới một ít làm cây úng.","Trước kỳ nghỉ dài: tưới đẫm, dời cây xa cửa sổ nắng — xem [cách giữ cây khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang)."],"ordered":false},{"type":"h2","text":"💦 Tăng độ ẩm quanh cây"},{"type":"list","items":["Đặt chậu lên **khay sỏi có nước** (đáy chậu không chạm nước).","Xếp nhiều cây gần nhau tạo vùng ẩm chung.","Phun sương nhẹ buổi sáng cho cây lá mỏng; cây lá dày như lưỡi hổ không cần.","Lau lá bằng khăn ẩm 2 tuần một lần — vừa sạch bụi vừa kiểm tra nhện ([lau lá đúng cách](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la))."],"ordered":false},{"type":"h2","text":"🛒 Cây nào hợp phòng máy lạnh?"},{"type":"table","rows":[["Cây","Vì sao hợp"],["Lưỡi hổ","Lá dày, chịu khô, ít tưới"],["Ngân hậu, bạch mã","Chịu bóng, chịu máy lạnh khá"],["Trầu bà đế vương","Lá dày bóng, bền"],["Lan ý","Chịu bóng; cần đất ẩm đều, phun sương"],["Đuôi công","Đẹp nhưng nhạy không khí khô — cần khay sỏi nước"]]},{"type":"h2","text":"🩺 Đọc dấu hiệu trên lá cây văn phòng"},{"type":"table","rows":[["Dấu hiệu","Nguyên nhân thường gặp","Cách sửa"],["Khô cháy mép, đầu lá","Không khí khô, gió máy lạnh, nước máy nhiều clo","Dời xa cửa gió, khay sỏi nước, dùng nước để qua đêm"],["Lá vàng từ dưới lên, đất ẩm lâu","Tưới quá nhiều","Giãn lịch tưới, kiểm tra rễ"],["Lá rũ, đất khô nứt","Quên tưới sau kỳ nghỉ","Ngâm chậu vào xô nước 20–30 phút cho đất hút lại"],["Lá lấm tấm chấm vàng, có tơ mảnh","Nhện đỏ","Lau lá, phun nước mặt dưới lá, cách ly cây"],["Lá quăn, rụng hàng loạt sau khi dời chỗ","Sốc môi trường","Giữ nguyên chỗ mới, tưới vừa phải, chờ 2–3 tuần"]]},{"type":"h2","text":"📋 Phân công chăm cây trong văn phòng"},{"type":"p","text":"Nhiều văn phòng cây chết không phải vì thiếu người chăm mà vì quá nhiều người cùng chăm. Một bảng chăm cây đơn giản dán cạnh khu pantry giúp mọi việc rõ ràng:"},{"type":"list","items":["**Một người phụ trách chính** và một người thay khi vắng.","Ghi tên cây, vị trí, **khoảng cách giữa hai lần tưới gợi ý** (ví dụ lưỡi hổ 10–14 ngày, lan ý 4–5 ngày) — vẫn kiểm tra đất trước khi tưới.","Cột đánh dấu ngày đã tưới để người khác không tưới chồng.","Mỗi tháng một lần lau lá, xoay chậu, kiểm tra sâu bệnh."],"ordered":false},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Với văn phòng có nhiều chậu lớn ở sảnh, lễ tân, nên dùng chậu có ngăn chứa nước dưới đáy (chậu tự tưới) kèm phao báo mực nước — giảm nhiều rủi ro quên tưới hay tưới quá tay."},{"type":"h2","text":"🗓️ Trước và sau kỳ nghỉ Tết, nghỉ lễ dài"},{"type":"list","items":["Tưới đẫm 1 ngày trước khi nghỉ, đổ nước dư dưới đĩa.","Dời cây xa cửa kính hứng nắng — văn phòng tắt máy lạnh dễ nóng bí.","Gom các chậu nhỏ đứng gần nhau, đặt trên khay sỏi có nước.","Sau kỳ nghỉ: kiểm tra đất trước khi tưới, không tưới bù quá nhiều cùng lúc."],"ordered":true},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đặt cây ngay dưới cửa gió** vì \"chỗ đó mát\": lá bị sốc lạnh và khô nhanh nhất.","**Đổ trà, cà phê thừa vào chậu**: đường, sữa làm đất chua, lên men, kéo kiến và ruồi.","**Dùng chậu không lỗ, không đĩa** cho đẹp bàn: nước dư không có đường thoát.","**Bón phân nhiều cho cây chậm lớn**: cây trong phòng lạnh lớn chậm, phân dư làm cháy rễ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Máy lạnh chạy cả ngày có làm cây chết không?"},{"type":"p","text":"Bản thân máy lạnh không làm cây chết. Vấn đề là gió thổi thẳng và độ ẩm thấp. Đặt cây xa cửa gió và tăng ẩm cục bộ là cây vẫn sống tốt nhiều năm."},{"type":"h3","text":"Đèn văn phòng có đủ sáng cho cây không?"},{"type":"p","text":"Đủ cho cây chịu bóng đặt gần đèn và gần cửa sổ. Cây ở giữa phòng xa cửa sổ nên chọn loại chịu bóng mạnh và luân phiên đưa ra chỗ sáng."},{"type":"h3","text":"Có nên thuê dịch vụ chăm cây văn phòng?"},{"type":"p","text":"Với văn phòng nhiều cây lớn, đặt ở sảnh, có thể cân nhắc. Với vài chậu nhỏ, chọn đúng cây chịu bóng và phân công một người chăm là đủ."},{"type":"products","title":"Cây hợp phòng máy lạnh","slugs":["luoi-ho","ngan-hau","trau-ba-de-vuong-xanh","bach-ma-hoang-tu","lan-y"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cham-cay-trong-phong-may-lanh$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Mồng tơi là rau quen thuộc của mâm cơm miền Tây — nấu canh cua, canh tôm. Cây leo nhanh, sống lâu, chỉ cần một góc nắng và vài cọc làm giàn là có rau ăn liên tục cả năm, lại thành màn xanh che nắng cho ban công."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Basella_alba_leaves_27052014.jpg/960px-Basella_alba_leaves_27052014.jpg","caption":"Mồng tơi leo giàn. Ảnh: Joydeep, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"🌱 Trồng bằng hạt hoặc giâm ngọn"},{"type":"list","items":["**Hạt**: vỏ cứng, nên ngâm nước ấm 6–8 tiếng (qua đêm) rồi gieo sâu 1cm; nảy mầm sau khoảng 1 tuần.","**Giâm ngọn**: cắt ngọn mồng tơi mua chợ dài 15–20cm, tỉa bớt lá, cắm vào đất ẩm nơi râm mát; vài ngày là ra rễ."],"ordered":false},{"type":"h2","text":"🪴 Chậu, đất và chỗ trồng"},{"type":"list","items":["Chậu hoặc thùng sâu 25cm trở lên, có lỗ thoát nước; trồng sát lan can, hàng rào.","Đất tơi giàu mùn, trộn phân chuồng hoai hoặc phân trùn quế.","Nắng nhiều thì lá dày, xanh; thiếu nắng thân mảnh, lá nhỏ."],"ordered":false},{"type":"h2","text":"🪜 Làm giàn"},{"type":"p","text":"Khi cây cao 15–20cm, cắm cọc tre hoặc căng lưới, dây cho cây leo. Dây mồng tơi tự quấn; lúc đầu quấn nhẹ thân vào cọc theo chiều kim đồng hồ để cây bám. Ban công cao tầng nhiều gió nên buộc giàn chắc."},{"type":"h2","text":"💧 Tưới và bón"},{"type":"list","items":["Mồng tơi thích ẩm: mùa nắng tưới mỗi ngày, ngày nắng gắt tưới cả sáng chiều.","Mỗi 2 tuần tưới phân hữu cơ hòa nước hoặc rắc phân trùn quế quanh gốc.","Thiếu nước cây nhanh ra hoa, lá nhỏ và dai."],"ordered":false},{"type":"h2","text":"✂️ Thu hoạch liên tục"},{"type":"p","text":"Khoảng 30–40 ngày sau trồng bắt đầu hái ngọn non dài 15–20cm. Mỗi lần hái là một lần bấm ngọn, cây ra thêm nhiều nhánh mới. Ngắt bỏ chùm hoa nếu muốn cây tập trung ra lá; để lại vài chùm trái chín tím đen lấy hạt cho vụ sau."},{"type":"h2","text":"🌿 Mồng tơi xanh hay mồng tơi tía?"},{"type":"table","rows":[["Loại","Đặc điểm","Ghi chú"],["Mồng tơi xanh lá to","Lá dày, to, nhiều nhớt","Phổ biến, năng suất cao"],["Mồng tơi thân tía","Thân và cuống lá tím đỏ","Đẹp, hợp làm giàn che ban công"],["Mồng tơi lá nhỏ (mồng tơi ta)","Lá nhỏ, thân mảnh","Dai sức, ít sâu bệnh"]]},{"type":"h2","text":"🪜 Kiểu giàn hợp từng chỗ"},{"type":"list","items":["**Ban công chung cư**: căng lưới nhựa hoặc dây dù dọc lan can, không khoan đục tường; giàn thấp 1,2–1,5m để dễ hái.","**Sân thượng nhà phố**: giàn chữ A bằng tre, ống nhựa; buộc chắc chân giàn vào thùng hoặc tạ để gió không lật.","**Hàng rào sân vườn**: cho leo thẳng lên lưới B40, vừa có rau vừa có màn xanh.","**Cửa sổ hướng Tây**: giàn mồng tơi trước cửa sổ giúp cản bớt nắng chiều."],"ordered":false},{"type":"h2","text":"🐛 Sâu bệnh và cách xử lý"},{"type":"table","rows":[["Vấn đề","Dấu hiệu","Xử lý"],["Đốm mắt cua","Đốm tròn nâu viền đỏ trên lá, mùa mưa","Ngắt lá bệnh, tưới gốc, giàn thoáng"],["Sâu ăn lá","Lá khuyết, có phân đen","Bắt tay, kiểm tra mặt dưới lá"],["Ốc sên","Lá non thủng lỗ lớn, vệt nhớt","Bắt ban đêm — xem [ốc sên ăn lá](/goc-cham-cay/oc-sen-an-la-ban-cong)"],["Rệp đen","Bám đọt non thành đám","Xịt nước mạnh, cắt bỏ đọt"]]},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Mồng tơi là rau ăn thường xuyên: ưu tiên bắt tay, ngắt lá bệnh, xịt nước. Không dùng thuốc hóa học trên giàn rau đang hái."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chậu nhỏ, đất cạn**: cây nhanh ra hoa, lá nhỏ dai, sớm tàn.","**Để cây ra hoa kết trái liên tục**: lá ít, cứng; nên ngắt chùm hoa nếu cần lá.","**Không bấm ngọn**: dây dài nhưng ít nhánh, giàn thưa.","**Tưới phun lên lá buổi tối mùa mưa**: dễ đốm lá."],"ordered":false},{"type":"h2","text":"🌱 Để giống cho vụ sau"},{"type":"p","text":"Chọn vài dây khỏe, lá to, để ra hoa và kết trái. Khi trái chín chuyển màu tím đen, hái về bóp bỏ phần thịt, rửa lấy hạt, phơi khô trong bóng mát rồi cất trong hũ kín nơi khô ráo. Hạt tự để giữ được đặc điểm của cây mẹ khá tốt. Trái mồng tơi chín có màu tím đậm, dễ dính màu vào quần áo, sàn nhà — nên để ý khi để giàn sát lối đi."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Mồng tơi sống được bao lâu?"},{"type":"p","text":"Mồng tơi có thể sống và cho hái nhiều tháng tới hơn một năm nếu được bón phân, tưới đều và cắt tỉa. Khi thân già hóa gỗ, lá nhỏ dần thì nên giâm ngọn trồng lứa mới."},{"type":"h3","text":"Mồng tơi có trồng được nơi ít nắng không?"},{"type":"p","text":"Được nhưng lá nhỏ, thân mảnh, cho ít rau. Muốn giàn đẹp cần ít nhất 4–5 giờ nắng mỗi ngày."},{"type":"h3","text":"Một giàn mồng tơi bao nhiêu cây là đủ?"},{"type":"p","text":"Với gia đình 3–4 người, 4–6 gốc trên một giàn dài khoảng 1,5–2m đã đủ hái nấu canh vài lần mỗi tuần khi cây đã sung."},{"type":"p","text":"Xem thêm [trồng rau thơm ban công](/goc-cham-cay/trong-rau-thom-ban-cong) và [trang trí ban công chung cư nhỏ](/goc-cham-cay/trang-tri-ban-cong-chung-cu-nho)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$trong-mong-toi-leo-gian-tai-nha$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Lá cây đổi màu không phải lúc nào cũng do sâu bệnh. Khi thiếu một chất dinh dưỡng, cây \"báo\" bằng những kiểu đổi màu khá đặc trưng. Đọc được tín hiệu đó giúp bón đúng thứ cây cần, không bón tràn lan."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Tomate_Blatt_Kalimangel.jpg/960px-Tomate_Blatt_Kalimangel.jpg","caption":"Lá cháy mép, vàng — dấu hiệu thường gặp khi thiếu kali. Ảnh: Goldlocki, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"🔍 Bảng nhận biết nhanh"},{"type":"table","rows":[["Thiếu chất","Lá nào bị trước","Dấu hiệu"],["Đạm (N)","Lá già","Vàng đều cả lá, cây còi, lá nhỏ"],["Lân (P)","Lá già","Lá xanh sẫm rồi ửng tím đỏ, cây chậm lớn, ít hoa"],["Kali (K)","Lá già","Mép lá vàng rồi cháy nâu, lá có thể xoăn mép"],["Magie (Mg)","Lá già","Vàng giữa các gân, gân còn xanh, thành hình xương cá"],["Sắt (Fe)","Lá non","Lá non vàng nhạt, gân xanh rõ"],["Canxi (Ca)","Lá non, trái","Đọt non biến dạng; cà chua thối đáy trái"]]},{"type":"p","text":"Mẹo nhớ: chất **di động** trong cây (đạm, lân, kali, magie) thiếu thì lá **già** biểu hiện trước — cây rút chất từ lá già nuôi lá non. Chất **ít di động** (sắt, canxi) thiếu thì lá **non** bị trước. Xem thêm [vàng lá do thiếu đạm](/benh-cay/vang-la-thieu-dam) và [vàng lá gân xanh do thiếu sắt](/benh-cay/vang-la-thieu-sat)."},{"type":"h2","text":"⚠️ Loại trừ trước khi bón thêm phân"},{"type":"list","items":["**Úng rễ, thối rễ**: rễ hỏng không hút được chất nên lá vàng giống thiếu dinh dưỡng — bón thêm còn hại.","**Bón dư phân** cũng làm cháy mép lá giống thiếu kali — xem [cháy rễ do bón phân quá liều](/benh-cay/chay-re-do-phan).","**Thiếu sáng** làm lá nhạt màu.","**Lá già tự nhiên** vàng rụng từng lá một — bình thường."],"ordered":false},{"type":"h2","text":"🛠️ Bổ sung thế nào cho đúng?"},{"type":"list","items":["Cây kiểng lá: phân NPK cân đối (như 20-20-20) pha loãng định kỳ thường đủ cả đạm, lân, kali.","Cây ra hoa, ra trái: dùng loại nhiều lân khi sắp ra hoa, nhiều kali khi nuôi trái.","Thiếu magie, sắt: chọn phân có ghi **trung – vi lượng** trên bao.","Bón theo đúng liều ghi trên bao, chia nhỏ nhiều lần; cây trồng chậu nên pha loãng hơn.","Lá đã đổi màu thường không xanh lại hẳn; theo dõi **lá mới ra** để biết bón đúng chưa."],"ordered":false},{"type":"h2","text":"🔄 Quy trình 4 bước trước khi kết luận \"thiếu chất\""},{"type":"list","items":["**Xem rễ và đất trước**: đất có sũng nước, rễ có thâm đen không? Rễ hỏng thì mọi triệu chứng đều giống thiếu dinh dưỡng.","**Xem vị trí lá bị**: lá già hay lá non — đây là manh mối lớn nhất (bảng ở trên).","**Nhớ lại lịch bón**: lần cuối bón phân là khi nào, loại gì, liều bao nhiêu? Cây vài tháng không bón thì khả năng thiếu chất cao; vừa bón đậm thì nghĩ tới bón dư.","**Bổ sung thử và theo dõi lá mới**: sau 2–4 tuần, lá mới ra xanh đẹp là đúng hướng."],"ordered":true},{"type":"h2","text":"🌍 Độ pH đất cũng làm cây \"đói\" dù đã bón"},{"type":"p","text":"Đất quá chua (phèn) hoặc quá kiềm (bón nhiều vôi, tro) làm một số chất có trong đất nhưng cây không hút được. Ví dụ đất kiềm thường gây vàng lá non gân xanh kiểu thiếu sắt dù đã bón phân vi lượng; đất phèn chua làm cây khó hút lân. Ở miền Tây, nhiều vùng đất phèn nên đây là nguyên nhân hay bị bỏ qua. Xem [tro bếp, vôi bột cho cây trồng](/goc-cham-cay/tro-bep-voi-bot-cho-cay-khi-nao-dung)."},{"type":"h2","text":"🌿 Từng nhóm cây hay thiếu chất gì?"},{"type":"table","rows":[["Nhóm cây","Hay gặp","Gợi ý"],["Cây kiểng lá trong chậu lâu năm","Thiếu đạm, magie","Thay đất 1–2 năm/lần, bón NPK cân đối"],["Cây ăn trái trong chậu","Thiếu kali khi nuôi trái, thiếu canxi","Tăng kali giai đoạn nuôi trái, tưới đều"],["Hoa hồng, cây ra hoa liên tục","Thiếu lân, kali, magie","Phân cho cây ra hoa có trung vi lượng"],["Rau ăn lá","Thiếu đạm","Phân hữu cơ hoai, phân trùn quế"],["Cây trên đất kiềm, giá thể nhiều vôi","Thiếu sắt","Giảm vôi, dùng phân có sắt dạng dễ hút"]]},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Thấy lá vàng là bón đạm**: nếu nguyên nhân là úng rễ hay thiếu magie, bón đạm không giải quyết được gì.","**Bón đậm một lần cho \"bù\"**: dễ cháy rễ, nhất là cây chậu.","**Phun phân bón lá giữa trưa nắng**: cháy lá, phí phân.","**Chờ lá cũ xanh lại để đánh giá**: lá đã đổi màu hiếm khi hồi phục — hãy nhìn lá mới."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Phân bón lá hay phân bón gốc tốt hơn khi cây thiếu chất?"},{"type":"p","text":"Phân bón lá cho hiệu quả nhanh với vi lượng (sắt, magie) và khi rễ đang yếu. Còn đạm, lân, kali với lượng lớn thì nên bón gốc. Xem [phân bón lá và phân bón gốc](/goc-cham-cay/phan-bon-la-va-phan-bon-goc)."},{"type":"h3","text":"Có cần đem đất đi phân tích không?"},{"type":"p","text":"Với vườn rộng, cây ăn trái hay sân vườn lớn, phân tích đất giúp bón đúng và tiết kiệm. Với vài chậu cây cảnh, quan sát lá và dùng phân cân đối thường là đủ."},{"type":"h3","text":"Bao lâu thì thấy cây hết thiếu chất?"},{"type":"p","text":"Thường 2–4 tuần với phân hòa tan, lâu hơn với phân hữu cơ, phân tan chậm. Dấu hiệu là lá non ra đều màu, kích thước bình thường."},{"type":"p","text":"Xem thêm [đọc chỉ số NPK trên bao phân](/goc-cham-cay/doc-chi-so-npk-tren-bao-phan) và [phân bón lá và phân bón gốc](/goc-cham-cay/phan-bon-la-va-phan-bon-goc)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-thieu-kali-thieu-lan-nhan-biet-qua-la$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Một góc bếp có vài chậu xanh vừa đẹp mắt vừa tiện: với tay là có nắm húng quế, cọng hành. Nhưng bếp nóng, có hơi dầu mỡ, chỗ thì sáng chỗ thì tối — chọn đúng cây và đúng chỗ thì cây mới bền."},{"type":"image","file":"https://live.staticflickr.com/3061/2593135672_292699fc40_b.jpg","caption":"Rau thơm trồng chậu ở bệ cửa sổ bếp"},{"type":"h2","text":"🌿 Rau thơm ở bệ cửa sổ"},{"type":"list","items":["Húng quế, tía tô, rau răm, hành lá, ngò: cần nắng ít nhất 4–5 giờ/ngày — chỉ hợp cửa sổ sáng.","Chậu nhỏ 12–15cm, có lỗ thoát nước, đĩa lót.","Cắt ngọn thường xuyên để cây ra nhánh.","Cách trồng từng loại: xem [trồng rau thơm ở ban công](/goc-cham-cay/trong-rau-thom-ban-cong) và [trồng hành lá từ gốc hành](/goc-cham-cay/trong-hanh-la-tai-nha)."],"ordered":false},{"type":"h2","text":"🛒 Cây kiểng hợp nhà bếp"},{"type":"table","rows":[["Cây","Vì sao hợp"],["Lưỡi hổ (cỡ mini)","Chịu nóng, chịu bóng, ít tưới"],["Lan chi","Treo, rủ đẹp, dễ sống"],["Trầu bà, ngọc ngân","Chịu bóng; có thể trồng thủy sinh, không đất"],["Ngọc bích","Hợp bệ cửa sổ nắng"]]},{"type":"h2","text":"⚠️ Chỗ không nên đặt cây"},{"type":"list","items":["Cạnh bếp gas, bếp từ, lò nướng, nồi cơm — nhiệt làm lá cháy, chậu nhựa biến dạng.","Trên tủ lạnh: nóng phía trên, rung, ít sáng.","Ngay dưới máy hút mùi: hơi dầu mỡ bám dày.","Sát bồn rửa: nước xà phòng bắn vào đất.","Cây có nhựa độc đặt xa chỗ chế biến thức ăn và tầm tay trẻ nhỏ."],"ordered":false},{"type":"h2","text":"🧽 Chăm cây trong bếp"},{"type":"p","text":"Lá bám dầu mỡ sẽ bí, kém quang hợp: lau lá bằng khăn ẩm 1–2 tuần một lần (xem [lau lá, cắt tỉa lá già](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la)). Không lau lá bằng dầu ăn hay sữa cho bóng — làm bít lỗ khí."},{"type":"h2","text":"🍳 Bố trí theo kiểu bếp"},{"type":"table","rows":[["Kiểu bếp","Chỗ đặt cây tốt","Gợi ý"],["Bếp có cửa sổ sáng","Bệ cửa sổ, kệ cạnh cửa","Rau thơm chậu nhỏ, ngọc bích"],["Bếp chữ L, chữ I không cửa sổ","Nóc tủ bếp trên xa máy hút mùi, kệ treo","Lan chi treo, trầu bà rủ"],["Bếp mở thông phòng khách","Ranh giới bếp – phòng ăn","Cây đứng chịu bóng làm vách mềm"],["Bếp nhà phố có giếng trời","Dưới giếng trời","Dương xỉ, trầu bà, rau thơm"]]},{"type":"h2","text":"🌱 Trồng thủy sinh ở bếp: gọn và sạch"},{"type":"p","text":"Bếp là nơi cần sạch sẽ, nên nhiều người chọn trồng cây trong nước thay vì đất: không lo đất rơi vãi, không sinh ruồi nấm. Trầu bà, ngọc ngân, phú quý cắm bình thủy tinh đặt trên kệ hoặc bệ cửa sổ, thay nước mỗi tuần là sống khỏe. Hành lá, rau muống cũng có thể ra rễ trong ly nước để hái dần. Xem cách làm ở bài [trồng cây thủy sinh trong bình nước](/goc-cham-cay/trong-cay-thuy-sinh-trong-nuoc)."},{"type":"h2","text":"🧄 Tận dụng đồ bếp để trồng rau"},{"type":"list","items":["**Gốc hành lá** cắt chừa 3–4cm có rễ, cắm vào ly nước hoặc chậu đất là ra lá mới.","**Gốc sả** cắm nước cho ra rễ rồi trồng chậu — xem [trồng sả trong chậu](/goc-cham-cay/trong-sa-trong-chau).","**Gừng, nghệ mọc mầm** đừng bỏ, trồng vào thùng — xem [trồng gừng, nghệ trong thùng](/goc-cham-cay/trong-gung-nghe-trong-thung).","**Ngò rí** gieo hạt vào khay nông, hái non sau vài tuần."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đặt rau thơm ở góc bếp tối** vì tiện tay: cây vống, lá nhạt, mau tàn.","**Tưới nước vo gạo, nước rửa rau có xà phòng**: đất chua, có mùi.","**Để đất vương vãi gần chỗ chế biến**: dùng chậu có đĩa lót và phủ mặt chậu bằng sỏi.","**Dùng bình xịt hóa chất lau bếp gần cây**: hơi hóa chất làm cháy lá."],"ordered":false},{"type":"h2","text":"🧼 Giữ góc cây trong bếp luôn sạch"},{"type":"p","text":"Bếp là nơi chế biến thức ăn nên vệ sinh quan trọng hơn mọi phòng khác. Chọn chậu có đĩa lót kín, lau đĩa mỗi tuần để không đọng nước, không thành chỗ muỗi đẻ trứng. Phủ mặt chậu bằng sỏi nhỏ giúp đất không văng ra khi tưới và hạn chế ruồi nấm đất. Không dùng phân chuồng, phân cá có mùi cho chậu đặt trong bếp; phân tan chậm dạng viên hoặc phân trùn quế đã hoai là lựa chọn sạch và ít mùi hơn. Khi thấy rệp, nhện trên rau thơm, ưu tiên ngắt bỏ phần bị hại và rửa lá, không phun thuốc trong bếp."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Bếp nóng cây có sống được không?"},{"type":"p","text":"Được, nếu đặt cây cách bếp nấu và lò nướng ít nhất 1–1,5m, nơi thoáng. Lưỡi hổ, ngọc bích chịu nóng khá; cây lá mỏng nên đặt xa hơn."},{"type":"h3","text":"Rau thơm trồng trong bếp có đủ ăn không?"},{"type":"p","text":"Đủ để hái điểm xuyết vài cọng cho món ăn. Muốn dùng nhiều nên trồng thêm ở ban công, sân thượng nắng nhiều."},{"type":"h3","text":"Có nên đặt cây trên bàn ăn?"},{"type":"p","text":"Một chậu nhỏ gọn, sạch đất (hoặc trồng thủy sinh) đặt giữa bàn ăn làm bữa cơm dễ chịu hơn. Tránh cây có phấn hoa nhiều, mùi mạnh."},{"type":"products","title":"Cây nhỏ cho góc bếp","slugs":["luoi-ho","lan-chi","ngoc-ngan","ngoc-bich"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-xanh-cho-nha-bep$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Phòng trọ nhỏ, cửa sổ hẹp, ngân sách eo hẹp, lại hay đi học, đi làm thêm cả ngày — nhưng một chậu cây xanh trên bàn học vẫn làm góc phòng dễ chịu hơn nhiều. Bí quyết là chọn đúng loại cây \"khó chết\"."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Shelf_at_the_bottom_of_a_window_for_growing_houseplants.jpg/960px-Shelf_at_the_bottom_of_a_window_for_growing_houseplants.jpg","caption":"Cây nhỏ trên kệ trong phòng"},{"type":"h2","text":"🛒 5 cây hợp phòng trọ"},{"type":"table","rows":[["Cây","Vì sao hợp","Chỗ đặt"],["Lưỡi hổ mini","Gần như không cần chăm, 7–10 ngày tưới","Bàn học, góc phòng"],["Lan chi","Rẻ, dễ sống, ra cây con tặng bạn","Kệ, treo cửa sổ"],["Ngọc ngân","Chịu bóng; trồng thủy sinh được","Bàn học"],["Dương xỉ mini","Xanh mướt, an toàn thú cưng","Cửa sổ có bóng râm, cần tưới đều"],["Ngọc bích","Ít tưới, sống lâu năm","Chỉ khi có cửa sổ nắng"]]},{"type":"h2","text":"💡 Mẹo giữ cây trong phòng trọ"},{"type":"list","items":["Chậu nhỏ phải có lỗ thoát nước và **đĩa lót** để khỏi ướt bàn, ướt sàn.","Phòng không cửa sổ: chọn lưỡi hổ, mỗi tuần mang ra hành lang có sáng vài giờ.","Tưới theo đất, không theo lịch — thử bằng ngón tay ([tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach)).","Không đặt cây trên máy tính, tủ lạnh mini, cạnh nồi cơm điện."],"ordered":false},{"type":"h2","text":"🏠 Về quê dài ngày thì sao?"},{"type":"list","items":["Tưới đẫm trước khi đi, đổ nước dư dưới đĩa.","Dời cây xa cửa sổ nắng, gom các chậu lại gần nhau.","Cây ưa ẩm: đặt trên khay sỏi có nước hoặc dùng bấc vải dẫn nước từ chai.","Lưỡi hổ, ngọc bích chịu được 2–3 tuần không tưới."],"ordered":false},{"type":"h2","text":"💰 Bắt đầu với ngân sách nhỏ"},{"type":"p","text":"Không cần chi nhiều để có một góc xanh. Một chậu cây nhỏ cỡ để bàn, kèm chậu nhựa có đĩa lót, là đủ bắt đầu. Nếu muốn tiết kiệm hơn nữa:"},{"type":"list","items":["**Xin cây con**: lan chi, trầu bà, lưỡi hổ rất dễ nhân giống — bạn bè trồng cây thường sẵn lòng cho một nhánh.","**Giâm cành trong ly nước**: trầu bà, ngọc ngân ra rễ trong vài tuần, không cần đất.","**Tái sử dụng hũ, ly**: khoan lỗ đáy hũ nhựa để làm chậu, hoặc dùng hũ thủy tinh trồng thủy sinh.","**Mua đất trộn sẵn túi nhỏ** thay vì túi lớn dùng không hết."],"ordered":false},{"type":"h2","text":"📅 Lịch chăm 5 phút mỗi tuần"},{"type":"table","rows":[["Khi nào","Việc","Thời gian"],["Mỗi tuần, cùng một ngày cố định","Thử đất bằng ngón tay, tưới nếu khô","2 phút"],["Mỗi tuần","Xoay chậu 1/4 vòng để cây mọc đều","10 giây"],["2 tuần một lần","Lau lá bằng khăn ẩm","2 phút"],["Mỗi tháng","Pha phân loãng tưới một lần (mùa cây lớn)","3 phút"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Gắn lịch chăm cây với một việc bạn chắc chắn làm mỗi tuần (ví dụ tối Chủ nhật giặt đồ) — sẽ ít khi quên hơn đặt nhắc nhở riêng."},{"type":"h2","text":"🏢 Ký túc xá có quy định riêng"},{"type":"p","text":"Một số ký túc xá không cho đặt chậu đất trên bệ cửa sổ, lan can vì sợ rơi, hoặc không cho đặt cây ở hành lang chung. Trước khi mua, nên hỏi ban quản lý. Trồng cây thủy sinh trong bình, đặt trên bàn học là cách gọn, sạch, ít bị nhắc nhở nhất."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Mua cây ưa nắng như sen đá, xương rồng** cho phòng thiếu sáng: cây vống, thối trong vài tuần.","**Tưới mỗi ngày cho chắc**: cây phòng trọ chết vì úng nhiều hơn chết khô.","**Chậu không lỗ thoát nước** mua theo bộ trang trí: nước đọng, rễ thối.","**Đặt cây sát cửa sổ nắng chiều gắt**: lá cháy, chậu nhựa nóng."],"ordered":false},{"type":"h2","text":"🤝 Góc xanh chung cho phòng ở ghép"},{"type":"p","text":"Phòng trọ nhiều người ở chung nên thống nhất một vài chậu cây chung đặt ở cửa sổ hoặc kệ chung, kèm tờ giấy nhỏ ghi lịch tưới và người phụ trách từng tuần. Cách này tránh tình trạng ai cũng tưới hoặc chẳng ai tưới. Chọn cây chịu được cả hai: lưỡi hổ, trầu bà, ngọc ngân. Mỗi người muốn có cây riêng thì chọn chậu nhỏ đặt trên bàn học của mình."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây nào khó chết nhất cho người hay quên?"},{"type":"p","text":"Lưỡi hổ đứng đầu: chịu bóng, chịu khô, 1–2 tuần tưới một lần vẫn ổn. Ngọc ngân trồng thủy sinh cũng rất ít phải chăm."},{"type":"h3","text":"Có nên để cây trong phòng ngủ trọ không?"},{"type":"p","text":"Một vài chậu nhỏ không ảnh hưởng gì đến sức khỏe. Phòng nhỏ kín gió thì không nên để quá nhiều chậu đất ẩm vì dễ sinh mốc, ruồi nấm."},{"type":"h3","text":"Chuyển trọ thì mang cây theo thế nào?"},{"type":"p","text":"Tưới trước 1–2 ngày (không tưới ngay hôm chuyển để chậu nhẹ, đất không rơi), bọc túi quanh chậu, đặt thẳng đứng trong thùng giấy. Tới nơi mới để cây chỗ sáng vừa phải vài ngày cho quen."},{"type":"p","text":"Xem chi tiết [giữ cây không chết khát khi đi vắng](/goc-cham-cay/cham-cay-khi-di-vang) và [6 cây khó chết cho người mới bắt đầu](/goc-cham-cay/cay-de-cham-cho-nguoi-moi-bat-dau)."},{"type":"products","title":"Cây nhỏ giá mềm","slugs":["lan-chi","luoi-ho","ngoc-ngan","duong-xi","duong-si"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-canh-cho-phong-tro-sinh-vien$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Một chậu cây xanh là món quà mừng thọ vừa trang nhã vừa \"sống\" — mỗi ngày ông bà nhìn cây lớn lên là nhớ người tặng. Nhưng cây tặng người lớn tuổi cần chọn kỹ hơn: ý nghĩa phải tốt, chăm phải dễ, và an toàn khi có cháu nhỏ chạy quanh."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg/960px-Hue_Vietnam_Tomb-of-Emperor-Minh-Mang-03a.jpg","caption":"Cây cảnh dáng cổ thụ — biểu tượng trường thọ. Ảnh: CEphoto, Uwe Aranas, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"🍀 Cây mang ý nghĩa trường thọ, bình an (theo dân gian)"},{"type":"table","rows":[["Cây","Ý nghĩa dân gian","Mức độ dễ chăm"],["Tùng thơm","Bền bỉ, trường thọ","Cần nắng sáng, tưới đều"],["Vạn niên thanh","Xanh tươi muôn năm, sức khỏe","Dễ; nhựa gây ngứa — đặt xa trẻ nhỏ"],["Ngọc bích","Sung túc, cây tiền","Rất dễ, ít tưới, cần nắng"],["Lưỡi hổ","Mạnh mẽ, xua điều xấu","Cực dễ, chịu bóng"],["Lan ý","Bình yên, hoa trắng thanh khiết","Dễ; lá rũ là báo khát nước"]]},{"type":"h2","text":"🛒 Chọn cây theo thói quen của người nhận"},{"type":"list","items":["**Ông bà hay quên tưới**: lưỡi hổ, ngọc bích — 1 tuần tưới một lần.","**Người thích chăm cây mỗi ngày**: tùng thơm, hoa hồng chậu, mai địa thảo.","**Nhà có sân, ban công nắng**: ngọc bích, tắc cẩm thạch (trái vàng, sung túc).","**Ở chung cư, ít sáng**: lưỡi hổ, ngân hậu, trầu bà đế vương."],"ordered":false},{"type":"h2","text":"🪴 Chậu và cách trao quà"},{"type":"list","items":["Chọn chậu vừa tầm, không quá nặng để người lớn tuổi dễ dời; có đĩa lót.","Tránh cây có gai, cây lá sắc nếu cụ yếu tay, mắt kém.","Viết kèm một tấm thiệp nhỏ: tên cây, bao lâu tưới một lần, đặt chỗ sáng hay râm.","Đặt sẵn cây ở chỗ cụ hay ngồi uống trà, đọc báo để cụ dễ ngắm, dễ chăm."],"ordered":false},{"type":"h2","text":"🎁 Gợi ý theo dịp và ngân sách"},{"type":"table","rows":[["Dịp","Gợi ý","Ghi chú"],["Mừng thọ 70, 80 tuổi","Tùng thơm, vạn niên thanh cỡ lớn trong chậu sứ","Trang trọng, chưng được lâu"],["Sinh nhật ông bà","Lan ý, ngọc bích cỡ vừa","Đặt bàn trà, bệ cửa sổ"],["Thăm hỏi khi ông bà mới khỏe lại","Lưỡi hổ, trầu bà đế vương","Không cần chăm nhiều"],["Tết, mừng xuân","Tắc cẩm thạch, mai địa thảo, chậu hoa","Thêm màu sắc, không khí Tết"]]},{"type":"h2","text":"🧓 Nghĩ tới sức khỏe người nhận"},{"type":"list","items":["**Người bị dị ứng phấn hoa, hen suyễn**: tránh cây hoa nhiều phấn, hoa có mùi nồng; chọn cây kiểng lá.","**Người mắt kém**: cây lá to, màu tương phản dễ nhìn, dễ thấy khi lá rũ cần tưới.","**Người đi lại khó khăn**: đặt cây ngay chỗ thường ngồi, không phải mang bình nước đi xa; chậu có bánh xe với cây lớn.","**Người hay quên**: cây chịu hạn, kèm một ngày cố định trong tuần để tưới (ví dụ sáng Chủ nhật)."],"ordered":false},{"type":"h2","text":"📝 Mẫu thiệp hướng dẫn chăm cây kèm quà"},{"type":"p","text":"Một tấm thiệp nhỏ viết tay, chữ to, giúp ông bà chăm cây dễ hơn và cũng là lời chúc:"},{"type":"table","rows":[["Mục","Ví dụ cho cây lưỡi hổ"],["Tên cây","Lưỡi hổ — mạnh mẽ, bền bỉ"],["Đặt ở đâu","Phòng khách, chỗ sáng nhẹ"],["Tưới","Mỗi tuần 1 lần, nửa ly nước; đất còn ẩm thì chưa tưới"],["Lời chúc","Chúc ông bà khỏe mạnh, sống lâu như cây xanh quanh năm"]]},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chọn chậu quá to, quá nặng** cho đẹp: người lớn tuổi không tự dời được để quét dọn, tránh mưa nắng.","**Cây cần chăm kỹ** (bonsai dáng thế, hoa hồng ngoại) cho người không có thói quen chăm cây.","**Cây có nhựa độc đặt chỗ thấp** khi nhà có cháu nhỏ hay chơi.","**Tặng cây đang ra hoa rộ**: đẹp lúc tặng nhưng mau tàn; nên chọn cây nhiều nụ."],"ordered":false},{"type":"h2","text":"🧓 Cùng ông bà chăm cây"},{"type":"p","text":"Nhiều người lớn tuổi rất thích làm vườn. Một chậu cây được tặng có thể là cái cớ để con cháu về thăm, cùng ông bà thay đất, tỉa lá, chụp ảnh cây ra hoa. Nếu ông bà ở xa, thỉnh thoảng gọi điện hỏi thăm cây cũng là dịp trò chuyện. Món quà xanh vì vậy có ý nghĩa lâu dài hơn một bó hoa cắt cành."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Tặng cây bonsai cho ông bà có hợp không?"},{"type":"p","text":"Hợp nếu ông bà thích và có thời gian chăm. Bonsai cần tưới đều, đủ nắng, cắt tỉa định kỳ — nếu ông bà chưa quen chăm cây, nên chọn cây dễ trước."},{"type":"h3","text":"Có kiêng tặng cây nào cho người lớn tuổi không?"},{"type":"p","text":"Theo quan niệm dân gian, nhiều gia đình tránh cây có gai nhọn hoặc cây héo úa làm quà mừng thọ. Đây là quan niệm để tham khảo; quan trọng nhất là cây khỏe, đẹp và hợp sở thích người nhận."},{"type":"h3","text":"Có thể nhờ shop giao cây kèm thiệp tới nhà ông bà không?"},{"type":"p","text":"Có thể liên hệ shop để hỏi về giao hàng và ghi lời nhắn kèm theo đơn."},{"type":"p","text":"Các ý nghĩa trên là quan niệm dân gian để tham khảo. Xem thêm [chọn cây làm quà khai trương, tân gia, sinh nhật](/goc-cham-cay/chon-cay-qua-tang-khai-truong-tan-gia) và [cây cảnh an toàn cho nhà có trẻ nhỏ](/goc-cham-cay/cay-canh-an-toan-tre-nho-thu-cung)."},{"type":"products","title":"Cây làm quà cho người lớn tuổi","slugs":["tung-thom","van-nien-thanh","ngoc-bich","luoi-ho","lan-y"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-tang-nguoi-lon-tuoi-mung-tho$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Cúc mâm xôi vàng rực, cúc đại đóa bông to — chậu cúc gần như không thể thiếu trước sân nhà ngày Tết miền Tây. Có nhà giữ cúc tươi tới rằm tháng Giêng, có nhà mới mùng 3 đã héo. Khác biệt nằm ở vài thói quen chăm đơn giản."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/CHRYSANTHEMUM.jpg/960px-CHRYSANTHEMUM.jpg","caption":"Chậu hoa cúc chưng Tết. Ảnh: Inchara Srinivas, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🛒 Chọn chậu cúc khi mua"},{"type":"list","items":["Chọn chậu có **nhiều nụ chúm chím, vài bông vừa nở** — nở dần sẽ bền suốt Tết.","Lá xanh đậm, không vàng úa ở gốc, không có đốm trắng (phấn trắng), không có rệp ở đọt.","Lắc nhẹ: bầu đất chắc, cây không lung lay.","Bông nở bung hết từ chợ: đẹp nhất lúc mua nhưng mau tàn."],"ordered":false},{"type":"h2","text":"📍 Đặt cúc ở đâu?"},{"type":"list","items":["Sân trước, hiên nhà có **nắng sáng**, thoáng gió là tốt nhất.","Đưa vào phòng khách chưng: chỉ vài ngày rồi đem ra ngoài lại; phòng tối kín bông mau rũ.","Tránh luồng gió nóng, máy lạnh thổi thẳng, gần bếp."],"ordered":false},{"type":"h2","text":"💧 Tưới cúc đúng cách"},{"type":"list","items":["Tưới **gốc** mỗi ngày vào sáng sớm (ngày nắng gắt thêm chiều mát), đủ ẩm, không đọng nước.","**Không tưới lên bông**: bông ướt dễ thâm, thối cánh.","Đất khô kiệt một lần là lá gốc vàng, bông rũ nhanh.","Chậu nhựa mỏng phơi nắng nóng: đặt vào chậu lớn hơn hoặc che thành chậu."],"ordered":false},{"type":"h2","text":"✂️ Ngắt bông tàn, lá úa"},{"type":"p","text":"Mỗi ngày dạo qua ngắt bông đã tàn, lá vàng ở gốc — chậu luôn gọn đẹp, ít nấm bệnh, cây dồn sức cho nụ còn lại. Thấy rệp ở đọt thì xịt nước hoặc ngắt bỏ (xem [rệp muội](/benh-cay/rep-muoi)); đốm bột trắng trên lá là [phấn trắng](/benh-cay/phan-trang)."},{"type":"h2","text":"🌱 Có cần bón phân không?"},{"type":"p","text":"Cúc mua về đã được nhà vườn bón đủ cho đợt hoa. Trong Tết chỉ cần tưới đều; bón thêm phân đạm lúc này còn làm cây ra lá, bông kém bền."},{"type":"h2","text":"❓ Sau Tết giữ cúc được không?"},{"type":"p","text":"Được với người kiên nhẫn: cắt bỏ hết bông tàn, cắt thấp cây, bón phân hữu cơ, đặt nơi nắng — cây ra chồi mới, có thể giâm ngọn làm cây con. Nhưng cúc Tết của nhà vườn được xử lý ánh sáng để nở đúng dịp, năm sau tự trồng thường nở không đúng Tết."},{"type":"h2","text":"🌼 Cúc mâm xôi và cúc đại đóa khác nhau thế nào?"},{"type":"table","rows":[["","Cúc mâm xôi","Cúc đại đóa"],["Dáng","Tán tròn như mâm xôi, rất nhiều bông nhỏ","Ít bông, mỗi bông to"],["Độ bền","Bền, nở nối tiếp nhau","Từng bông bền nhưng ít bông"],["Tưới","Cần nước nhiều vì tán dày","Vừa phải, giữ ẩm đều"],["Lưu ý","Tán dày dễ bí, nên ngắt bông tàn thường xuyên","Bông to nặng, cần cọc đỡ"]]},{"type":"h2","text":"📅 Lịch chăm cúc từ 23 tháng Chạp đến rằm tháng Giêng"},{"type":"table","rows":[["Giai đoạn","Việc cần làm"],["Ngày mua về","Đặt chỗ nắng sáng thoáng gió, tưới gốc đẫm, kiểm tra rệp ở đọt"],["Trước Giao thừa","Tưới mỗi sáng, ngắt bông tàn; chậu chưng trong nhà chỉ để 1–2 ngày"],["Mùng 1 – mùng 3","Nhà đông người, dễ quên tưới — giao việc tưới cho một người"],["Sau mùng 4","Đem cúc ra hiên nắng sáng, tiếp tục ngắt bông tàn, lá vàng"],["Tới rằm tháng Giêng","Bông thưa dần; quyết định giữ cây hay thay bằng cây trồng mới"]]},{"type":"h2","text":"🌬️ Mẹo giữ cúc tươi trong những ngày nóng"},{"type":"list","items":["Chậu nhựa đen đặt nắng gắt: lồng vào chậu sứ, chậu đất nung lớn hơn để giảm nóng rễ.","Che lưới mỏng vào buổi trưa nếu nắng quá gắt; buổi sáng vẫn cho cây hứng nắng.","Ngày gió khô (gió chướng cuối năm), kiểm tra đất cả chiều — cúc rũ rất nhanh khi khô.","Không tưới nước đá lạnh \"cho bông tươi\" — rễ bị sốc."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chưng cúc trong phòng máy lạnh suốt Tết**: bông rũ, lá vàng chỉ sau vài ngày.","**Tưới phun từ trên xuống cho nhanh**: cánh hoa thâm, thối.","**Bón phân đạm khi đang chưng**: cây ra lá, bông kém bền.","**Để bông tàn trên cây**: dễ nấm mốc lan sang bông còn tươi."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cúc bị rệp trong Tết có phun thuốc được không?"},{"type":"p","text":"Hạn chế phun thuốc trong nhà ngày Tết. Xịt nước mạnh vào đọt, ngắt đọt bị nặng và theo dõi; rệp ít không ảnh hưởng nhiều đến độ bền hoa."},{"type":"h3","text":"Lá gốc cúc vàng là bệnh gì?"},{"type":"p","text":"Thường do thiếu nước, đất khô kiệt rồi tưới lại, hoặc lá già tự nhiên. Ngắt bỏ lá vàng, tưới đều. Nếu vàng lan nhanh lên trên kèm thối gốc thì kiểm tra úng nước."},{"type":"h3","text":"Mua cúc ngày nào là đẹp nhất?"},{"type":"p","text":"Thường khoảng 23–27 tháng Chạp, chọn chậu nhiều nụ hé, vài bông nở. Mua quá sớm thì hoa có thể nở rộ trước Tết; quá sát Tết thì chậu đẹp đã được chọn gần hết."},{"type":"p","text":"Xem thêm [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet) và [chăm cây sau Tết](/goc-cham-cay/cham-cay-sau-tet)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cham-cuc-chung-tet-ben-hoa$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Nhiều người thấy kiến bò lên xuống thân cây liền đi tìm thuốc diệt kiến. Nhưng kiến thường chỉ là \"người đưa tin\": lần theo đường kiến lên tới đọt non, mặt dưới lá, bạn sẽ thấy thủ phạm thật — rệp."},{"type":"image","file":"https://upload.wikimedia.org/wikipedia/commons/9/9f/Ants_tending_aphids%2C_Julie_Metz_Wetlands%2C_Woodbridge%2C_Virginia.jpg","caption":"Kiến chăm sóc đàn rệp trên thân cây để lấy mật. Ảnh: Judy Gallagher, CC BY 2.0, Wikimedia Commons"},{"type":"h2","text":"🔎 Vì sao có kiến thì thường có rệp?"},{"type":"p","text":"[Rệp muội](/benh-cay/rep-muoi), [rệp sáp](/benh-cay/rep-sap), bọ phấn hút nhựa cây và thải ra **mật ngọt**. Kiến rất thích mật này nên chúng \"chăn\" rệp: tha rệp lên đọt non, đuổi bọ rùa và ong ký sinh — kẻ thù tự nhiên của rệp. Kết quả là rệp càng đông, cây càng yếu, lá dính mật rồi đen [muội](/benh-cay/muoi-den)."},{"type":"h2","text":"🔍 Kiến có trực tiếp hại cây không?"},{"type":"list","items":["Phần lớn kiến không ăn lá cây.","Kiến làm tổ trong chậu làm đất rỗng, khô nhanh, rễ có chỗ bị hở; cây chậu nhỏ có thể héo.","Vài loài kiến cắn nụ hoa, hạt giống mới gieo.","Kiến lửa làm tổ trong chậu đặt sân vườn có thể đốt người khi tưới cây."],"ordered":false},{"type":"h2","text":"🛠️ Cách xử lý kiến và rệp"},{"type":"list","items":["**Diệt rệp trước**: xịt nước mạnh, cắt đọt bị nặng, lau rệp sáp bằng tăm bông nhúng cồn (xem [trị rệp sáp](/goc-cham-cay/tri-rep-sap-cay-kieng-la)). Hết mật, kiến tự bỏ đi.","**Chặn đường lên cây**: quấn một vòng băng keo hai mặt quanh thân hoặc chân kệ; đặt chân kệ chậu vào chén nước.","**Tổ kiến trong chậu**: ngâm cả chậu vào xô nước ngập mặt đất 20–30 phút, kiến sẽ bò lên, gạt bỏ; với cây chịu úng kém thì nên thay đất mới.","**Quanh nhà**: dùng bả kiến dạng gel đặt ở đường kiến đi (ngoài chậu, xa tầm tay trẻ nhỏ và thú cưng) để kiến mang về diệt cả tổ."],"ordered":true},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Bả kiến, thuốc diệt côn trùng phải đặt xa tầm với trẻ nhỏ, chó mèo, không rắc trực tiếp vào chậu rau ăn. Rửa tay sau khi dùng."},{"type":"h2","text":"🛡️ Phòng kiến quay lại"},{"type":"p","text":"Kiểm tra đọt non mỗi tuần để diệt rệp từ khi mới có vài con; không bón dư đạm làm đọt non mập mềm; kê chậu lên kệ, không để chậu sát tường nhiều kiến."},{"type":"h2","text":"🐜 Nhận diện vài loại kiến hay gặp quanh chậu cây"},{"type":"table","rows":[["Loại","Đặc điểm","Mức phiền"],["Kiến đen nhỏ","Đi thành hàng dài, chăn rệp lấy mật","Trung bình — dấu hiệu có rệp"],["Kiến lửa (kiến đỏ nhỏ)","Màu nâu đỏ, đốt rát, làm tổ đất xốp","Cao — nguy hiểm khi tưới, làm vườn"],["Kiến vàng","Làm tổ bằng lá trên cây ăn trái","Thấp — nhà vườn còn dùng để diệt sâu"],["Kiến hôi","Nhỏ, có mùi khi bóp, hay vào nhà","Trung bình — tìm mật, đồ ngọt"]]},{"type":"p","text":"Trên cây ăn trái như cam, quýt, bưởi, nhà vườn miền Tây từ lâu đã nuôi **kiến vàng** để kiểm soát sâu hại — ví dụ cho thấy không phải con kiến nào cũng là kẻ thù của cây."},{"type":"h2","text":"🔁 Vòng lặp kiến – rệp – muội đen"},{"type":"list","items":["Rệp hút nhựa đọt non, thải mật ngọt.","Kiến kéo tới ăn mật, xua đuổi bọ rùa, ong ký sinh — thiên địch của rệp.","Rệp được bảo vệ nên sinh sôi nhanh hơn, mật tiết ra nhiều hơn.","Mật đọng trên lá nuôi nấm muội đen, lá đen bẩn, quang hợp kém."],"ordered":true},{"type":"p","text":"Chỉ cần phá một mắt xích — diệt rệp, hoặc chặn kiến lên cây — là cả vòng lặp yếu đi. Làm cả hai cùng lúc thì nhanh nhất."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Rắc thuốc diệt kiến dạng bột vào chậu rau, chậu cây trong nhà**: tồn dư trong đất, nguy hiểm cho trẻ nhỏ và thú cưng.","**Chỉ diệt kiến mà bỏ qua rệp**: kiến tổ khác lại kéo tới vì mật vẫn còn.","**Đổ nước sôi vào chậu để diệt tổ kiến**: chết luôn rễ cây.","**Để đĩa lót đọng nước ngọt, đồ ăn gần chậu**: kéo kiến vào nhà."],"ordered":false},{"type":"h2","text":"📋 Kiểm tra nhanh mỗi tuần"},{"type":"list","items":["Nhìn đường kiến: kiến đi thành hàng lên thân là dấu hiệu có rệp trên cây.","Lật đọt non, mặt dưới lá: tìm rệp muội, rệp sáp, bọ phấn.","Sờ lá: lá dính mật là rệp đang hoạt động.","Nhấc chậu xem đáy: tổ kiến, đất rỗng, rệp sáp rễ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Kiến trong chậu lan có sao không?"},{"type":"p","text":"Kiến thường làm tổ trong giá thể vỏ thông, than của chậu lan và có thể chăn rệp sáp ở rễ. Ngâm chậu vào nước cho kiến bò ra và kiểm tra rệp sáp quanh rễ."},{"type":"h3","text":"Phấn rôm, quế bột có đuổi kiến được không?"},{"type":"p","text":"Có thể làm kiến tạm đổi đường đi, nhưng hiệu quả ngắn và không diệt được tổ. Nên dùng như biện pháp phụ."},{"type":"h3","text":"Bị kiến lửa đốt khi tưới cây thì làm gì?"},{"type":"p","text":"Rửa chỗ bị đốt bằng xà phòng và nước mát, chườm lạnh, không gãi vỡ mụn. Nếu sưng lan rộng, khó thở, chóng mặt thì cần đi khám ngay."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$kien-bo-tren-cay-canh-co-hai-khong$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Mua về cây tán tròn, gọn; vài tháng sau thân cao lêu khêu, lá thưa thớt, ngọn ngả hẳn về phía cửa sổ. Hiện tượng này gọi là **cây vống** — cây đang \"rướn người\" đi tìm ánh sáng."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Etiolation_of_plants.JPG/960px-Etiolation_of_plants.JPG","caption":"Cây con vươn dài vì thiếu sáng. Ảnh: சஞ்சீவி சிவகுமார், CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🔍 Dấu hiệu cây bị vống"},{"type":"list","items":["Khoảng cách giữa hai lá (đốt thân) dài ra rõ rệt so với phần thân cũ.","Thân mảnh, mềm, dễ ngả đổ.","Lá mới nhỏ hơn, nhạt màu; cây lá màu (phú quý, vạn lộc) xanh dần.","Cả cây nghiêng về phía nguồn sáng.","Cây mọng nước (ngọc bích, sen đá) dài ngoằng, lá thưa và cong xuống."],"ordered":false},{"type":"h2","text":"🔎 Vì sao cây bị vống?"},{"type":"p","text":"**Thiếu ánh sáng** là nguyên nhân chính. Cây đặt sâu trong phòng, xa cửa sổ, hay chỉ có đèn trần sẽ vươn dài để tìm sáng. Bón nhiều đạm khi cây thiếu sáng làm cây vống nhanh hơn. Cây con gieo hạt để chỗ râm cũng vống ngay trong vài ngày. Xem cách đánh giá ánh sáng trong nhà ở bài [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."},{"type":"h2","text":"🛠️ Cách sửa cây bị vống"},{"type":"list","items":["**Dời ra chỗ sáng hơn** — từ từ trong 1 tuần, không đưa thẳng ra nắng gắt (lá quen bóng sẽ cháy).","**Xoay chậu 1/4 vòng mỗi tuần** để cây mọc thẳng, đều tán.","**Cắt ngọn**: cắt phần thân vống phía trên một mắt lá; cây sẽ bật nhánh mới ở các mắt bên dưới, tán dày lại.","**Đem ngọn đi giâm** để có thêm cây (xem [nhân giống cây cảnh tại nhà](/goc-cham-cay/nhan-giong-cay-canh-tai-nha)).","**Giảm phân đạm** cho tới khi cây được đủ sáng.","Thân quá dài không chịu nổi: cắm cọc đỡ tạm."],"ordered":true},{"type":"p","text":"Lưu ý: phần thân đã vống **không ngắn lại được**. Sửa đúng thì phần lá mới ra sẽ dày, đẹp; phần cũ cắt dần khi cây đã có tán mới."},{"type":"h2","text":"🛒 Chỗ ít sáng thì chọn cây gì?"},{"type":"p","text":"Nếu không thể dời chỗ, hãy chọn cây chịu bóng thật sự: [lưỡi hổ](/san-pham/luoi-ho), [ngân hậu](/san-pham/ngan-hau), [bạch mã](/san-pham/bach-ma-hoang-tu), [trầu bà đế vương xanh](/san-pham/trau-ba-de-vuong-xanh). Xem thêm [6 cây sống khỏe ở góc tối](/goc-cham-cay/cay-trong-nha-thieu-sang)."},{"type":"h2","text":"🌿 Sửa vống theo từng loại cây"},{"type":"table","rows":[["Loại cây","Cách sửa hiệu quả"],["Trầu bà, trầu bà leo","Cắt dây dài trên mắt lá, giâm ngọn cắm lại cùng chậu cho dày gốc"],["Phú quý, vạn lộc, ngọc ngân","Cắt ngọn cây quá cao, gốc sẽ đâm chồi; giâm ngọn trong nước"],["Sen đá, ngọc bích","Cắt ngọn (cắt hoa thị), để khô vết cắt rồi cắm lại; gốc cũ ra nhiều nhánh"],["Lưỡi hổ","Lá vống không cắt ngắn được; tách cây con mới mọc và cho đủ sáng"],["Cây con gieo hạt","Vùi sâu thêm phần thân vống khi cấy sang chậu (với cà chua, ớt) và đưa ra sáng ngay"]]},{"type":"h2","text":"💡 Đo ánh sáng bằng điện thoại"},{"type":"p","text":"Có nhiều ứng dụng đo độ rọi (lux) trên điện thoại. Kết quả không chính xác như máy đo chuyên dụng nhưng đủ để so sánh các vị trí trong nhà. Đo vào khoảng 10 giờ sáng, đặt điện thoại ngửa ngay tại chỗ lá cây:"},{"type":"table","rows":[["Mức đo được (tham khảo)","Ý nghĩa"],["Dưới vài trăm lux","Quá tối với phần lớn cây — chỉ lưỡi hổ, ngân hậu trụ được, và nên có đèn"],["Khoảng 1.000–2.500 lux","Sáng vừa — hợp nhiều cây kiểng lá chịu bóng"],["Trên 5.000 lux","Sáng nhiều — hợp cây lá màu, cây ra hoa"],["Hàng chục nghìn lux","Nắng trực tiếp — cây mọng nước, rau, cây ăn trái"]]},{"type":"h2","text":"🗓️ Sau khi sửa: theo dõi thế nào?"},{"type":"list","items":["**Tuần 1–2**: cây làm quen chỗ sáng mới, có thể rụng vài lá già — bình thường.","**Tuần 3–6**: chồi mới bật ở các mắt dưới vết cắt; lá mới ngắn đốt, dày hơn.","**Sau 2–3 tháng**: tán đã dày, có thể cắt bỏ dần phần thân vống cũ.","Chỉ bón lại phân khi thấy cây ra lá mới đều đặn."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đưa cây vống ra nắng gắt ngay**: lá quen bóng cháy trắng.","**Bón thêm phân \"cho cây mập lại\"**: thiếu sáng mà dư đạm càng vống.","**Chỉ xoay chậu mà không tăng sáng**: cây thẳng hơn nhưng vẫn vống.","**Tiếc không dám cắt ngọn**: tán không bao giờ dày lại được."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây vống có chết không?"},{"type":"p","text":"Vống không làm cây chết ngay, nhưng cây yếu dần, dễ sâu bệnh, dễ đổ. Nếu được sửa sớm, cây hồi phục rất tốt."},{"type":"h3","text":"Đèn trần trong nhà có giúp cây hết vống không?"},{"type":"p","text":"Đèn trần thường quá yếu và quá xa. Muốn dùng đèn, nên chọn đèn LED trồng cây đặt gần ngọn — xem [đèn LED trồng cây trong nhà](/goc-cham-cay/den-led-trong-cay-trong-nha)."},{"type":"h3","text":"Cây con gieo hạt bị vống có cứu được không?"},{"type":"p","text":"Với cây con, đưa ngay ra chỗ nắng sáng và giảm tưới. Cà chua có thể vùi sâu thân khi cấy; nhiều loại rau vống quá thì gieo lại sẽ nhanh hơn."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-bi-vong-vuon-dai-la-thua$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Sả là gia vị không thể thiếu trong bếp miền Tây: kho, xào, nướng, nấu nước. Trồng một chậu sả ở ban công vừa có sả tươi dùng quanh năm, vừa được tiếng là giúp đuổi muỗi (mùi sả có tác dụng nhẹ, không thay được biện pháp diệt muỗi)."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Tanglad_%28lemongrass%2C_Cymbopogon_citratus%29_-_Philippines.jpg/960px-Tanglad_%28lemongrass%2C_Cymbopogon_citratus%29_-_Philippines.jpg","caption":"Bụi sả trồng chậu"},{"type":"h2","text":"🌱 Cho sả ra rễ từ cây mua chợ"},{"type":"list","items":["Chọn cây sả tươi, còn nguyên phần gốc dưới (đáy tép), không bị cắt sát.","Cắt bớt lá, chừa thân dài 15–20cm.","Cắm gốc vào ly nước ngập 3–4cm, đặt nơi sáng, thay nước 2–3 ngày một lần.","Sau 1–2 tuần rễ trắng mọc dài 2–3cm là đem trồng."],"ordered":true},{"type":"h2","text":"🪴 Chậu, đất và chỗ đặt"},{"type":"list","items":["Chậu hoặc thùng sâu ít nhất 25–30cm — bụi sả lớn nhanh, rễ nhiều.","Đất tơi thoát nước, trộn ít phân hữu cơ.","Nắng nhiều càng tốt, ít nhất 5–6 giờ/ngày.","Trồng mỗi chậu 3–5 tép, cách nhau 10cm."],"ordered":false},{"type":"h2","text":"💧 Tưới và bón"},{"type":"list","items":["Mới trồng: giữ ẩm 1–2 tuần cho bén rễ.","Sau đó tưới khi mặt đất khô; sả chịu hạn tốt, sợ úng.","1–2 tháng một lần rắc phân trùn quế hoặc phân hữu cơ quanh gốc."],"ordered":false},{"type":"h2","text":"✂️ Thu hoạch và tách bụi"},{"type":"p","text":"Sau 2–3 tháng, bụi đã đẻ thêm nhiều tép. Cắt sát gốc những tép to bên ngoài, chừa tép non ở giữa. Bụi quá dày, chật chậu thì nhấc ra tách thành nhiều bụi nhỏ trồng sang chậu khác. Lá sả già có thể cắt bớt để bụi thoáng (đeo găng vì mép lá sắc)."},{"type":"h2","text":"🌾 Sả chanh, sả hồng, sả Java khác nhau ra sao?"},{"type":"table","rows":[["Loại","Đặc điểm","Dùng làm gì"],["Sả chanh (sả thường)","Bẹ trắng hồng, mùi chanh thơm","Nấu ăn: kho, xào, nướng, nấu nước"],["Sả hồng (sả tím)","Bẹ có màu tím hồng","Nấu ăn, trồng làm cảnh"],["Sả Java (sả xả muỗi)","Lá to, mùi hắc hơn","Thường dùng chưng cất tinh dầu, không phải sả nấu ăn"]]},{"type":"p","text":"Sả mua ở chợ thường là sả chanh nấu ăn — loại hợp nhất để trồng chậu dùng trong bếp."},{"type":"h2","text":"🪴 Một chậu sả cho được bao nhiêu?"},{"type":"p","text":"Bụi sả trồng chậu đủ nắng, bón đều, sau vài tháng đã đẻ thành bụi nhiều tép. Với gia đình nấu ăn thường ngày, 2–3 chậu sả cỡ 30–40cm thường đủ cắt dùng dần quanh năm mà không phải mua. Muốn có nhiều hơn, tách bụi và trồng thêm thay vì để một chậu quá dày."},{"type":"h2","text":"🐛 Sả có bị sâu bệnh không?"},{"type":"table","rows":[["Vấn đề","Dấu hiệu","Cách xử lý"],["Thối gốc","Gốc mềm nhũn, có mùi, tép vàng rũ","Giảm tưới, chậu thoát nước, cắt bỏ tép thối"],["Gỉ sắt","Lá có vệt chấm màu nâu cam","Cắt lá bệnh, bụi thoáng, không tưới lên lá"],["Rệp sáp gốc","Mảng trắng như bông ở bẹ sát đất","Lau, cắt bỏ bẹ già, kiểm tra rễ"],["Cháy đầu lá","Đầu lá khô nâu","Bình thường ở lá già; nếu nhiều thì kiểm tra khô hạn, nước mặn"]]},{"type":"h2","text":"☀️ Sả trên ban công chung cư"},{"type":"list","items":["Ban công hướng Đông hoặc Nam có nắng nhiều là chỗ lý tưởng.","Ban công gió mạnh: dùng chậu nặng, đáy rộng — bụi sả lớn dễ làm chậu nhẹ ngã.","Lá sả dài có thể quét vào lan can, nhà bên cạnh; cắt bớt lá già cho gọn.","Chậu đặt trên khay hứng để nước tưới không chảy xuống tầng dưới."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Trồng sả trong chậu nông**: bụi chật, tép nhỏ, nhanh cạn đất.","**Tưới quá nhiều, chậu đặt trong bóng râm**: gốc thối.","**Cắt sát toàn bộ bụi**: bụi kiệt sức, chậm hồi.","**Mua sả đã cắt sát gốc** để trồng: không còn phần đáy tép nên không ra rễ."],"ordered":false},{"type":"h2","text":"🍲 Thu hoạch đúng lúc để sả thơm nhất"},{"type":"p","text":"Tép sả dùng nấu ăn ngon nhất khi bẹ đã to bằng ngón tay cái, phần gốc trắng chắc, mùi thơm rõ. Nên cắt vào buổi sáng khi cây còn tươi. Lấy một tép bằng cách dùng dao sắc cắt sát mặt đất hoặc tách nhẹ tép ở rìa bụi kèm một ít rễ — tép có rễ có thể cắm lại sang chậu khác. Sả cắt về bọc giấy cất ngăn mát tủ lạnh giữ được nhiều ngày; muốn để lâu hơn có thể băm nhỏ, chia túi nhỏ cất ngăn đá."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Sả có thực sự đuổi muỗi không?"},{"type":"p","text":"Mùi sả có tác dụng xua muỗi nhẹ ở khoảng cách gần, chủ yếu khi vò lá. Một chậu sả không thay được mùng, lưới chống muỗi và việc dọn chỗ nước đọng."},{"type":"h3","text":"Có trồng sả trong nhà được không?"},{"type":"p","text":"Sả cần nhiều nắng nên trồng trong nhà sẽ vống, ít tép. Nên để ngoài ban công, sân thượng."},{"type":"h3","text":"Lá sả dùng được không?"},{"type":"p","text":"Lá sả có thể nấu nước uống, nấu nước xông theo thói quen dân gian, hoặc cắt nhỏ ủ làm phân. Không đốt lá sả trong nhà."},{"type":"p","text":"Xem thêm [trồng hành lá tại nhà từ gốc hành](/goc-cham-cay/trong-hanh-la-tai-nha) và [trồng rau thơm ban công](/goc-cham-cay/trong-rau-thom-ban-cong)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$trong-sa-trong-chau$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Với cây trồng trong nhà, trên ban công hay rau ăn hằng ngày, nhiều người muốn tránh thuốc hóa học mạnh. Dầu neem và xà phòng sinh học là hai lựa chọn phổ biến — hiệu quả với côn trùng nhỏ thân mềm nếu dùng đúng cách."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Azadirachta_indica%2C_leaves_%26_fruits.JPG/960px-Azadirachta_indica%2C_leaves_%26_fruits.JPG","caption":"Lá cây neem (xoan Ấn Độ). Ảnh: Kevinsooryan, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"📖 Dầu neem là gì?"},{"type":"p","text":"Dầu neem ép từ hạt cây neem (xoan Ấn Độ). Hoạt chất trong dầu làm côn trùng chán ăn, rối loạn lột xác; lớp dầu cũng làm con non bị bít thở. Tác dụng chậm hơn thuốc hóa học — vài ngày mới thấy rệp giảm rõ."},{"type":"h2","text":"🧼 Xà phòng sinh học là gì?"},{"type":"p","text":"Là xà phòng gốc axit béo (xà phòng kali) làm tan lớp sáp bảo vệ của côn trùng thân mềm. **Chỉ có tác dụng khi phun trúng con**, khô rồi là hết tác dụng. Không dùng nước rửa chén, xà phòng giặt thay thế — nhiều loại có chất tẩy, hương liệu làm cháy lá."},{"type":"h2","text":"🐛 Trị được những gì?"},{"type":"table","rows":[["Đối tượng","Hiệu quả"],["Rệp muội, bọ phấn","Tốt khi phun kỹ, lặp lại"],["Nhện đỏ","Khá; phải phun mặt dưới lá"],["Rệp sáp non","Khá; con già có lớp sáp dày cần lau bằng cồn trước"],["Bọ trĩ","Trung bình"],["Sâu to, ốc sên","Kém — nên bắt tay"]]},{"type":"h2","text":"🛠️ Cách pha và phun"},{"type":"list","items":["Pha **đúng tỉ lệ ghi trên chai** sản phẩm; dầu neem cần chất nhũ hóa đi kèm mới hòa được với nước.","Thử trước trên 2–3 lá, chờ 24 giờ không cháy mới phun cả cây.","Phun lúc **chiều mát**, không phun khi nắng gắt (lá dính dầu dưới nắng dễ cháy).","Phun ướt đều **mặt dưới lá**, nách lá, đọt non — nơi côn trùng trú.","Lặp lại 5–7 ngày một lần, 3–4 lần, để diệt lứa mới nở từ trứng.","Pha xong dùng hết trong ngày."],"ordered":true},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Dầu neem và xà phòng sinh học ít độc nhưng vẫn là sản phẩm bảo vệ thực vật: đọc nhãn, đeo găng tay, tránh mắt, để xa tầm tay trẻ nhỏ, không phun lên hoa đang có ong bướm ghé. Với rau, rửa kỹ trước khi ăn và tuân thủ thời gian cách ly ghi trên nhãn. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."},{"type":"h2","text":"⚖️ Dầu neem hay xà phòng sinh học: chọn cái nào?"},{"type":"table","rows":[["Tiêu chí","Dầu neem","Xà phòng sinh học"],["Cách tác động","Gây chán ăn, rối loạn lột xác, làm bít thở","Làm tan lớp sáp, côn trùng mất nước"],["Tốc độ","Chậm, vài ngày","Nhanh, tác dụng ngay khi phun trúng"],["Thời gian tác dụng","Lưu lại trên lá một thời gian ngắn","Hết tác dụng khi đã khô"],["Hợp nhất với","Rệp, bọ phấn, nhện — dùng định kỳ","Đợt xử lý mạnh khi mật độ cao"],["Rủi ro cho lá","Cháy lá nếu phun nắng, phun đặc","Cháy lá non nếu pha đặc"]]},{"type":"p","text":"Nhiều người trồng cây kết hợp cả hai: xà phòng sinh học để \"giảm đông\" nhanh, sau đó dầu neem để giữ mật độ thấp. Không trộn chung hai sản phẩm khi nhãn không hướng dẫn."},{"type":"h2","text":"🌿 Cây nào dễ bị cháy lá khi phun?"},{"type":"list","items":["Cây lá mỏng, lá non mới nhú: dương xỉ, đuôi công.","Cây lá có lông tơ: lá nhung, một số loại tía tô cảnh.","Cây mọng nước có lớp phấn trắng trên lá: sen đá — phun làm mất lớp phấn, để lại vết.","Cây đang thiếu nước, đất khô: luôn tưới cây trước, phun sau."],"ordered":false},{"type":"h2","text":"🧴 Bảo quản và mua sản phẩm"},{"type":"list","items":["Chọn sản phẩm có nhãn rõ ràng, ghi thành phần, hướng dẫn pha, đối tượng sử dụng.","Dầu neem nguyên chất dễ đông đặc khi trời lạnh: ngâm chai vào nước ấm cho tan rồi lắc đều trước khi pha.","Cất nơi thoáng mát, tránh nắng, đậy kín; không đựng sang chai nước uống.","Dung dịch đã pha dùng hết trong ngày, không để qua đêm."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Pha đặc hơn hướng dẫn cho \"mạnh\"**: không diệt thêm được côn trùng mà dễ cháy lá.","**Chỉ phun mặt trên lá**: rệp, nhện, bọ phấn ở mặt dưới.","**Phun một lần rồi bỏ**: trứng nở lứa mới.","**Tự pha nước rửa chén thay xà phòng sinh học**: chất tẩy làm hại lá."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Dầu neem có hại ong không?"},{"type":"p","text":"Dầu neem ít độc hơn nhiều thuốc hóa học, nhưng vẫn có thể ảnh hưởng tới côn trùng có ích nếu phun trúng. Phun chiều mát, không phun lên hoa đang có ong bướm."},{"type":"h3","text":"Phun dầu neem lá bị bóng nhờn có sao không?"},{"type":"p","text":"Lớp dầu mỏng trên lá sẽ mất dần sau vài ngày. Nếu bóng nhờn dày, đọng giọt thì do pha đặc hoặc phun quá nhiều — lần sau phun hạt mịn hơn."},{"type":"h3","text":"Có dùng cho rau ăn được không?"},{"type":"p","text":"Có nhiều sản phẩm gốc neem, xà phòng sinh học dùng được cho rau — đọc nhãn để biết đối tượng và thời gian cách ly, rửa rau kỹ trước khi ăn."},{"type":"p","text":"Xem thêm [nhện đỏ mùa khô](/goc-cham-cay/nhen-do-mua-kho-cay-canh), [rệp sáp trên cây kiểng lá](/goc-cham-cay/tri-rep-sap-cay-kieng-la) và [đọc nhãn thuốc trước khi dùng](/goc-cham-cay/doc-nhan-thuoc-bvtv-truoc-khi-dung)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$dau-neem-xa-phong-sinh-hoc-tri-sau$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Một khu vườn thu nhỏ trong chiếc bình thủy tinh trên bàn làm việc — terrarium là món decor được nhiều bạn trẻ thích tự tay làm. Làm đúng nguyên tắc, tiểu cảnh có thể sống nhiều tháng tới nhiều năm."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Terrarium_small.jpg/960px-Terrarium_small.jpg","caption":"Tiểu cảnh terrarium trong bình thủy tinh. Ảnh: christopher*, CC BY 2.0, Wikimedia Commons"},{"type":"h2","text":"🛒 Chọn bình kín hay bình hở?"},{"type":"table","rows":[["Loại bình","Đặc điểm","Cây hợp"],["Bình kín (có nắp)","Hơi nước tuần hoàn, rất ẩm, ít phải tưới","Rêu, dương xỉ nhỏ, cây lá nhỏ ưa ẩm"],["Bình hở (miệng rộng)","Thoáng, khô nhanh","Sen đá, xương rồng, cây mọng nước"]]},{"type":"p","text":"**Không trộn** cây ưa ẩm với cây mọng nước trong cùng một bình — một bên sẽ chết."},{"type":"h2","text":"📝 Xếp lớp từ dưới lên"},{"type":"list","items":["**Sỏi nhỏ, đá cuội** dày 2–3cm: chỗ chứa nước dư (bình không có lỗ thoát).","**Than hoạt tính** một lớp mỏng: hạn chế mùi, nấm mốc.","**Rêu khô hoặc lưới mỏng**: ngăn đất lọt xuống sỏi.","**Giá thể**: bình kín dùng đất tơi giàu mùn; bình hở dùng giá thể nhiều cát, sỏi nhỏ.","Trồng cây, phủ rêu, đá, sỏi màu, tượng nhỏ trang trí."],"ordered":true},{"type":"h2","text":"🌿 Trồng cây"},{"type":"list","items":["Chọn cây nhỏ, lớn chậm; rũ bớt đất bầu, tỉa rễ dài.","Dùng nhíp dài, đũa để đặt cây qua miệng bình hẹp.","Chừa khoảng trống giữa cây và thành bình để lá không dính kính (dễ thối)."],"ordered":false},{"type":"h2","text":"💧 Tưới và chăm"},{"type":"list","items":["Bình kín: tưới phun sương nhẹ lúc mới làm; sau đó chỉ tưới khi thành bình không còn đọng hơi nước nhiều ngày. Hơi nước đọng dày cả ngày = quá ẩm, mở nắp vài giờ.","Bình hở: tưới bằng muỗng hoặc ống nhỏ giọt quanh gốc, 1–2 tuần một lần.","Ánh sáng tán xạ; **nắng chiếu thẳng vào bình làm cây \"luộc chín\"** trong vài giờ.","Lá vàng, mốc: gắp bỏ ngay, mở nắp cho thoáng."],"ordered":false},{"type":"h2","text":"❓ Vì sao terrarium bị mốc, thối?"},{"type":"p","text":"Thường do tưới quá nhiều, thiếu lớp sỏi thoát nước, hoặc dùng đất chưa sạch. Xem thêm [thối rễ](/benh-cay/thoi-re) và [đốm lá do nấm](/benh-cay/dom-la-nam)."},{"type":"h2","text":"🧰 Dụng cụ cần chuẩn bị"},{"type":"table","rows":[["Dụng cụ","Dùng để"],["Bình thủy tinh trong, sạch","Chứa tiểu cảnh — miệng rộng dễ làm hơn cho người mới"],["Nhíp dài, đũa, muỗng nhỏ","Đặt cây, rải đất qua miệng bình"],["Phễu giấy hoặc ống nhựa","Đổ sỏi, đất không làm bẩn thành bình"],["Cọ nhỏ, khăn mềm","Lau đất bám thành bình"],["Bình phun sương","Tưới nhẹ, rửa đất bám lá"],["Kéo nhỏ","Tỉa rễ, cắt lá"]]},{"type":"h2","text":"🌱 Gợi ý cây cho người mới"},{"type":"table","rows":[["Bình kín","Bình hở"],["Rêu (rêu tản, rêu cục)","Sen đá nhỏ"],["Dương xỉ nhỏ","Xương rồng mini"],["Cẩm nhung (lá gân trắng, đỏ)","Cây mọng nước dáng bò"],["Ngọc ngân, phú quý cỡ rất nhỏ","Không trồng rêu ướt trong bình hở dưới nắng"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Chọn cây con nhỏ, lớn chậm. Cây lớn nhanh sẽ chạm nắp, chạm thành bình chỉ sau vài tháng và phải thay cây."},{"type":"h2","text":"🔧 Bảo dưỡng định kỳ"},{"type":"list","items":["**Hàng tuần**: nhìn thành bình — có hơi nước nhẹ buổi sáng, tan dần trong ngày là vừa đủ ẩm (với bình kín).","**2–4 tuần**: gắp bỏ lá vàng, lá rụng; lau thành bình.","**Vài tháng**: tỉa cây chạm thành bình, cắt bớt rêu mọc dày.","**Khi cây quá lớn**: nhấc ra trồng chậu, thay cây con mới."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Đặt terrarium ở bệ cửa sổ nắng**: bình thủy tinh như nhà kính, nhiệt độ bên trong tăng rất nhanh.","**Tưới như chậu cây thường**: bình không có lỗ thoát, nước đọng làm thối rễ.","**Dùng đất vườn chưa xử lý**: mang theo trứng sâu, nấm bệnh.","**Nhồi quá nhiều cây cho đầy**: cây tranh chỗ, không thoáng, dễ mốc."],"ordered":false},{"type":"h2","text":"🎨 Mẹo bố cục cho tiểu cảnh đẹp"},{"type":"p","text":"Đặt cây cao nhất ở phía sau hoặc lệch về một bên, cây thấp và rêu ở phía trước để tạo chiều sâu. Dùng một viên đá lớn hoặc một khúc gỗ lũa nhỏ làm điểm nhấn. Tạo độ dốc nhẹ cho lớp đất — cao phía sau, thấp phía trước — nhìn sẽ tự nhiên hơn mặt phẳng. Tượng trang trí nên chọn cỡ nhỏ, ít chi tiết để không lấn át cây. Ít mà tinh luôn đẹp hơn nhồi kín."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Bình kín có cần mở nắp không?"},{"type":"p","text":"Không cần thường xuyên. Chỉ mở vài giờ khi thành bình đọng hơi nước dày suốt ngày, hoặc khi thấy mốc trắng."},{"type":"h3","text":"Terrarium sống được bao lâu?"},{"type":"p","text":"Làm đúng và bảo dưỡng, terrarium có thể đẹp nhiều tháng tới vài năm. Thay cây khi cây quá lớn là chuyện bình thường."},{"type":"h3","text":"Có làm terrarium bằng hũ, ly cũ được không?"},{"type":"p","text":"Được, miễn là thủy tinh trong, rửa sạch. Hũ miệng nhỏ khó làm hơn, nên bắt đầu với hũ miệng rộng."},{"type":"p","text":"Xem thêm [trang trí kệ sách, kệ tivi bằng cây xanh](/goc-cham-cay/trang-tri-ke-sach-bang-cay) và [tạo góc xanh cho bàn làm việc tại nhà](/goc-cham-cay/goc-xanh-ban-lam-viec-tai-nha)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$lam-tieu-canh-terrarium-binh-thuy-tinh$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Phòng làm việc giữa tòa nhà, phòng ngủ ngăn vách, quầy lễ tân không có cửa sổ — đây là môi trường khó nhất cho cây. Nói thẳng: **không cây nào sống lâu dài trong bóng tối hoàn toàn**. Nhưng với đèn và lựa chọn đúng, vẫn có cây trụ được và đẹp."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Young_snake_plant_%28Sansevieria%29_in_pot.jpg/960px-Young_snake_plant_%28Sansevieria%29_in_pot.jpg","caption":"Cây trong phòng dưới ánh đèn"},{"type":"h2","text":"🛒 5 cây chịu tối tốt nhất"},{"type":"table","rows":[["Cây","Ghi chú"],["Lưỡi hổ","Chịu tối và chịu khô bậc nhất; tưới rất thưa"],["Ngân hậu","Lá bạc, chịu bóng rất tốt"],["Bạch mã","Chịu bóng, dáng thẳng sang"],["Trầu bà đế vương xanh","Lá to, bền, chịu bóng"],["Ngọc ngân","Nhỏ gọn, có thể trồng thủy sinh"]]},{"type":"p","text":"Cây lá màu đỏ, cây ra hoa, cây mọng nước ưa nắng (ngọc bích, sen đá) **không hợp** phòng không cửa sổ."},{"type":"h2","text":"💡 Ánh đèn có đủ không?"},{"type":"list","items":["Đèn trần văn phòng bật 8–10 giờ/ngày đủ cho cây chịu bóng mạnh đặt gần đèn.","Phòng ngủ chỉ bật đèn buổi tối: không đủ — cần đèn LED trồng cây hẹn giờ.","Xem cách chọn và đặt đèn ở bài [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)."],"ordered":false},{"type":"h2","text":"🔄 Luân phiên cây"},{"type":"p","text":"Cách nhiều văn phòng dùng: có 2 bộ cây, mỗi 1–2 tuần đổi một bộ ra chỗ sáng (hành lang, ban công) và đưa bộ kia vào. Cây được \"nạp năng lượng\" nên giữ màu lá lâu hơn hẳn."},{"type":"h2","text":"💧 Tưới ít hơn bình thường"},{"type":"p","text":"Không có nắng, đất khô rất chậm. Tưới theo kiểu chỗ sáng là cây úng rễ nhanh — chỉ tưới khi mặt đất khô 2–3cm (lưỡi hổ: khô hẳn). Lá vàng từ dưới lên, đất có mùi là dấu hiệu [thối rễ](/benh-cay/thoi-re). Không bón phân nhiều — cây thiếu sáng dùng rất ít dinh dưỡng."},{"type":"h2","text":"🔍 Dấu hiệu cây đang thiếu sáng"},{"type":"list","items":["Lá mới nhỏ dần, nhạt màu.","Thân vươn dài, nghiêng về phía đèn.","Lá già rụng dần, tán thưa."],"ordered":false},{"type":"h2","text":"🔆 Thiết lập \"cửa sổ nhân tạo\" bằng đèn"},{"type":"list","items":["Chọn đèn LED trồng cây ánh trắng toàn phổ (dễ chịu cho mắt trong phòng ở).","Treo hoặc kẹp đèn cách ngọn cây khoảng 40–60cm với cây chịu bóng.","Cắm qua ổ cắm hẹn giờ: bật khoảng 10–12 giờ mỗi ngày, cùng một khung giờ.","Sau 2–3 tuần, quan sát lá mới: lá ngắn đốt, xanh đều là đủ sáng; vẫn vươn dài thì hạ đèn xuống."],"ordered":true},{"type":"p","text":"Xem chi tiết cách chọn công suất, khoảng cách ở bài [đèn LED trồng cây trong nhà](/goc-cham-cay/den-led-trong-cay-trong-nha)."},{"type":"h2","text":"🏢 Gợi ý theo từng kiểu phòng"},{"type":"table","rows":[["Kiểu phòng","Gợi ý bố trí"],["Phòng ngủ không cửa sổ","1–2 chậu lưỡi hổ, ngân hậu + đèn LED hẹn giờ ban ngày"],["Quầy lễ tân giữa tòa nhà","Bạch mã, trầu bà đế vương chậu lớn dưới đèn trần bật cả ngày; luân phiên cây"],["Phòng họp kín","Cây nhỏ trên bàn, mang ra ngoài sáng mỗi tuần"],["Nhà vệ sinh không cửa sổ","Lưỡi hổ mini luân phiên — xem [cây xanh cho phòng tắm](/goc-cham-cay/cay-xanh-cho-phong-tam-nha-ve-sinh)"],["Hành lang, cầu thang tối","Cây chịu bóng chậu nhẹ để dễ đổi chỗ"]]},{"type":"h2","text":"🔄 Khi nào nên dùng cây giả, cây khô?"},{"type":"p","text":"Có những vị trí gần như không có ánh sáng tự nhiên, không thể gắn đèn và không ai luân phiên cây — ví dụ góc kho, phòng máy. Ở đó, cây giả chất lượng tốt hoặc tiểu cảnh khô là lựa chọn thực tế hơn là để cây thật chết dần. Cây thật nên dành cho những chỗ bạn có thể chăm."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Tin rằng có cây \"không cần ánh sáng\"**: mọi cây xanh đều cần sáng để quang hợp; cây chịu bóng chỉ cần ít hơn.","**Tưới theo lịch của cây ở chỗ sáng**: phòng tối đất khô rất chậm, cây úng nhanh.","**Mua cây lá màu sặc sỡ cho phòng tối**: màu phai dần trong vài tuần.","**Bật đèn 24/24**: cây cần thời gian tối để nghỉ."],"ordered":false},{"type":"h2","text":"🧹 Lau lá thường xuyên hơn"},{"type":"p","text":"Ở phòng thiếu sáng, mỗi chút ánh sáng đều quý. Lớp bụi mỏng trên lá cũng đủ cản bớt ánh sáng mà cây nhận được. Lau lá bằng khăn ẩm 1–2 tuần một lần, đỡ mặt dưới lá bằng tay để lá không gãy. Không dùng dầu ăn, sữa, chất đánh bóng lá — chúng bít lỗ khí và bám thêm bụi. Xem [lau lá, cắt tỉa cây kiểng lá](/goc-cham-cay/lau-la-cat-tia-cay-kieng-la)."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây trong phòng không cửa sổ sống được bao lâu?"},{"type":"p","text":"Không có đèn và không luân phiên, cây chịu bóng tốt nhất thường chỉ đẹp vài tháng rồi yếu dần. Có đèn trồng cây hoặc luân phiên đều, cây có thể sống nhiều năm."},{"type":"h3","text":"Đèn LED thường trong nhà có dùng được không?"},{"type":"p","text":"Đèn LED trắng thường vẫn giúp được phần nào nếu đặt gần cây và bật đủ giờ, nhưng kém hơn đèn trồng cây chuyên dụng."},{"type":"h3","text":"Phòng không cửa sổ có nên đặt nhiều cây để lọc không khí?"},{"type":"p","text":"Lượng cây đặt trong nhà không đủ để lọc không khí đáng kể. Phòng kín cần thông gió, máy lọc không khí; cây chủ yếu tạo cảm giác dễ chịu."},{"type":"p","text":"Xem thêm [cây trồng trong nhà thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang) và [cây văn phòng chịu bóng, ít tưới](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi)."},{"type":"products","title":"Cây chịu tối tại vườn","slugs":["luoi-ho","ngan-hau","bach-ma-hoang-tu","trau-ba-de-vuong-xanh","ngoc-ngan"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-trong-phong-khong-cua-so$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Cây kiểng trong phòng khách tự nhiên có cả đám ruồi đen nhỏ như muỗi, bay lởn vởn quanh chậu và cả quanh màn hình máy tính. Đây là **ruồi nấm đất** (fungus gnat) — gần như lúc nào cũng báo hiệu một điều: **đất chậu đang quá ẩm**."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Dark-winged_Fungus_Gnat_%288009220744%29.jpg/960px-Dark-winged_Fungus_Gnat_%288009220744%29.jpg","caption":"Ruồi nấm đất trưởng thành — nhỏ, đen, chân dài như muỗi. Ảnh: John Tann from Sydney, Australia, CC BY 2.0, Wikimedia Commons"},{"type":"h2","text":"🔍 Nhận biết ruồi nấm đất"},{"type":"list","items":["Ruồi nhỏ 2–3mm, màu đen xám, chân dài, bay chậm, hay đậu trên mặt đất chậu.","Tưới nước xong, chúng bay lên từ mặt đất.","Ấu trùng là con dòi trắng nhỏ, đầu đen, sống ở lớp đất mặt 2–5cm.","Khác ruồi giấm (thân nâu vàng, mắt đỏ, bay quanh trái cây chín)."],"ordered":false},{"type":"h2","text":"🔎 Ruồi nấm đất có hại cây không?"},{"type":"p","text":"Con trưởng thành chỉ gây phiền. Ấu trùng ăn nấm, mùn trong đất, nhưng khi đông chúng ăn cả **rễ non, hom giâm, cây con mới gieo**, làm cây con đổ rạp. Đất ẩm kéo dài cũng là điều kiện dẫn tới [thối rễ](/benh-cay/thoi-re) — nên ruồi nấm là lời nhắc bạn đang tưới quá tay."},{"type":"h2","text":"🛠️ Cách diệt ruồi nấm đất"},{"type":"list","items":["**Để đất khô lớp mặt**: chờ mặt đất khô 2–3cm rồi mới tưới. Ấu trùng chết khi lớp đất mặt khô. Đây là bước quan trọng nhất (xem [tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach)).","**Bẫy dính màu vàng** cắm trên mặt chậu để bắt con trưởng thành, cắt đứt vòng đẻ trứng.","**Tưới từ đáy**: đặt chậu vào khay nước 15–20 phút cho đất hút từ dưới lên, mặt đất luôn khô hơn.","**Phủ mặt chậu** lớp cát, sỏi nhỏ hoặc đá trang trí dày 1–2cm, ruồi khó đẻ trứng xuống đất.","Bỏ lá rụng, xác hoa trên mặt chậu; đổ nước đọng dưới đĩa.","Đất mục, có mùi hôi: thay đất mới thoát nước tốt."],"ordered":true},{"type":"p","text":"Thường sau 2–3 tuần giữ đất khô mặt và đặt bẫy, đám ruồi giảm hẳn."},{"type":"h2","text":"🛡️ Phòng ruồi nấm"},{"type":"p","text":"Dùng giá thể thoát nước (xơ dừa, trấu hun, đá perlite) thay vì đất thịt nặng ([tự trộn đất](/goc-cham-cay/tron-dat-trong-cay-kieng-la)); không dùng phân hữu cơ chưa hoai trong chậu để trong nhà; chậu có lỗ thoát nước."},{"type":"h2","text":"🧪 Thử nhanh: đất có ấu trùng không?"},{"type":"p","text":"Cắt một lát khoai tây sống dày khoảng 1cm, đặt úp lên mặt đất chậu. Sau 2–3 ngày lật lên: nếu thấy những con dòi trắng nhỏ đầu đen bám ở mặt dưới lát khoai, đất đang có ấu trùng ruồi nấm. Cách này giúp biết chậu nào bị nặng để xử lý trước, và kiểm tra sau xử lý đã sạch chưa."},{"type":"h2","text":"🔄 Vòng đời ruồi nấm đất"},{"type":"p","text":"Ruồi cái đẻ trứng vào lớp đất mặt ẩm, giàu mùn. Trứng nở thành ấu trùng sống trong đất khoảng 1–2 tuần, hóa nhộng rồi thành ruồi trưởng thành. Cả vòng đời chỉ khoảng 3–4 tuần trong điều kiện ấm áp. Vì vậy phải duy trì đất khô mặt và đặt bẫy **liên tục ít nhất 3–4 tuần** mới cắt được hết các lứa."},{"type":"h2","text":"📅 Kế hoạch xử lý 4 tuần"},{"type":"table","rows":[["Tuần","Việc cần làm"],["Tuần 1","Cạo bỏ 1–2cm đất mặt, thay đất khô; cắm bẫy dính vàng; ngưng tưới cho tới khi mặt đất khô"],["Tuần 2","Chuyển sang tưới từ đáy; phủ cát hoặc sỏi mặt chậu; thay bẫy khi dính kín"],["Tuần 3","Kiểm tra bằng lát khoai tây; số ruồi trên bẫy phải giảm rõ"],["Tuần 4","Duy trì cách tưới mới; gỡ bớt bẫy nếu không còn ruồi"]]},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Một số sản phẩm sinh học diệt ấu trùng trong đất (như chế phẩm chứa vi khuẩn Bti) có bán ở cửa hàng vật tư. Nếu dùng, làm theo đúng hướng dẫn trên nhãn."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chỉ dùng bình xịt côn trùng diệt ruồi bay**: ấu trùng trong đất vẫn còn, ruồi mới tiếp tục nở.","**Tưới quế, tỏi, giấm vào đất**: hiệu quả không chắc chắn, có thể hại rễ.","**Giữ thói quen tưới mỗi ngày**: đất mặt luôn ẩm, ruồi không bao giờ hết.","**Để cây giâm, khay ươm cạnh chậu bị ruồi**: ấu trùng ăn rễ non, cây con chết."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Ruồi nấm đất có cắn người không?"},{"type":"p","text":"Không. Chúng không cắn, không truyền bệnh cho người, chỉ gây phiền vì bay quanh mặt, màn hình."},{"type":"h3","text":"Thay toàn bộ đất mới có hết ruồi không?"},{"type":"p","text":"Thường là có, nếu đất mới thoát nước tốt và bạn đổi cách tưới. Nếu vẫn tưới nhiều như cũ, ruồi sẽ quay lại theo cây khác trong nhà."},{"type":"h3","text":"Sao nhà không có cây mà vẫn có ruồi nhỏ?"},{"type":"p","text":"Có thể là ruồi giấm (quanh trái cây chín, thùng rác) hoặc ruồi cống (quanh ống thoát nước). Mỗi loại cần xử lý nguồn sinh sản khác nhau."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$ruoi-nho-bay-quanh-chau-cay$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Phòng ngủ không cửa sổ, quầy lễ tân sâu trong tòa nhà, kệ sách góc tối — những chỗ đó đèn trần thường không đủ cho cây. Một bóng đèn LED trồng cây có thể biến chỗ \"cây nào cũng chết\" thành chỗ trồng được."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/LED_panel_and_plants.jpg/960px-LED_panel_and_plants.jpg","caption":"Cây trồng dưới đèn LED trong nhà"},{"type":"h2","text":"🔎 Khi nào cần đèn trồng cây?"},{"type":"list","items":["Phòng không có cửa sổ hoặc cửa sổ bị che hoàn toàn.","Cây đặt cách cửa sổ trên 3m.","Cây đã vống, lá nhạt dần dù tưới bón đúng (xem [ánh sáng cho cây trong nhà](/goc-cham-cay/anh-sang-cho-cay-trong-nha)).","Muốn trồng cây ưa sáng (sen đá, ngọc bích, rau thơm) trong nhà."],"ordered":false},{"type":"h2","text":"🛒 Chọn đèn nào?"},{"type":"table","rows":[["Loại đèn","Ưu điểm","Nhược điểm"],["LED trắng toàn phổ (full spectrum)","Ánh sáng tự nhiên, dễ nhìn, hợp phòng ở","Cường độ có hạn với bóng nhỏ"],["LED tím hồng (đỏ + xanh dương)","Hiệu quả cao cho cây","Ánh tím khó chịu cho mắt, nhìn màu cây sai"],["Bóng LED trắng thường (6500K)","Rẻ, dễ mua","Kém hơn đèn chuyên dụng, cần đặt gần"]]},{"type":"p","text":"Với cây kiểng lá trong phòng ở, **LED trắng toàn phổ** là lựa chọn dễ chịu nhất. Đèn tím hợp kệ ươm cây con, tủ trồng rau mầm."},{"type":"h2","text":"📏 Đặt đèn cách cây bao xa?"},{"type":"list","items":["Cây kiểng lá chịu bóng: 40–60cm từ ngọn.","Cây ưa sáng, cây mọng nước, rau: 20–30cm.","Lá bạc màu, cháy đốm ngay dưới đèn: đèn quá gần, nâng lên.","Cây vẫn vươn dài về phía đèn: đèn còn xa hoặc yếu, hạ xuống."],"ordered":false},{"type":"h2","text":"⏱️ Bật bao nhiêu giờ mỗi ngày?"},{"type":"p","text":"Cây kiểng lá: **10–12 giờ/ngày**; cây ưa sáng: 12–14 giờ. Cây cần cả thời gian tối để nghỉ — đừng bật 24/24. Dùng **ổ cắm hẹn giờ** để đèn bật tắt đều đặn, không phụ thuộc trí nhớ."},{"type":"h2","text":"⚠️ Lưu ý an toàn"},{"type":"list","items":["Chọn đèn có chứng nhận, dây điện xa chỗ tưới nước.","Không đặt đèn sát lá — dù LED ít nóng, lá sát bóng vẫn có thể cháy.","Cây dưới đèn khô đất nhanh hơn một chút, kiểm tra độ ẩm đất thường xuyên hơn."],"ordered":false},{"type":"h2","text":"🔢 Đọc thông số đèn trên bao bì"},{"type":"table","rows":[["Thông số","Ý nghĩa","Lưu ý khi chọn"],["Công suất (W)","Điện năng tiêu thụ","Không nói chính xác cây nhận bao nhiêu sáng; so sánh trong cùng loại đèn"],["Nhiệt độ màu (K)","Màu ánh sáng: 3000K vàng ấm, 6500K trắng lạnh","Đèn trồng cây trắng thường khoảng 4000–6500K"],["\"Full spectrum\" (toàn phổ)","Ánh sáng trải đều nhiều màu","Hợp phòng ở, nhìn cây đúng màu"],["PPF / PPFD (nếu có)","Lượng ánh sáng cây dùng được","Thông số đáng tin nhất khi so sánh đèn chuyên dụng"],["Chứng nhận an toàn","Đèn và bộ nguồn đạt chuẩn","Ưu tiên đèn có xuất xứ, bảo hành rõ"]]},{"type":"h2","text":"🧩 Ba cách lắp đèn phổ biến"},{"type":"list","items":["**Đèn kẹp cổ ngỗng**: rẻ, linh hoạt, hợp 1–2 chậu trên bàn, kệ.","**Thanh LED dán dưới kệ**: hợp kệ nhiều tầng trồng cây nhỏ, rau mầm.","**Bóng đèn trồng cây đuôi E27**: thay vào đèn bàn, đèn treo có sẵn — tiện cho phòng khách."],"ordered":false},{"type":"h2","text":"💸 Tiền điện có đáng lo không?"},{"type":"p","text":"Đèn LED trồng cây gia đình thường có công suất nhỏ. Ví dụ một bóng 15W bật 12 giờ mỗi ngày tiêu thụ khoảng 15 × 12 × 30 = 5.400Wh, tức khoảng 5,4 số điện mỗi tháng. Chi phí cụ thể tùy bậc giá điện nhà bạn, nhưng thường không đáng kể so với các thiết bị khác."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Treo đèn quá xa** (trên trần nhà) rồi kết luận đèn vô dụng: ánh sáng giảm rất nhanh theo khoảng cách.","**Bật đèn ban đêm cho cây \"ăn thêm\"**: cây vẫn cần giai đoạn tối; nên bật vào ban ngày.","**Dùng đèn tím trong phòng khách**: ánh tím mỏi mắt, khó nhìn màu.","**Dây điện, ổ cắm đặt dưới chậu cây**: nước tưới chảy xuống gây chập điện."],"ordered":false},{"type":"h2","text":"🌿 Cây nào hợp trồng dưới đèn?"},{"type":"list","items":["**Rất hợp**: cây kiểng lá chịu bóng (trầu bà, ngọc ngân, ngân hậu, lưỡi hổ) — cần ít sáng, đèn nhỏ là đủ.","**Hợp nếu đèn đủ mạnh, đặt gần**: rau thơm, rau mầm, sen đá, cây lá màu.","**Khó**: cây ăn trái, cây ra hoa cần nắng mạnh — đèn gia đình khó cung cấp đủ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Đèn LED có làm cây cháy lá không?"},{"type":"p","text":"Có nếu đặt quá gần, nhất là đèn công suất lớn. Lá bạc màu hoặc cháy đốm ngay dưới đèn là dấu hiệu cần nâng đèn lên."},{"type":"h3","text":"Có cần tắt đèn khi trời nắng?"},{"type":"p","text":"Nếu cây đã có cửa sổ sáng, đèn chỉ bổ sung vào những giờ thiếu sáng (sáng sớm, chiều tối, ngày âm u). Cây trong phòng tối hoàn toàn thì bật theo hẹn giờ cố định."},{"type":"h3","text":"Rau thơm trồng dưới đèn có ăn được không?"},{"type":"p","text":"Được. Rau thơm, rau mầm trồng dưới đèn vẫn quang hợp bình thường; chỉ cần đèn đủ mạnh và đặt gần."},{"type":"p","text":"Muốn chọn cây ít cần sáng? Xem [cây trồng trong nhà thiếu sáng](/goc-cham-cay/cay-trong-nha-thieu-sang)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$den-led-trong-cay-trong-nha$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Rau ngót nấu canh thịt bằm là món dân dã ai cũng biết. Cây sống lâu năm, càng cắt càng ra ngọn, trồng vài khóm cạnh hàng rào là gần như cả năm không phải mua rau ngót."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Sauropus_androgynous_7816.jpg/960px-Sauropus_androgynous_7816.jpg","caption":"Khóm rau ngót. Ảnh: Vengolis, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🌱 Giâm cành rau ngót"},{"type":"list","items":["Chọn cành bánh tẻ (không quá non, không quá già), to bằng chiếc đũa trở lên.","Cắt đoạn dài 20–25cm, có 4–5 mắt, tuốt bỏ lá.","Cắm nghiêng 45° vào đất ẩm, vùi 1/2 – 2/3 chiều dài cành.","Giữ đất ẩm, để chỗ râm nhẹ; sau 2–3 tuần cành ra chồi lá mới."],"ordered":true},{"type":"h2","text":"🪴 Đất, chậu, chỗ trồng"},{"type":"list","items":["Trồng đất vườn hoặc thùng xốp, chậu sâu 25–30cm.","Đất tơi, giàu mùn; trộn phân chuồng hoai khi trồng.","Ưa nắng sáng nhưng chịu bóng một phần — hợp góc sân ít nắng.","Trồng hàng rào: cắm cành cách nhau 15–20cm thành hàng."],"ordered":false},{"type":"h2","text":"💧 Tưới và bón"},{"type":"p","text":"Rau ngót thích đất ẩm: mùa nắng tưới mỗi ngày, mùa mưa giảm. Sau mỗi lần cắt, rắc phân hữu cơ hoặc tưới nước phân trùn quế loãng để cây nhanh ra ngọn mới."},{"type":"h2","text":"✂️ Thu hoạch"},{"type":"p","text":"Khi cây cao 40–50cm, cắt ngọn non dài 15–20cm. Mỗi lần cắt, chừa lại vài mắt để cây đâm nhánh. Định kỳ vài tháng đốn thấp toàn bộ khóm còn 30–40cm cho cây ra lứa ngọn mới mập, lá non mềm."},{"type":"note","title":"💡 Lưu ý khi ăn","text":"Rau ngót là rau ăn phổ biến khi nấu chín. Không nên ăn sống, ép nước uống lượng lớn. Phụ nữ mang thai nên hỏi ý kiến bác sĩ về lượng rau ngót trong khẩu phần, theo khuyến cáo phổ biến."},{"type":"h2","text":"📅 Lịch trồng rau ngót"},{"type":"table","rows":[["Thời gian","Việc cần làm"],["Tuần 0","Cắt cành giâm, cắm nghiêng vào đất ẩm, để chỗ râm nhẹ"],["Tuần 2–3","Cành ra chồi lá mới — bắt đầu cho ra nắng sáng dần"],["Tháng 2","Bón phân hữu cơ quanh gốc, bấm ngọn để cây đâm nhánh"],["Tháng 2–3","Cây cao 40–50cm, bắt đầu cắt ngọn ăn"],["Vài tháng một lần","Đốn thấp cả khóm còn 30–40cm, bón phân để ra lứa mới"]]},{"type":"p","text":"Đầu mùa mưa là lúc giâm cành rau ngót dễ sống nhất ở miền Tây, vì đất ẩm tự nhiên, ít phải tưới."},{"type":"h2","text":"🐛 Sâu bệnh hay gặp trên rau ngót"},{"type":"table","rows":[["Vấn đề","Dấu hiệu","Xử lý"],["Rệp sáp","Mảng trắng như bông ở ngọn, nách lá","Cắt bỏ ngọn bị nặng, xịt nước mạnh"],["Bệnh phấn trắng","Lớp bột trắng mặt lá, lá vàng","Cắt tỉa cho thoáng, ngắt lá bệnh — xem [phấn trắng](/benh-cay/phan-trang)"],["Sâu ăn lá","Lá thủng, ngọn bị cắn","Bắt tay, kiểm tra buổi sáng"],["Lá vàng, cây cằn","Lâu không bón, đất bạc màu","Bón phân hữu cơ, phân trùn quế sau mỗi lần cắt"]]},{"type":"h2","text":"🌿 Muốn lá to, ngọn mập"},{"type":"list","items":["Cắt thường xuyên — cây càng được cắt càng ra nhiều ngọn non.","Bón phân hữu cơ đều đặn sau mỗi lần cắt.","Tưới đủ nước mùa khô; thiếu nước lá nhỏ, cứng.","Đốn trẻ hóa khóm khi thân đã già, lá nhỏ dần."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Giâm cành quá non hoặc quá già**: cành non dễ thối, cành già lâu ra rễ.","**Cắm thẳng đứng, vùi quá nông**: cành dễ đổ, ít ra rễ.","**Để cây mọc cao vống không cắt**: ngọn ít, lá thưa, khó hái.","**Phun thuốc lên rau đang ăn**: ưu tiên cắt bỏ phần bị hại."],"ordered":false},{"type":"h2","text":"🌱 Nhân thêm khóm rau ngót"},{"type":"p","text":"Khi khóm rau ngót đã lớn, mỗi lần đốn trẻ hóa sẽ có rất nhiều cành bánh tẻ. Đừng bỏ đi: chọn những cành to, khỏe, cắt thành đoạn 20–25cm rồi giâm tiếp thành hàng mới hoặc chia cho hàng xóm. Giâm vào đầu mùa mưa tỷ lệ sống cao nhất. Nếu giâm trong mùa khô, cắm cành vào bầu đất, đặt dưới bóng râm, tưới mỗi ngày cho tới khi cành ra chồi mới rồi mới đem trồng ra chỗ nắng."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Rau ngót trồng chậu được không?"},{"type":"p","text":"Được, với chậu hoặc thùng sâu 25–30cm trở lên. Rau ngót trồng chậu cần tưới và bón đều hơn vì đất ít."},{"type":"h3","text":"Bao lâu thì rau ngót được hái lứa đầu?"},{"type":"p","text":"Thường khoảng 2–3 tháng sau giâm cành tùy điều kiện chăm. Sau đó có thể cắt định kỳ."},{"type":"h3","text":"Rau ngót có cần nhiều nắng không?"},{"type":"p","text":"Rau ngót ưa nắng sáng nhưng chịu bóng một phần. Trồng nơi râm quá thì thân dài, lá nhỏ, ít ngọn."},{"type":"p","text":"Xem thêm [trồng rau muống thùng xốp](/goc-cham-cay/trong-rau-muong-thung-xop) và [ủ phân hữu cơ từ rác bếp](/goc-cham-cay/u-phan-huu-co-tu-rac-bep)."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$trong-rau-ngot-tai-nha$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Ở miền Tây, nhiều nhà có sẵn tro bếp củi, tro trấu và quen dùng vôi để cải tạo đất phèn. Dùng đúng thì đất bớt chua, cây khỏe; dùng quá tay thì đất kiềm, cây vàng lá vì không hút được sắt."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Wood_ash.jpg/960px-Wood_ash.jpg","caption":"Tro bếp từ củi, rơm. Ảnh: Laurentius, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"📖 Tro bếp có gì?"},{"type":"list","items":["Chủ yếu **kali** và **canxi**, ít lân; không có đạm.","Tính kiềm: làm giảm độ chua của đất.","Chỉ dùng tro từ củi, rơm, trấu, lá khô. **Không dùng** tro than đá, tro đốt nhựa, giấy in màu, gỗ sơn."],"ordered":false},{"type":"h2","text":"📖 Vôi bột dùng làm gì?"},{"type":"p","text":"Vôi (vôi bột nông nghiệp, vôi dolomite) dùng để **khử chua, cải tạo đất phèn**, bổ sung canxi (dolomite có thêm magie). Vôi sống (vôi cục) nóng, ăn da — không rải trực tiếp quanh gốc cây đang sống."},{"type":"h2","text":"🔎 Khi nào nên dùng?"},{"type":"list","items":["Đất chua, phèn: nước ruộng, mương có váng vàng đỏ, đất có mùi chua, cây chậm lớn.","Lúc làm đất trước khi trồng — trộn vôi, tưới ẩm, chờ 2–3 tuần rồi mới trồng.","Tro bếp rắc mỏng quanh luống rau ngoài trời để bổ sung kali, và làm vành khô ngăn [ốc sên](/benh-cay/oc-sen).","Có bút, giấy đo pH đất thì tốt nhất: chỉ bón khi đất thật sự chua."],"ordered":false},{"type":"h2","text":"⚠️ Khi nào không dùng?"},{"type":"list","items":["Cây ưa đất chua (nhiều loại lan, cây họ đỗ quyên) — tro, vôi làm cây vàng lá.","Chậu cây kiểng trong nhà dùng giá thể sẵn: thường không cần.","**Không trộn chung tro, vôi với phân đạm** (urê, phân chuồng tươi): đạm bay hơi mất tác dụng. Bón cách nhau ít nhất 1–2 tuần.","Không rải dày sát gốc, không bón khi đất khô kiệt."],"ordered":false},{"type":"h2","text":"📏 Liều lượng tham khảo"},{"type":"p","text":"Tro bếp: một nắm nhỏ (khoảng 1–2 muỗng canh) cho chậu đường kính 30cm, vài tháng một lần; luống rau rắc mỏng như rắc muối. Vôi cải tạo đất: theo hướng dẫn trên bao, thường vài trăm gam cho mỗi mét vuông đất chua, trộn đều. Ít mà đều tốt hơn nhiều một lần."},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Vôi bột và tro bếp có tính kiềm, có thể gây rát da, hại mắt. Đeo găng tay, khẩu trang khi rải, tránh ngày gió, để xa tầm tay trẻ nhỏ."},{"type":"h2","text":"🧪 Đo pH đất đơn giản tại nhà"},{"type":"list","items":["Lấy đất ở vài chỗ trong luống (hoặc trong chậu), độ sâu 5–15cm, trộn đều.","Cho một phần đất vào ly sạch, thêm khoảng gấp đôi lượng nước cất hoặc nước mưa, khuấy đều.","Để lắng 15–30 phút, nhúng giấy quỳ đo pH hoặc dùng bút đo vào phần nước trong.","So màu hoặc đọc số: dưới 5,5 là đất chua; khoảng 6–7 là phù hợp với phần lớn cây trồng."],"ordered":true},{"type":"p","text":"Bút đo pH đất loại cắm trực tiếp cũng có bán ở cửa hàng vật tư nông nghiệp. Độ chính xác không cao như phòng thí nghiệm nhưng đủ để biết đất có chua rõ rệt hay không."},{"type":"h2","text":"🌱 Cây nào thích, cây nào ngại tro và vôi?"},{"type":"table","rows":[["Nhóm","Ví dụ","Tro / vôi"],["Ưa đất trung tính đến hơi kiềm","Rau cải, rau dền, cà chua, mai vàng trồng đất phèn","Dùng vừa phải khi đất chua"],["Ưa đất hơi chua","Lan, dứa cảnh, nhiều loại cây kiểng lá","Hạn chế, chậu giá thể không cần"],["Cây trồng chậu giá thể pha sẵn","Hầu hết cây kiểng trong nhà","Thường không cần bổ sung"],["Ruộng, vườn đất phèn","Cây ăn trái, rau màu ngoài trời","Vôi cải tạo theo hướng dẫn, chia nhiều lần"]]},{"type":"h2","text":"🔁 Thứ tự bón khi cải tạo luống đất phèn"},{"type":"list","items":["Làm đất, rải vôi theo hướng dẫn, xới trộn đều, tưới ẩm.","Chờ khoảng 2–3 tuần cho vôi phản ứng với đất.","Bón lót phân hữu cơ hoai mục, trộn đều.","Gieo trồng; các đợt bón đạm sau cách lần bón vôi ít nhất 1–2 tuần."],"ordered":true},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Rắc tro, vôi theo thói quen mỗi vụ** mà không kiểm tra đất: đất thành kiềm, cây vàng lá non.","**Trộn vôi chung với phân chuồng, urê** cho tiện: mất đạm, có mùi khai.","**Dùng tro đốt rác lẫn nhựa, túi ni lông**: tro chứa chất độc hại.","**Rải vôi sống quanh gốc cây đang trồng**: cháy rễ, cháy cổ thân."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Tro trấu và tro củi có khác nhau không?"},{"type":"p","text":"Tro trấu nhẹ, xốp, nhiều silic, ít kali hơn tro củi. Trấu hun (trấu đốt chưa cháy hết, còn đen) là giá thể làm đất tơi, khác với tro trắng đã cháy hết."},{"type":"h3","text":"Có dùng vôi để trị nấm bệnh không?"},{"type":"p","text":"Nhà vườn đôi khi rắc vôi quanh chỗ nhổ bỏ cây bệnh để khử trùng đất. Cách này chỉ là biện pháp phụ, không thay thế được việc chọn giống khỏe, thoát nước tốt."},{"type":"h3","text":"Bao lâu bón vôi một lần?"},{"type":"p","text":"Tùy độ chua của đất; nhiều vùng chỉ cần một lần mỗi năm hoặc vài vụ một lần. Nên đo pH trước mỗi lần cải tạo."},{"type":"p","text":"Xem thêm [phòng mặn cho cây sân vườn mùa khô](/goc-cham-cay/phong-man-cho-cay-san-vuon) và [vàng lá gân xanh do thiếu sắt](/benh-cay/vang-la-thieu-sat)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$tro-bep-voi-bot-cho-cay-khi-nao-dung$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Thay đất, bón phân hữu cơ được vài tuần, mặt chậu bỗng phủ một lớp mốc trắng như bông gòn hay như rắc bột. Phần lớn trường hợp đây là nấm \"dọn rác\" đang phân hủy mùn trong đất — không nguy hiểm, nhưng là dấu hiệu chậu đang quá ẩm."},{"type":"h2","text":"🔎 Vì sao mặt đất chậu bị mốc trắng?"},{"type":"list","items":["Đất ẩm kéo dài, tưới quá nhiều hoặc chậu không thoát nước.","Chậu đặt chỗ kín gió, thiếu sáng (góc phòng, gầm cầu thang).","Trộn phân chuồng, phân trùn quế, xơ dừa, trấu chưa hoai: nấm phát triển để phân hủy chúng.","Mùa mưa ở miền Tây không khí ẩm cao, mốc mọc nhanh hơn."],"ordered":false},{"type":"h2","text":"⚠️ Mốc nào đáng lo?"},{"type":"p","text":"Cần phân biệt với **nấm hạch trắng** gây [thối gốc](/benh-cay/thoi-goc-nam-hach): tơ trắng **bao quanh cổ rễ, bò lên gốc thân**, kèm những hạt tròn nhỏ như hạt cải màu trắng rồi nâu; gốc cây thâm, cây héo. Trường hợp này phải xử lý ngay. Còn mốc chỉ nằm trên mặt đất, cách xa gốc, cây vẫn xanh tốt thì không đáng lo."},{"type":"h2","text":"🛠️ Xử lý mốc trên mặt chậu"},{"type":"list","items":["Cạo bỏ lớp đất mặt 1–2cm có mốc, thay bằng đất sạch khô.","Giảm tưới: chờ mặt đất khô mới tưới lại.","Dời chậu ra chỗ thoáng, có ánh sáng; xới nhẹ mặt đất cho thông khí.","Có thể rắc mỏng một lớp quế bột hoặc than hoạt tính lên mặt đất — cách dân gian giúp hạn chế nấm.","Đổ bỏ nước đọng dưới đĩa."],"ordered":false},{"type":"h2","text":"🛡️ Phòng mốc tái phát"},{"type":"p","text":"Chỉ dùng phân hữu cơ đã hoai hẳn (không mùi hôi, tơi vụn); dùng giá thể thoát nước; trộn chế phẩm [Trichoderma](/goc-cham-cay/trichoderma-che-pham-sinh-hoc) khi thay đất để nấm có ích lấn át nấm hại. Xem thêm [phân hữu cơ cho cây cảnh dùng sao cho không hôi](/goc-cham-cay/phan-huu-co-cho-cay-canh)."},{"type":"h2","text":"🔍 Phân biệt các loại \"mốc trắng\" thường gặp"},{"type":"table","rows":[["Hình dạng","Có thể là","Mức độ"],["Tơ trắng mịn như bông, chỉ trên mặt đất","Nấm hoại sinh phân hủy mùn","Không đáng lo — giảm ẩm"],["Lớp bột, váng trắng khô cứng, sờ sạn","Muối khoáng, phân bón tích tụ","Không phải nấm — tưới rửa đất"],["Tơ trắng bò lên gốc, kèm hạt tròn nhỏ","Nấm hạch trắng","Nguy hiểm — xử lý ngay"],["Đám bông trắng bò, bóp ra có con","Rệp sáp","Côn trùng — xử lý như rệp sáp"],["Nấm mũ nhỏ màu vàng, trắng mọc lên","Nấm hoại sinh trong đất giàu mùn","Không hại cây — nhổ bỏ, không cho trẻ chạm"]]},{"type":"p","text":"Lớp váng trắng do muối khoáng thường gặp ở chậu đất nung, chậu tưới nước cứng, bón phân hòa tan thường xuyên. Xem thêm [tưới cây bằng nước gì tốt nhất](/goc-cham-cay/tuoi-cay-bang-nuoc-gi-tot)."},{"type":"h2","text":"🍄 Nấm mũ mọc lên trong chậu có sao không?"},{"type":"p","text":"Mùa mưa, đôi khi chậu cây mọc lên những cây nấm nhỏ màu vàng hoặc trắng. Đó là phần \"quả thể\" của nấm hoại sinh sống trong đất giàu mùn, không hại cây. Tuy nhiên, không nên để trẻ nhỏ, thú cưng chạm hoặc ăn — nhổ bỏ cả gốc nấm, cạo lớp đất mặt và giảm tưới."},{"type":"h2","text":"🌱 Trộn đất chậu ít bị mốc"},{"type":"list","items":["Dùng đất sạch, giá thể đóng bao có nguồn gốc rõ ràng.","Thêm vật liệu thoát nước: trấu hun, perlite, xơ dừa đã xả chát.","Phân hữu cơ phải hoai hẳn, không trộn quá nhiều vào chậu nhỏ trong nhà.","Có thể trộn chế phẩm Trichoderma theo hướng dẫn — xem [tự trộn đất trồng cây kiểng lá](/goc-cham-cay/tron-dat-trong-cay-kieng-la)."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Phun thuốc trị nấm lên mặt đất cho mốc hoại sinh**: không cần thiết, tốn kém.","**Chỉ cạo mốc mà không đổi cách tưới**: mốc mọc lại trong vài ngày.","**Bỏ qua mốc bò lên gốc**: nhầm nấm hạch trắng với mốc vô hại."],"ordered":false},{"type":"h2","text":"🌧️ Mùa mưa: vì sao mốc mọc khắp nơi?"},{"type":"p","text":"Những tuần mưa dầm, không khí ẩm cao, đất chậu khô rất chậm và ánh sáng yếu — điều kiện lý tưởng cho nấm hoại sinh. Trong giai đoạn này nên giãn lịch tưới, đưa chậu ngoài trời vào chỗ có mái che, kê cao khỏi nền để nước mưa không đọng đáy chậu. Xem thêm [chăm cây mùa mưa miền Tây](/goc-cham-cay/cham-cay-mua-mua-mien-tay) để chuẩn bị cho cả vườn."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Mốc trắng có lây sang cây khác không?"},{"type":"p","text":"Mốc hoại sinh có mặt ở hầu hết đất, không \"lây\" theo kiểu bệnh. Chậu nào ẩm và nhiều mùn thì mốc mọc. Nấm hạch trắng thì có thể lây qua đất, nước — cần cách ly chậu bệnh."},{"type":"h3","text":"Có cần thay toàn bộ đất khi bị mốc không?"},{"type":"p","text":"Thường không. Cạo lớp mặt và giảm ẩm là đủ. Chỉ thay đất khi đất đã mục, có mùi, thoát nước kém hoặc cây có dấu hiệu thối rễ."},{"type":"h3","text":"Quế bột có thật sự trị nấm không?"},{"type":"p","text":"Đây là cách dân gian, có thể giúp hạn chế nấm trên mặt đất một chút. Giảm ẩm và tăng thoáng vẫn là cách chính."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$nam-moc-trang-tren-mat-dat-chau$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Chậu sứ, chậu gốm tráng men đẹp sang nhưng nhiều chiếc không có lỗ thoát nước ở đáy. Trồng thẳng cây vào đó, mỗi lần tưới dư nước sẽ đọng ở đáy chậu — lâu ngày rễ thiếu khí, thối dần mà bên ngoài không thấy."},{"type":"image","file":"https://pd.w.org/2025/07/192687c82a3a92579.44164725-1536x2048.jpeg","caption":"Cây kiểng lá trong chậu sứ trang trí"},{"type":"h2","text":"💡 Cách tốt nhất: chậu lồng chậu"},{"type":"list","items":["Để cây ở chậu nhựa có lỗ thoát nước (thường là chậu nhà vườn khi mua về).","Lót 2–3cm sỏi hoặc đặt miếng kê dưới đáy chậu sứ.","Đặt chậu nhựa lên trên, sao cho đáy chậu nhựa cao hơn mực nước có thể đọng.","Phủ rêu khô, sỏi trắng hoặc vỏ thông lên khe giữa hai chậu để che chậu nhựa.","Sau khi tưới 15–20 phút, nghiêng chậu sứ hoặc nhấc chậu nhựa ra đổ nước đọng."],"ordered":true},{"type":"p","text":"Cách này còn tiện: muốn thay cây, đổi chậu theo mùa hay mang cây đi tắm lá chỉ cần nhấc chậu nhựa ra. Cỡ chậu nhựa theo mã C của nhà vườn xem ở bài [chọn chậu và cỡ cây](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c)."},{"type":"h2","text":"⚠️ Nếu buộc phải trồng trực tiếp"},{"type":"list","items":["Lót lớp sỏi, đá nhỏ dày 1/5 chiều cao chậu để có chỗ chứa nước dư.","Dùng giá thể rất thoát nước (xơ dừa, trấu hun, perlite).","Tưới **ít và đo lượng**: khoảng 1/4–1/5 thể tích đất mỗi lần, chờ đất khô hẳn mới tưới lại.","Chỉ trồng cây chịu hạn (lưỡi hổ, ngọc bích); tránh cây cần ẩm nhiều.","Có thể khoan lỗ đáy bằng mũi khoan kính/gạch chuyên dụng nếu chậu cho phép."],"ordered":false},{"type":"h2","text":"🔍 Dấu hiệu cây trong chậu kín bị úng"},{"type":"p","text":"Lá vàng từ dưới lên, đất có mùi hôi chua, lá rũ dù đất ướt, ruồi nhỏ bay quanh chậu (ruồi nấm đất). Gặp các dấu hiệu này, nhấc cây ra kiểm tra rễ ngay — xem [thối rễ](/benh-cay/thoi-re)."},{"type":"h2","text":"📏 Chọn chậu lót bên trong đúng cỡ"},{"type":"table","rows":[["Chậu sứ bên ngoài","Chậu nhựa bên trong nên"],["Đường kính miệng","Nhỏ hơn 2–4cm để nhấc ra, đặt vào dễ dàng"],["Chiều cao","Thấp hơn để miệng chậu nhựa ngang hoặc thấp hơn miệng chậu sứ một chút"],["Đáy","Kê cao 2–3cm bằng sỏi, miếng kê nhựa, nắp hũ úp ngược"]]},{"type":"p","text":"Nếu chậu nhựa quá thấp, kê thêm sỏi hoặc chậu nhỏ úp ngược dưới đáy. Nếu chậu nhựa quá to so với chậu sứ, thay cây sang chậu nhựa nhỏ hơn hoặc chọn chậu sứ lớn hơn — đừng ép chậu cho vừa làm gãy rễ."},{"type":"h2","text":"💧 Tưới cây trong chậu lồng"},{"type":"list","items":["Nhấc chậu nhựa ra, mang tới bồn rửa hoặc ra ban công.","Tưới đẫm cho nước chảy qua lỗ đáy.","Để ráo 10–15 phút rồi đặt lại vào chậu sứ.","Nếu không nhấc ra được (chậu lớn), tưới vừa phải và kiểm tra nước đọng ở đáy chậu sứ sau 20–30 phút."],"ordered":true},{"type":"note","title":"💡 Mẹo nhà vườn","text":"Dùng que gỗ (đũa) cắm xuống đáy chậu, rút lên sau vài phút: que ẩm ướt, dính đất là đất còn ẩm — chưa cần tưới. Cách này kiểm tra được lớp đất sâu mà ngón tay không chạm tới."},{"type":"h2","text":"🪴 Chậu tự tưới có phải chậu \"không lỗ\"?"},{"type":"p","text":"Chậu tự tưới (có ngăn chứa nước dưới đáy, bấc hoặc giá thể hút nước lên) khác hẳn chậu kín: đất được ngăn cách với nước bằng một tấm lưới hoặc khay, nước chỉ được hút lên từ từ. Loại chậu này hợp cây ưa ẩm đều như lan ý, trầu bà; nhưng vẫn cần để ngăn nước cạn hẳn vài ngày giữa các lần đổ nước để rễ được thở."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Tin rằng lớp sỏi dưới đáy đủ để chống úng**: sỏi chỉ chứa thêm một ít nước dư; nếu tưới nhiều, nước vẫn dâng lên vùng rễ.","**Tưới theo lượng như chậu có lỗ**: chậu kín cần ít nước hơn nhiều.","**Phủ kín mặt chậu bằng rêu dày**: đất khó khô, không nhìn được tình trạng đất.","**Đặt chậu kín ngoài trời không mái che**: một cơn mưa lớn là ngập cả chậu."],"ordered":false},{"type":"h2","text":"🌿 Cây nào chịu được chậu kín tốt hơn?"},{"type":"p","text":"Nếu không thể dùng cách chậu lồng chậu, chọn cây chịu khô và ít tưới: lưỡi hổ, ngọc bích, kim tiền, xương rồng. Những cây này dự trữ nước trong lá, thân hoặc củ nên chịu được lịch tưới thưa. Tránh dương xỉ, đuôi công, lan ý — cây cần đất ẩm đều nên người trồng thường tưới nhiều, dễ úng trong chậu kín."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Có tự khoan lỗ chậu sứ được không?"},{"type":"p","text":"Được với nhiều loại chậu sứ, gốm, dùng mũi khoan chuyên dụng cho gạch men, kính, khoan chậm, tưới nước làm mát mũi khoan. Chậu men mỏng, chậu có giá trị cao nên nhờ thợ hoặc giữ cách chậu lồng chậu."},{"type":"h3","text":"Cây thủy sinh có cần chậu có lỗ không?"},{"type":"p","text":"Không. Cây trồng nước dùng bình kín là bình thường, chỉ cần thay nước định kỳ — xem [trồng cây thủy sinh trong bình nước](/goc-cham-cay/trong-cay-thuy-sinh-trong-nuoc)."},{"type":"h3","text":"Làm sao biết chậu sứ có lỗ hay không khi mua?"},{"type":"p","text":"Lật ngược chậu xem đáy. Nhiều chậu sứ có nút nhựa bịt lỗ — có thể tháo ra khi trồng trực tiếp."},{"type":"products","title":"Cây chịu khô hợp chậu trang trí","slugs":["luoi-ho","ngoc-bich","trau-ba-de-vuong-xanh"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$trong-cay-chau-khong-lo-thoat-nuoc$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Dưa leo hái tận giàn giòn, thơm, ăn sống hay chấm mắm đều ngon. Trên sân thượng nhà phố, vài thùng xốp và một khung giàn đơn giản là đủ có dưa ăn hằng ngày trong mùa."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Starr-220604-0502-Cucumis_sativus-Marketmore_vine_on_trellis-Hawea_Pl_Olinda-Maui_%2852449316933%29.jpg/960px-Starr-220604-0502-Cucumis_sativus-Marketmore_vine_on_trellis-Hawea_Pl_Olinda-Maui_%2852449316933%29.jpg","caption":"Dưa leo leo giàn. Ảnh: Forest and Kim Starr, CC BY 2.0, Wikimedia Commons"},{"type":"h2","text":"🌱 Gieo hạt"},{"type":"list","items":["Ngâm hạt nước ấm 3–4 tiếng, ủ khăn ẩm đến khi nứt nanh.","Gieo 2–3 hạt mỗi hốc, sâu 1–1,5cm; giữ lại 1–2 cây khỏe khi có 2 lá thật.","Mỗi thùng xốp lớn trồng 2–3 cây."],"ordered":false},{"type":"h2","text":"🪴 Đất và thùng"},{"type":"p","text":"Thùng sâu ít nhất 30cm, có lỗ thoát nước; đất tơi giàu mùn (đất thịt + phân chuồng hoai + xơ dừa). Đặt nơi nắng 6 giờ/ngày trở lên."},{"type":"h2","text":"🪜 Làm giàn"},{"type":"p","text":"Khi cây ra tua cuốn (khoảng 2 tuần sau gieo), cắm giàn chữ A hoặc căng lưới cao 1,5–2m. Giàn chắc vì lúc nhiều trái khá nặng; sân thượng gió mạnh thì buộc thêm dây néo."},{"type":"h2","text":"💧 Tưới và bón"},{"type":"list","items":["Tưới gốc mỗi ngày, ngày nắng gắt tưới hai lần; **tưới đều** là bí quyết để trái không đắng, không cong queo.","Tránh tưới lên lá buổi chiều tối (dễ bệnh phấn trắng, sương mai).","Bón phân hữu cơ 7–10 ngày một lần; khi ra hoa, nuôi trái tăng phân có kali."],"ordered":false},{"type":"h2","text":"🌼 Thụ phấn bằng tay"},{"type":"p","text":"Dưa leo có hoa đực và hoa cái riêng (hoa cái có trái non nhỏ ngay dưới cánh hoa). Sân thượng ít ong thì sáng sớm hái hoa đực, bỏ cánh, quẹt nhị vào nhụy hoa cái. Hoa cái không được thụ phấn sẽ héo, trái non vàng rụng."},{"type":"h2","text":"🐛 Sâu bệnh hay gặp"},{"type":"list","items":["[Phấn trắng](/benh-cay/phan-trang) trên lá mùa khô.","Bọ trĩ, rệp, bọ phấn ở đọt non — xem [bọ trĩ](/benh-cay/bo-tri).","Ruồi đục trái: bao trái non bằng túi giấy.","[Héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan): nhổ bỏ cây."],"ordered":false},{"type":"h2","text":"✂️ Thu hoạch"},{"type":"p","text":"Khoảng 35–45 ngày sau gieo, hái trái khi còn non, vỏ xanh bóng, gai mềm. Hái thường xuyên để cây tiếp tục ra trái; để trái già trên cây làm cây nhanh tàn."},{"type":"h2","text":"📅 Lịch trồng dưa leo trên sân thượng"},{"type":"table","rows":[["Thời gian (sau gieo)","Giai đoạn","Việc chính"],["Ngày 3–5","Nảy mầm","Giữ ẩm, che nắng gắt buổi trưa"],["Ngày 10–14","Cây con 2–3 lá thật","Tỉa cây yếu, bón phân hữu cơ loãng"],["Ngày 14–20","Ra tua cuốn","Làm giàn, hướng dây leo lên giàn"],["Ngày 25–35","Ra hoa","Thụ phấn tay nếu ít ong, tăng phân kali"],["Ngày 35–45","Thu trái đầu","Hái thường xuyên, bón thúc nhẹ"],["Sau khoảng 2 tháng thu","Cây già, lá vàng nhiều","Nhổ bỏ, trộn lại đất, trồng luân canh cây khác"]]},{"type":"h2","text":"🥒 Vì sao dưa leo bị đắng, cong, vẹo?"},{"type":"table","rows":[["Hiện tượng","Nguyên nhân thường gặp","Khắc phục"],["Trái đắng","Thiếu nước, nắng nóng gay gắt, tưới thất thường","Tưới đều mỗi ngày, phủ gốc giữ ẩm"],["Trái cong queo","Thụ phấn không đều, thiếu nước, thiếu dinh dưỡng","Thụ phấn tay, tưới đều, bổ sung kali"],["Trái thắt eo, phình đầu","Thụ phấn kém, cây yếu","Thụ phấn tay vào sáng sớm"],["Trái non vàng rụng","Hoa cái không được thụ phấn, cây mang quá nhiều trái","Thụ phấn tay, tỉa bớt trái dị dạng"]]},{"type":"h2","text":"✂️ Tỉa nhánh cho giàn thoáng"},{"type":"p","text":"Dưa leo leo giàn trên sân thượng nên giữ thân chính khỏe. Tỉa bỏ các nhánh phụ ở 4–5 đốt dưới gốc để gốc thoáng, ít bệnh; phía trên để nhánh phát triển ra trái. Cắt bỏ lá già vàng ở gốc thường xuyên. Giàn thoáng giúp lá khô nhanh sau mưa, hạn chế phấn trắng và sương mai."},{"type":"h2","text":"🔄 Luân canh trên sân thượng"},{"type":"p","text":"Trồng dưa leo liên tục trên cùng một thùng đất dễ tích tụ mầm bệnh. Sau một vụ dưa, nên trộn lại đất với phân hữu cơ mới, phơi đất vài ngày và trồng cây khác họ như rau muống, rau dền, cải — xem [trồng rau dền tại nhà](/goc-cham-cay/trong-rau-den-tai-nha) — rồi mới quay lại trồng dưa."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Thùng quá nông, quá nhỏ**: cây nhanh mất sức, ít trái.","**Để trái già trên giàn**: cây ngừng ra trái mới.","**Tưới lên lá buổi chiều tối**: phấn trắng, sương mai lan nhanh.","**Giàn yếu, không néo**: gió lớn lật giàn khi cây đang nhiều trái."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Một cây dưa leo cho bao nhiêu trái?"},{"type":"p","text":"Tùy giống và cách chăm; trồng thùng trên sân thượng, mỗi cây khỏe thường cho đủ hái vài trái mỗi tuần trong mùa thu hoạch."},{"type":"h3","text":"Mùa nào trồng dưa leo trên sân thượng tốt nhất?"},{"type":"p","text":"Ở miền Tây có thể trồng quanh năm, nhưng đầu mùa khô hoặc cuối mùa mưa thường thuận lợi hơn: ít mưa dầm gây bệnh, nắng vừa phải."},{"type":"h3","text":"Có nên dùng hạt giống từ trái dưa ăn?"},{"type":"p","text":"Không nên. Nhiều giống dưa leo bán chợ là giống lai, hạt gieo lại cây không đồng đều. Mua hạt giống có bao bì rõ ràng sẽ chắc ăn hơn."},{"type":"p","text":"Xem thêm [trồng cà chua chậu](/goc-cham-cay/trong-ca-chua-chau) và [trồng ớt chậu](/goc-cham-cay/trong-ot-chau)."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$trong-dua-leo-san-thuong$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Cây tưới đủ, bón đủ mà vẫn còi cọc, lá vàng nhạt, trưa nắng là héo — trên lá không thấy sâu bệnh gì. Lúc đó nên nghĩ tới thứ nằm dưới đất: **rệp sáp rễ**. Chúng hay gặp ở cây mọng nước, lưỡi hổ, cây kiểng lá, cây ăn trái trồng chậu lâu năm."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Mealybug_on_Ghaf_%28Prosopis_cineraria%29_tree_in_India_02.jpg/960px-Mealybug_on_Ghaf_%28Prosopis_cineraria%29_tree_in_India_02.jpg","caption":"Rệp sáp phủ lớp sáp trắng như bông. Ảnh: Suyash Dwivedi, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🔍 Dấu hiệu cây bị rệp sáp rễ"},{"type":"list","items":["Cây lớn chậm hẳn, lá nhỏ, vàng nhạt dần, không có đốm bệnh rõ ràng.","Héo vào buổi trưa dù đất còn ẩm.","Nhấc cây ra khỏi chậu: thấy **đốm trắng như mốc bông** bám quanh rễ và thành chậu, bóp ra có con rệp nhỏ màu trắng hồng.","Đôi khi thấy rệp bò lên cổ rễ sát mặt đất."],"ordered":false},{"type":"p","text":"Đừng nhầm với mốc trắng hoại sinh (dạng tơ, không có con) hay [tuyến trùng](/benh-cay/tuyen-trung-sung-re) (rễ nổi u bướu)."},{"type":"h2","text":"🛠️ Cách xử lý rệp sáp rễ"},{"type":"list","items":["Nhấc cây ra, rũ bỏ toàn bộ đất cũ (bỏ đi, không dùng lại).","Rửa sạch bộ rễ dưới vòi nước, dùng bàn chải mềm chải những chỗ có sáp trắng.","Cắt bỏ rễ thối, rễ khô, phần rễ bám rệp dày đặc.","Ngâm rễ vào nước ấm khoảng 45°C trong 5–10 phút (cách nhà vườn hay dùng với cây khỏe, rễ chắc) hoặc nhúng rễ qua dung dịch xà phòng sinh học pha loãng rồi rửa lại.","Rửa chậu bằng xà phòng, phơi nắng; hoặc dùng chậu mới.","Trồng lại bằng đất mới, để chỗ râm 1 tuần, tưới vừa phải."],"ordered":true},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Ngâm nước ấm chỉ áp dụng cho cây khỏe, nhiệt độ vừa đủ ấm tay; nước quá nóng làm chết rễ. Nếu dùng thuốc bảo vệ thực vật xử lý đất, chọn thuốc có đăng ký và đọc kỹ nhãn."},{"type":"h2","text":"🛡️ Phòng rệp sáp rễ"},{"type":"list","items":["Cây mới mua về: nhấc nhẹ ra xem bầu rễ trước khi đặt cạnh cây khác.","Không dùng lại đất cũ của chậu cây bị bệnh.","Thay chậu định kỳ ([thay chậu đúng cách](/goc-cham-cay/thay-chau-cay-canh-dung-cach)) cũng là dịp kiểm tra rễ.","Rệp sáp trên thân lá: xử lý sớm (xem [rệp sáp](/benh-cay/rep-sap)) để không lan xuống đất."],"ordered":false},{"type":"h2","text":"🌿 Cây nào hay bị rệp sáp rễ?"},{"type":"table","rows":[["Nhóm cây","Vì sao dễ bị"],["Sen đá, xương rồng, cây mọng nước","Giá thể khô, ít khi thay chậu"],["Lưỡi hổ, kim tiền","Ít tưới, sống lâu một chậu, ít ai nhấc ra xem rễ"],["Cây kiểng lá chậu lâu năm","Đất cũ, rễ dày đặc, chậu chật"],["Cây ăn trái trồng chậu","Chậu lớn, nhiều năm không thay đất"],["Lan","Giá thể vỏ thông, than, kiến hay mang rệp tới"]]},{"type":"h2","text":"🔍 Kiểm tra rễ không làm hại cây"},{"type":"list","items":["Chờ đất hơi khô (không quá ướt) để bầu đất giữ nguyên khối.","Nghiêng chậu, gõ nhẹ thành chậu, đỡ gốc cây bằng tay, nhấc cả bầu ra.","Quan sát quanh thành bầu đất và đáy bầu — nơi rệp sáp rễ hay tập trung.","Không thấy gì thì đặt lại chậu, tưới nhẹ; cây gần như không bị ảnh hưởng."],"ordered":true},{"type":"note","title":"💡 Dấu hiệu dễ bỏ sót","text":"Kiến đi lại nhiều dưới đáy chậu, quanh lỗ thoát nước thường là dấu hiệu có rệp sáp ở rễ — kiến chăn rệp để lấy mật. Xem [kiến bò trên cây cảnh](/goc-cham-cay/kien-bo-tren-cay-canh-co-hai-khong)."},{"type":"h2","text":"🗓️ Theo dõi sau khi xử lý"},{"type":"list","items":["**Tuần 1–2**: để cây chỗ râm, tưới ít; cây có thể rũ nhẹ do mất bớt rễ.","**Tuần 3–4**: cây hồi lại, bắt đầu ra lá mới.","**Sau 1 tháng**: nhấc chậu kiểm tra lại một lần — rệp sáp rễ hay tái phát nếu còn sót trứng.","Kiểm tra luôn các chậu đặt cạnh vì rệp có thể bò qua lỗ thoát nước, đĩa lót chung."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Chỉ phun thuốc lên lá**: rệp ở rễ không bị chạm tới.","**Dùng lại đất cũ** sau khi phơi qua loa: trứng rệp vẫn còn.","**Đặt nhiều chậu chung một khay nước**: rệp di chuyển qua nước, đĩa lót.","**Ngâm rễ nước quá nóng**: chết rễ, cây không hồi."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Rệp sáp rễ có lây qua đất không?"},{"type":"p","text":"Có. Đất cũ, chậu cũ, dụng cụ, khay lót chung đều có thể mang rệp và trứng. Vì vậy đất cũ nên bỏ hoặc xử lý kỹ trước khi dùng lại."},{"type":"h3","text":"Cây bị rệp sáp rễ có cứu được không?"},{"type":"p","text":"Phần lớn cứu được nếu phát hiện khi cây còn khỏe. Cây đã yếu, rễ thối nhiều thì nên giâm ngọn, tách cây con để giữ giống."},{"type":"h3","text":"Có nên dùng thuốc xử lý đất?"},{"type":"p","text":"Với cây cảnh trong nhà, rửa rễ và thay đất thường đủ. Vườn cây ăn trái, chậu lớn bị nặng có thể cân nhắc thuốc có đăng ký cho rệp sáp, dùng đúng nhãn."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$rep-sap-re-cay-trong-chau$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Bình phun sương là món đồ quen thuộc của người trồng cây trong nhà. Nhưng phun sai cây, sai giờ thì không những vô ích mà còn làm cây bị nấm, thối nõn."},{"type":"h2","text":"🔎 Phun sương có tác dụng gì?"},{"type":"list","items":["Tăng độ ẩm quanh lá trong thời gian ngắn — giảm khô mép lá ở cây ưa ẩm.","Rửa bụi trên lá.","Làm môi trường kém thuận lợi cho [nhện đỏ](/benh-cay/nhen-do) (chúng thích khô).","Không thay được tưới gốc: rễ vẫn cần nước từ đất."],"ordered":false},{"type":"h2","text":"🛒 Cây nào cần, cây nào không?"},{"type":"table","rows":[["Nên phun","Không cần / không nên phun"],["Đuôi công (Calathea)","Lưỡi hổ"],["Dương xỉ","Ngọc bích, sen đá, xương rồng"],["Lan ý","Cây lá có lông tơ (lá nhung)"],["Môn, Alocasia (vừa phải)","Cây đang ra hoa — phun lên hoa dễ úng cánh"]]},{"type":"h2","text":"⏰ Phun lúc nào, phun bao nhiêu?"},{"type":"list","items":["**Buổi sáng** là tốt nhất: lá kịp khô trước tối.","Không phun buổi tối: lá ướt qua đêm dễ [đốm lá do nấm](/benh-cay/dom-la-nam).","Không phun khi nắng chiếu trực tiếp lên lá ngoài trời.","Phun hạt thật nhỏ, đủ làm ẩm bề mặt lá, không để nước nhỏ giọt, đọng ở nõn.","Phòng máy lạnh: 1 lần mỗi ngày hoặc cách ngày; mùa mưa thường không cần.","Dùng nước để qua đêm hoặc nước mưa, tránh vệt trắng trên lá do khoáng."],"ordered":false},{"type":"h2","text":"💡 Cách tăng ẩm bền hơn phun sương"},{"type":"p","text":"Phun sương chỉ giữ ẩm vài phút. Muốn bền hơn: đặt chậu trên khay sỏi có nước, gom nhiều cây gần nhau, đặt cây xa cửa gió máy lạnh. Xem thêm [cây văn phòng chịu bóng](/goc-cham-cay/cay-van-phong-chiu-bong-it-tuoi) và [cây đuôi công giữ lá không cháy mép](/goc-cham-cay/phan-biet-cay-duoi-cong-calathea)."},{"type":"h2","text":"🧴 Chọn bình phun sương"},{"type":"table","rows":[["Loại bình","Ưu điểm","Nhược điểm"],["Bình bóp tay nhỏ","Rẻ, gọn","Hạt to, mỏi tay khi nhiều cây"],["Bình xịt liên tục (bóp một lần ra nhiều tia)","Hạt mịn đều, nhẹ tay","Giá cao hơn"],["Bình áp suất (bơm hơi)","Phun lâu, hợp nhiều cây, ban công","Cồng kềnh với vài chậu trong nhà"],["Máy tạo ẩm","Tăng ẩm cả phòng, liên tục","Tốn điện, cần vệ sinh để tránh nấm"]]},{"type":"p","text":"Bình dùng phun sương cho cây nên để riêng, **không dùng chung** với bình đã chứa thuốc bảo vệ thực vật, chất tẩy rửa."},{"type":"h2","text":"🌡️ Phun sương theo mùa ở miền Tây"},{"type":"list","items":["**Mùa khô (khoảng tháng 12 – tháng 4)**: không khí khô, gió chướng; cây ưa ẩm trong nhà, ban công cần phun thường xuyên hơn.","**Mùa mưa (khoảng tháng 5 – tháng 11)**: độ ẩm cao, thường không cần phun; phun thêm dễ sinh nấm.","**Phòng máy lạnh**: quanh năm đều khô — phun theo nhu cầu cây, kết hợp khay sỏi nước."],"ordered":false},{"type":"h2","text":"🩺 Dấu hiệu phun sương quá tay"},{"type":"table","rows":[["Dấu hiệu","Ý nghĩa"],["Đốm nâu, đốm đen loang trên lá","Lá ướt lâu, nấm phát triển"],["Nõn non thâm, thối","Nước đọng ở nõn — hay gặp với cây dạng hoa thị"],["Vệt trắng trên lá","Khoáng trong nước — dùng nước mưa, nước để qua đêm"],["Mặt đất chậu luôn ẩm, có rêu","Phun quá nhiều xuống đất, kết hợp tưới quá tay"]]},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Phun sương thay cho tưới**: rễ vẫn khô, cây vẫn héo.","**Phun cho mọi cây trong nhà như nhau**: cây mọng nước, cây lá lông không cần, thậm chí bị hại.","**Phun buổi tối trước khi tắt đèn**: lá ướt cả đêm.","**Phun nước lạnh từ tủ lạnh**: sốc lá cây nhiệt đới."],"ordered":false},{"type":"h2","text":"🪴 Gom cây thành nhóm: cách tăng ẩm \"miễn phí\""},{"type":"p","text":"Mỗi chiếc lá đều thoát hơi nước ra không khí. Khi đặt nhiều chậu cây gần nhau, hơi nước từ lá và đất tạo thành một vùng không khí ẩm hơn xung quanh nhóm cây — giống một khu rừng nhỏ. Cách bố trí này hợp với đuôi công, dương xỉ, lan ý trong phòng máy lạnh. Đặt cây ưa ẩm ở giữa nhóm, cây chịu khô ở rìa; chừa khoảng cách vừa đủ để lá không chạm nhau quá dày, vẫn có gió lưu thông và dễ kiểm tra sâu bệnh."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Phun sương có giúp trị nhện đỏ không?"},{"type":"p","text":"Phun sương làm môi trường kém thuận lợi cho nhện đỏ, nhưng không diệt được khi chúng đã đông. Cần xịt nước mạnh mặt dưới lá và dùng biện pháp trị nhện — xem [dầu neem và xà phòng sinh học](/goc-cham-cay/dau-neem-xa-phong-sinh-hoc-tri-sau)."},{"type":"h3","text":"Có nên pha phân bón vào bình phun sương?"},{"type":"p","text":"Chỉ dùng phân bón lá đúng loại, đúng liều và theo hướng dẫn. Phun sương hằng ngày nên dùng nước sạch, không pha phân."},{"type":"h3","text":"Máy tạo ẩm có tốt hơn phun sương không?"},{"type":"p","text":"Máy tạo ẩm giữ ẩm ổn định hơn cho cả phòng, hợp với nhiều cây ưa ẩm như đuôi công. Cần vệ sinh máy thường xuyên."},{"type":"products","title":"Cây ưa ẩm cần phun sương","slugs":["duoi-cong-xanh","duoi-cong-tim","duong-xi","lan-y"]}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$phun-suong-cho-cay-khi-nao-nen$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Gừng, nghệ là gia vị và vị thuốc dân gian quen thuộc. Trồng trong thùng xốp hay bao tải ở góc sân, ít tốn công, lại có lá xanh mướt quanh năm. Đầu mùa mưa ở miền Tây là thời điểm trồng thuận lợi nhất."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Ingwer_%28Zingiber_officinale%29_Freiland_Anbau_Pflanze-2-Josef_Schlaghecken.jpg/960px-Ingwer_%28Zingiber_officinale%29_Freiland_Anbau_Pflanze-2-Josef_Schlaghecken.jpg","caption":"Cây gừng trồng tại nhà. Ảnh: Schlaghecken Josef, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🌱 Chọn và ủ củ giống"},{"type":"list","items":["Chọn củ chắc, vỏ căng, có nhiều **mắt mầm** (u nhỏ màu vàng, hồng ở đầu củ).","Bẻ thành đoạn 3–5cm, mỗi đoạn có 2–3 mắt; để khô vết bẻ 1 ngày.","Ủ trong cát ẩm hoặc khăn ẩm nơi râm 1–2 tuần cho mầm nhú."],"ordered":false},{"type":"h2","text":"🪴 Trồng"},{"type":"list","items":["Thùng xốp, bao tải hoặc chậu sâu 30cm trở lên, đáy có lỗ.","Đất tơi xốp giàu mùn, thoát nước: đất + phân chuồng hoai + trấu hun.","Đặt củ nằm ngang, mầm hướng lên, sâu khoảng 5cm, cách nhau 15–20cm.","Nơi có nắng sáng hoặc bóng nhẹ; nắng gắt cả ngày lá dễ cháy."],"ordered":false},{"type":"h2","text":"💧 Tưới, bón, vun gốc"},{"type":"list","items":["Giữ đất ẩm đều, không để úng — củ ngâm nước sẽ thối.","1 tháng một lần bón phân hữu cơ quanh gốc.","Khi củ nhô lên mặt đất, vun thêm đất (hoặc thêm đất vào bao) để củ to và không bị xanh.","Mùa khô tưới thường xuyên hơn; phủ rơm mặt đất giữ ẩm."],"ordered":false},{"type":"h2","text":"✂️ Thu hoạch"},{"type":"p","text":"Sau 8–10 tháng, khi lá vàng úa dần là củ đã già, đào lên dùng hoặc giữ làm giống. Muốn dùng gừng non (gừng ngó hồng làm mứt, gừng tươi) có thể bới nhẹ, bẻ nhánh củ non sau 4–5 tháng rồi lấp đất lại."},{"type":"note","title":"💡 Gừng, nghệ mua chợ có trồng được không?","text":"Được, nếu củ còn mắt mầm khỏe. Một số củ đã qua xử lý bảo quản lâu sẽ nhú mầm chậm hoặc không nhú — chọn củ tươi, vỏ căng, mua ở chợ quê thường dễ lên hơn."},{"type":"h2","text":"📅 Lịch trồng gừng, nghệ"},{"type":"table","rows":[["Thời gian","Giai đoạn","Việc cần làm"],["Tháng 0","Ủ củ giống, trồng","Ủ mầm 1–2 tuần, trồng khi mầm nhú"],["Tháng 1–2","Mầm lên khỏi mặt đất","Giữ ẩm đều, che bớt nắng gắt"],["Tháng 2–5","Phát triển lá, đẻ nhánh","Bón phân hữu cơ mỗi tháng, vun gốc"],["Tháng 4–5","Có thể bẻ gừng non","Bới nhẹ một phía, bẻ nhánh non, lấp lại"],["Tháng 6–8","Củ lớn, chắc dần","Giảm đạm, giữ ẩm vừa phải"],["Tháng 8–10","Lá vàng úa","Ngưng tưới vài ngày rồi đào thu hoạch"]]},{"type":"h2","text":"🌿 Gừng và nghệ chăm khác nhau không?"},{"type":"table","rows":[["","Gừng","Nghệ"],["Ánh sáng","Ưa bóng nhẹ, nắng xuyên","Chịu nắng tốt hơn"],["Lá","Hẹp, dài như lá tre","To, bản rộng"],["Độ ẩm","Cần ẩm đều, rất sợ úng","Cần ẩm, chịu ẩm khá hơn"],["Lá dùng được","Ít dùng","Lá nghệ dùng trong một số món ăn"]]},{"type":"h2","text":"🧺 Bảo quản củ sau thu hoạch"},{"type":"list","items":["Rũ sạch đất, không rửa nếu cất lâu; để ráo nơi thoáng mát vài ngày.","Cất trong thùng có cát khô hoặc trấu, nơi râm mát — củ giữ được khá lâu.","Chọn củ to, chắc, nhiều mắt để riêng làm giống cho vụ sau.","Gừng dùng hằng ngày: bọc giấy, cất ngăn mát tủ lạnh."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Trồng trong thùng nông**: củ không có chỗ phát triển, mọc trồi lên mặt.","**Tưới quá nhiều, thùng không thoát nước**: củ giống thối trước khi kịp mọc.","**Không vun gốc**: củ lộ ra ngoài, xanh, xơ.","**Thu hoạch khi lá còn xanh tốt**: củ chưa già, cất nhanh hỏng (trừ khi muốn dùng gừng non)."],"ordered":false},{"type":"h2","text":"🛍️ Trồng bằng bao tải: tiết kiệm chỗ, dễ thu hoạch"},{"type":"list","items":["Chọn bao tải dứa hoặc túi vải trồng cây, đục vài lỗ nhỏ ở đáy và quanh thành.","Cho đất vào khoảng 1/3 bao, đặt củ giống, phủ đất.","Khi cây lên cao, xắn mép bao và bổ sung đất dần — giống như vun gốc.","Lúc thu hoạch chỉ cần dốc ngược bao ra là lấy được trọn củ, không phải đào bới."],"ordered":true},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Một thùng xốp thu được bao nhiêu gừng?"},{"type":"p","text":"Tùy củ giống và cách chăm. Thùng xốp cỡ thông dụng trồng vài đoạn củ, chăm tốt thường cho lượng gừng đủ dùng trong bếp gia đình nhiều tuần."},{"type":"h3","text":"Gừng trồng trong nhà được không?"},{"type":"p","text":"Gừng chịu bóng nhẹ nhưng vẫn cần sáng tốt. Đặt cạnh cửa sổ sáng hoặc ban công có mái hiên sẽ hợp hơn trong nhà sâu."},{"type":"h3","text":"Lá gừng vàng đầu lá giữa mùa là sao?"},{"type":"p","text":"Thường do khô hạn, nắng gắt hoặc thiếu dinh dưỡng. Tưới đều, phủ rơm gốc và bón phân hữu cơ. Nếu gốc thối, mềm thì do úng."},{"type":"p","text":"Xem thêm [trồng hành lá từ gốc hành mua chợ](/goc-cham-cay/trong-hanh-la-tai-nha) và [ủ phân hữu cơ từ rác bếp](/goc-cham-cay/u-phan-huu-co-tu-rac-bep)."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$trong-gung-nghe-trong-thung$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Thấy cây rũ lá, phản xạ đầu tiên của hầu hết mọi người là tưới thêm nước. Nhưng nếu đất trong chậu vẫn còn ẩm ướt mà cây vẫn héo, tưới thêm là đẩy cây tới chỗ chết nhanh hơn. Héo khi đất ướt nghĩa là **rễ không đưa được nước lên lá**."},{"type":"image","file":"https://live.staticflickr.com/5029/5684778520_6b5d7e1f7e_b.jpg","caption":"Cây trồng chậu héo rũ lá"},{"type":"h2","text":"🔎 5 nguyên nhân cây héo khi đất còn ướt"},{"type":"h3","text":"1. Thối rễ do úng nước"},{"type":"p","text":"Nguyên nhân phổ biến nhất. Rễ ngâm nước lâu bị thiếu khí, nấm tấn công, rễ chuyển nâu đen, mềm nhũn, có mùi hôi. Xem [thối rễ](/benh-cay/thoi-re) và [5 dấu hiệu thối rễ mùa mưa](/goc-cham-cay/5-dau-hieu-thoi-re-mua-mua)."},{"type":"h3","text":"2. Nắng nóng gắt giữa trưa"},{"type":"p","text":"Lá thoát nước nhanh hơn rễ hút được nên cây rũ tạm thời, chiều mát tự đứng lên. Đây là héo sinh lý, không cần tưới thêm — chỉ cần che nắng trưa."},{"type":"h3","text":"3. Cây vừa thay chậu, vừa chuyển chỗ"},{"type":"p","text":"Rễ bị đứt, cây cần 1–2 tuần để hồi. Để chỗ râm mát, giữ ẩm vừa phải, không bón phân."},{"type":"h3","text":"4. Rễ bị sâu hại"},{"type":"p","text":"Rệp sáp rễ, tuyến trùng làm rễ mất khả năng hút nước — xem [rệp sáp hại rễ](/benh-cay/rep-sap) và [tuyến trùng sưng rễ](/benh-cay/tuyen-trung-sung-re)."},{"type":"h3","text":"5. Héo xanh do vi khuẩn"},{"type":"p","text":"Cây héo rũ đột ngột khi lá còn xanh, hay gặp trên cà chua, ớt, cà tím. Cắt ngang gốc thân nhúng vào ly nước thấy dịch trắng đục chảy ra như sợi khói. Bệnh không chữa được, phải nhổ bỏ — xem [héo xanh vi khuẩn](/benh-cay/heo-xanh-vi-khuan)."},{"type":"h2","text":"🛠️ Cách cứu cây héo khi đất còn ướt"},{"type":"list","items":["Ngưng tưới ngay.","Dời cây vào chỗ râm mát, thoáng gió.","Nhấc cây ra khỏi chậu xem rễ: rễ trắng chắc là khỏe; rễ nâu đen, mềm, hôi là thối.","Cắt bỏ rễ thối bằng kéo sạch, để rễ khô thoáng vài giờ.","Trồng lại bằng đất mới thoát nước tốt, chậu có lỗ; tỉa bớt lá nếu rễ còn quá ít.","Tưới nhẹ sau 2–3 ngày, giữ chỗ râm 1–2 tuần."],"ordered":true},{"type":"table","rows":[["Kiểm tra","Héo do thiếu nước","Héo do rễ hỏng"],["Đất","Khô, nhẹ chậu","Ẩm hoặc sũng"],["Sau khi tưới","Tươi lại sau vài giờ","Không tươi lại, tệ hơn"],["Rễ","Trắng, chắc","Nâu đen, mềm, có mùi"]]},{"type":"h2","text":"🧭 Sơ đồ đoán nhanh trong 2 phút"},{"type":"list","items":["**Đất khô hay ướt?** Khô → thiếu nước, tưới đẫm. Ướt → đi tiếp bước 2.","**Héo lúc nào?** Chỉ héo trưa nắng, chiều tự đứng lên → héo sinh lý, che nắng trưa. Héo cả ngày → bước 3.","**Có vừa thay chậu, chuyển chỗ?** Có → để râm, chờ 1–2 tuần. Không → bước 4.","**Nhấc cây xem rễ**: rễ nâu đen, mềm, hôi → thối rễ. Rễ có bông trắng → rệp sáp rễ. Rễ có u sưng → tuyến trùng. Rễ trắng khỏe nhưng cây héo đột ngột (cà, ớt) → nghĩ tới héo xanh vi khuẩn."],"ordered":true},{"type":"h2","text":"🌱 Chăm cây trong 2 tuần sau khi cứu"},{"type":"table","rows":[["Thời gian","Việc cần làm"],["Ngày 1","Cắt rễ thối, trồng lại đất mới thoát nước, để chỗ râm thoáng"],["Ngày 2–3","Tưới nhẹ lần đầu; không bón phân"],["Tuần 1","Cây có thể vẫn rũ nhẹ, rụng vài lá — bình thường"],["Tuần 2","Lá đứng lên dần, đọt có thể nhú mầm mới; tưới khi mặt đất khô"],["Sau 3–4 tuần","Đưa dần ra chỗ sáng như cũ; bón phân loãng khi cây ra lá mới đều"]]},{"type":"note","title":"💡 Khi rễ đã thối quá nửa","text":"Cây đã mất gần hết rễ khó cứu toàn bộ. Giâm ngọn, giâm cành còn khỏe là cách giữ lại giống cây — xem [nhân giống cây cảnh tại nhà](/goc-cham-cay/nhan-giong-cay-canh-tai-nha)."},{"type":"h2","text":"🛡️ Phòng cây héo do rễ hỏng"},{"type":"list","items":["Tưới theo độ ẩm đất, không theo lịch cố định.","Chậu luôn có lỗ thoát nước; đổ nước đọng dưới đĩa lót.","Thay đất, thay chậu định kỳ khi đất đã mục, nén chặt.","Mùa mưa: đưa chậu vào chỗ có mái che, kê cao khỏi nền."],"ordered":false},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Tưới thêm khi thấy cây héo** mà không kiểm tra đất.","**Bón phân \"cho cây khỏe lại\"** khi rễ đang hỏng: phân làm cháy rễ thêm.","**Đưa cây héo ra nắng** cho \"khô đất nhanh\": lá mất nước nhanh hơn, cây kiệt sức.","**Trồng lại vào đất cũ** sau khi cắt rễ thối: mầm bệnh vẫn còn."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây héo bao lâu thì không cứu được?"},{"type":"p","text":"Không có mốc thời gian chung. Thân còn chắc, còn một phần rễ trắng thì vẫn có cơ hội. Thân mềm nhũn, thâm đen tới gốc thì khó cứu — nên giâm ngọn."},{"type":"h3","text":"Có cần dùng thuốc trị nấm khi rễ thối không?"},{"type":"p","text":"Việc chính là cắt bỏ rễ thối, thay đất thoát nước. Có thể dùng chế phẩm sinh học như Trichoderma khi trồng lại để hỗ trợ."},{"type":"h3","text":"Sao cây héo khi vừa mua về?"},{"type":"p","text":"Cây từ nhà vườn về nhà thay đổi ánh sáng, nhiệt độ, độ ẩm nên có thể sốc vài ngày. Xem [chăm cây mới mua về](/goc-cham-cay/cham-soc-cay-moi-mua-ve)."},{"type":"p","text":"Xem thêm [héo do thiếu nước](/benh-cay/heo-thieu-nuoc) để so sánh."}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$cay-heo-du-dat-con-uot$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Một bình thủy tinh trong, thấy rõ bộ rễ trắng muốt và vài lá xanh — cây thủy sinh để bàn vừa sạch sẽ (không đất, không côn trùng đất) vừa ít phải chăm. Không phải cây nào cũng sống được trong nước, nhưng khá nhiều cây kiểng lá quen thuộc làm được."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Ficus_cuttings_with_roots_in_a_bottle..jpg/960px-Ficus_cuttings_with_roots_in_a_bottle..jpg","caption":"Cành cây ra rễ trong bình nước. Ảnh: Biusch, CC BY-SA 3.0, Wikimedia Commons"},{"type":"h2","text":"🛒 Cây nào trồng thủy sinh được?"},{"type":"table","rows":[["Dễ trồng nước","Lưu ý"],["Phú quý, vạn lộc, ngọc ngân (Aglaonema)","Rất bền, lá màu đẹp"],["Trầu bà các loại","Ra rễ nhanh từ đốt thân"],["Lan ý","Vẫn ra hoa nếu đủ sáng"],["Lan chi","Dùng cây con trên nhánh rủ"],["Không nên","Cây mọng nước (lưỡi hổ lớn, ngọc bích), cây ăn trái"]]},{"type":"h2","text":"🛠️ Chuyển cây từ đất sang nước"},{"type":"list","items":["Nhấc cây khỏi chậu, rũ đất, ngâm rửa rễ thật sạch dưới vòi nước nhẹ.","Cắt bỏ rễ thối, rễ đứt dập; tỉa bớt rễ quá dài.","Đặt cây vào bình sao cho **nước chỉ ngập rễ**, gốc thân và lá phải ở trên mặt nước.","Dùng sỏi, đá hoặc nắp xốp có lỗ để giữ cây đứng.","Vài tuần đầu rễ đất sẽ thoái hóa và mọc rễ nước mới (trắng, mảnh hơn) — thay nước 3–4 ngày một lần trong giai đoạn này."],"ordered":true},{"type":"h2","text":"💧 Thay nước và bón phân"},{"type":"list","items":["Thay nước 5–7 ngày một lần; dùng nước để qua đêm.","Rửa sạch nhớt bám ở rễ và thành bình khi thay.","Mỗi tháng nhỏ vài giọt **phân thủy sinh** theo hướng dẫn; không dùng phân bón đất.","Nước đục, có mùi: thay ngay, kiểm tra rễ thối."],"ordered":false},{"type":"h2","text":"☀️ Đặt bình ở đâu?"},{"type":"p","text":"Nơi sáng tán xạ, **không có nắng chiếu thẳng vào bình** — nắng làm nước nóng và rêu xanh mọc nhanh trong bình thủy tinh. Rêu nhiều thì dùng bình màu hoặc bình mờ."},{"type":"h2","text":"❓ Cây thủy sinh có sống lâu không?"},{"type":"p","text":"Có thể sống nhiều năm nếu thay nước đều và bổ sung dinh dưỡng, nhưng thường lớn chậm hơn trồng đất. Khi cây quá lớn so với bình, có thể tách bớt hoặc chuyển ra trồng đất. Xem thêm [phân biệt phú quý, vạn lộc, ngọc ngân](/goc-cham-cay/phan-biet-phu-quy-van-loc-ngoc-ngan-ngan-hau)."},{"type":"h2","text":"✂️ Giâm cành ra rễ trong nước từ đầu"},{"type":"p","text":"Thay vì chuyển cây từ đất sang nước, cách dễ thành công hơn là giâm cành trực tiếp trong nước — rễ mọc ra đã là \"rễ nước\", cây không phải thích nghi lại."},{"type":"list","items":["Cắt đoạn ngọn dài 10–20cm, có ít nhất 1–2 mắt (đốt) và vài lá.","Tuốt bỏ lá ở phần sẽ ngập nước.","Cắm vào bình nước sạch, mắt ngập nước, đặt nơi sáng tán xạ.","Thay nước 3–4 ngày một lần; sau vài tuần rễ mọc dài là có thể để luôn trong bình."],"ordered":true},{"type":"p","text":"Trầu bà, ngọc ngân, phú quý, lan chi (cây con trên nhánh rủ) là những cây ra rễ trong nước dễ nhất."},{"type":"h2","text":"🫙 Chọn bình và vật liệu"},{"type":"table","rows":[["Lựa chọn","Ưu điểm","Lưu ý"],["Bình thủy tinh trong","Ngắm được rễ, đẹp","Dễ mọc rêu nếu gần nắng"],["Bình màu, bình mờ","Hạn chế rêu","Khó nhìn mực nước và tình trạng rễ"],["Sỏi, đá cuội đáy bình","Giữ cây đứng, trang trí","Rửa sạch trước khi dùng, rửa lại khi thay nước"],["Hạt đất nung (hạt viên)","Giữ cây chắc, thoáng khí","Ngâm rửa trước khi dùng"]]},{"type":"h2","text":"🐟 Nuôi cá trong bình cây thủy sinh được không?"},{"type":"p","text":"Một số người thả vài con cá nhỏ vào bình trồng trầu bà, phú quý. Cá ăn bớt lăng quăng, chất thải của cá cung cấp thêm chút dinh dưỡng cho cây. Tuy nhiên bình nhỏ, không sục khí, thay nước thường xuyên sẽ không phải môi trường tốt cho cá. Nếu muốn kết hợp, nên dùng bình lớn và chăm sóc cá đúng cách."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Ngập cả gốc thân trong nước**: thân thối từ gốc.","**Để lâu không thay nước**: nước đục, rễ nhớt, có mùi.","**Bón phân bón đất pha đặc**: nước nhiều rêu, rễ cháy.","**Đặt bình dưới nắng trực tiếp**: nước nóng, rêu mọc dày."],"ordered":false},{"type":"h2","text":"🦟 Bình cây nước có sinh muỗi không?"},{"type":"p","text":"Nước tĩnh để lâu có thể thành chỗ muỗi đẻ trứng, nhất là bình miệng rộng đặt ngoài ban công. Thay nước đúng hẹn 5–7 ngày một lần là đủ cắt vòng đời lăng quăng. Bình miệng rộng có thể đậy bớt bằng nắp xốp có lỗ cắm cây, hoặc phủ một lớp sỏi nổi. Nếu thấy lăng quăng, đổ bỏ nước, rửa bình ngay."},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Cây thủy sinh có cần phân không?"},{"type":"p","text":"Có, nhưng rất ít. Nước sạch không có đủ dinh dưỡng lâu dài, nên mỗi tháng nhỏ vài giọt phân dành cho cây thủy sinh theo hướng dẫn."},{"type":"h3","text":"Rễ cây thủy sinh bị nhớt, nâu là sao?"},{"type":"p","text":"Thường do nước để lâu, thiếu khí hoặc rễ thối. Rửa rễ, cắt bỏ phần nâu mềm, thay nước mới và thay nước thường xuyên hơn."},{"type":"h3","text":"Có chuyển cây thủy sinh ra trồng đất được không?"},{"type":"p","text":"Được, nhưng cây cần thời gian thích nghi. Trồng vào giá thể tơi, giữ ẩm hơn bình thường trong 2–3 tuần đầu."},{"type":"products","title":"Cây trồng thủy sinh được","slugs":["phu-quy","ngoc-ngan","van-loc","lan-y","lan-chi"]}]$j$::jsonb, "read_minutes" = 5, "updated_at" = now()
  WHERE "slug" = $j$trong-cay-thuy-sinh-trong-nuoc$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Lá non vừa nhú đã xoăn tít, mép cong lên hay cong xuống, có khi nhăn nhúm như giấy vò — đó là tín hiệu đọt non đang bị tổn thương. Nguyên nhân có thể là côn trùng rất nhỏ, virus hoặc chỉ là thời tiết. Mỗi nguyên nhân xử lý khác nhau nên cần đoán đúng."},{"type":"image","file":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/American_elm_leaves_with_woolly_elm_aphid_infestation_.jpg/960px-American_elm_leaves_with_woolly_elm_aphid_infestation_.jpg","caption":"Lá non xoăn, biến dạng. Ảnh: Account for test, CC BY-SA 4.0, Wikimedia Commons"},{"type":"h2","text":"🔍 Bảng phân biệt nhanh"},{"type":"table","rows":[["Dấu hiệu đi kèm","Nguyên nhân thường gặp"],["Đám con nhỏ màu xanh, đen ở đọt, lá dính mật","Rệp muội"],["Vệt bạc, đốm nâu trên lá, nụ hoa thâm; con thon dài 1–2mm","Bọ trĩ"],["Lá non dày, giòn, cong ngược xuống, đọt chùn lại; không thấy con","Nhện trắng (nhện rất nhỏ, cần kính lúp)"],["Lá loang xanh vàng như khảm, cây còi; có bọ phấn trắng quanh","Virus xoăn lá, khảm lá"],["Xoăn sau đợt nắng nóng, gió khô; lá già không bị","Thời tiết, thiếu nước"],["Xoăn đồng loạt ngay sau khi phun thuốc, bón phân lá","Ngộ độc do phun quá liều"]]},{"type":"h2","text":"🛠️ Xử lý theo nguyên nhân"},{"type":"list","items":["**Rệp muội**: xịt nước mạnh, cắt đọt nặng, dùng xà phòng sinh học — xem [rệp muội](/benh-cay/rep-muoi).","**Bọ trĩ**: cắt bỏ nụ, đọt bị nặng, treo bẫy dính xanh dương hoặc vàng — xem [bọ trĩ](/benh-cay/bo-tri).","**Nhện**: phun nước mặt dưới lá, tăng độ ẩm — xem [nhện đỏ](/benh-cay/nhen-do).","**Virus**: không có thuốc chữa. Nhổ bỏ cây bị nặng để khỏi lây, diệt bọ phấn, rệp truyền bệnh — xem [vàng xoăn lá virus](/benh-cay/xoan-la-virus), [khảm lá](/benh-cay/kham-la).","**Thời tiết**: che nắng trưa, tưới đều; lá mới ra sẽ phẳng lại.","**Ngộ độc thuốc**: ngưng phun, tưới nước rửa lá; lần sau pha đúng liều, phun lúc chiều mát."],"ordered":false},{"type":"note","title":"⚠️ Lưu ý an toàn","text":"Không phun nhiều loại thuốc trộn chung khi chưa rõ nguyên nhân — dễ làm cây ngộ độc thêm. Nếu dùng thuốc bảo vệ thực vật, chọn thuốc có đăng ký đúng đối tượng và đọc kỹ nhãn. Xem [hướng dẫn dùng thuốc an toàn](/chinh-sach/thuoc-bvtv-an-toan)."},{"type":"h2","text":"❓ Lá đã xoăn có phẳng lại được không?"},{"type":"p","text":"Lá đã biến dạng thường giữ nguyên hình dạng. Điều cần theo dõi là **lá mới ra sau khi xử lý**: lá mới phẳng, lành lặn nghĩa là đã xử lý đúng. Lá xoăn quá xấu có thể cắt bỏ dần."},{"type":"h2","text":"🔎 Kiểm tra bằng kính lúp và tờ giấy trắng"},{"type":"p","text":"Nhiều thủ phạm gây xoăn lá nhỏ tới mức mắt thường gần như không thấy. Hai cách kiểm tra đơn giản:"},{"type":"list","items":["**Kính lúp** (hoặc chế độ phóng to trên điện thoại): soi mặt dưới lá non, nách lá — tìm rệp, bọ trĩ, nhện.","**Tờ giấy trắng**: đặt dưới cành lá nghi bị hại, gõ nhẹ cành. Những chấm nhỏ bò trên giấy là nhện, bọ trĩ; chấm xanh, đen tròn là rệp."],"ordered":false},{"type":"h2","text":"🌱 Cây hay bị xoăn lá non"},{"type":"table","rows":[["Cây","Nguyên nhân hay gặp"],["Ớt, cà chua","Bọ trĩ, nhện trắng, virus xoăn lá do bọ phấn truyền"],["Hoa hồng","Rệp muội ở đọt, bọ trĩ ở nụ"],["Mai vàng","Rệp, bọ trĩ đọt non sau đợt ra lá"],["Bông giấy, dâm bụt","Rệp, bọ phấn"],["Cây kiểng lá trong nhà","Nhện đỏ khi không khí khô, ngộ độc phân bón lá"]]},{"type":"h2","text":"🗓️ Theo dõi sau xử lý"},{"type":"p","text":"Đánh dấu lá non mới nhú bằng một sợi chỉ nhỏ hoặc chụp ảnh lại. Sau 1–2 tuần, so sánh lá mới với lá cũ: lá mới phẳng, màu đều là đúng nguyên nhân và đã xử lý được. Nếu lá mới vẫn xoăn, quay lại bảng phân biệt để kiểm tra nguyên nhân khác, hoặc chụp ảnh gửi người có chuyên môn hỏi thêm."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Phun thuốc trừ sâu khi nguyên nhân là virus hoặc thời tiết**: tốn kém, không có tác dụng.","**Trộn nhiều loại thuốc, phân bón lá cùng lúc**: dễ ngộ độc, lá xoăn thêm.","**Giữ cây virus nặng trong vườn** vì tiếc: nguồn lây cho cây khác.","**Cắt bỏ hết lá xoăn ngay**: cây mất lá quang hợp; nên cắt dần khi lá mới đã ra."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Làm sao phân biệt xoăn lá do virus với do côn trùng?"},{"type":"p","text":"Virus thường làm lá loang lổ xanh vàng như khảm, cây còi, và không thấy con gì dù đã soi kỹ. Côn trùng thường để lại dấu vết: vệt bạc, chấm, mật dính, xác lột."},{"type":"h3","text":"Cây bị virus xoăn lá có cứu được không?"},{"type":"p","text":"Hiện không có thuốc chữa virus cho cây. Cây nhẹ vẫn cho thu hoạch nhưng kém; cây nặng nên nhổ bỏ và diệt côn trùng truyền bệnh."},{"type":"h3","text":"Lá xoăn sau khi phun thuốc có tự hết không?"},{"type":"p","text":"Lá đã bị ngộ độc thường giữ nguyên hình dạng. Ngưng phun, tưới đủ nước, lá mới ra sẽ phẳng lại nếu cây không bị hại quá nặng."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$la-non-bi-xoan-bien-dang$j$ AND "updated_by" = 'Hệ thống';
--> statement-breakpoint
UPDATE "posts" SET "body" = $j$[{"type":"p","text":"Mặt đất chậu phủ lớp xanh mướt như nhung, thành chậu đất nung loang lổ màu xanh rêu. Có người thấy đẹp, có người lo cây bệnh. Thực ra rêu và tảo không ăn cây — chúng chỉ cho bạn biết chậu đang ẩm hơn mức cần."},{"type":"image","file":"https://pd.w.org/2026/03/29269bd11f19642a0.88733813-2048x1151.jpg","caption":"Rêu mọc trên mặt đất trồng"},{"type":"h2","text":"🔎 Vì sao chậu cây bị rêu, tảo?"},{"type":"list","items":["Đất ẩm liên tục, tưới thường xuyên hoặc tưới phun mưa nhẹ hằng ngày.","Chậu đặt chỗ râm, ít gió, ánh sáng yếu.","Nước tưới có nhiều chất dinh dưỡng (phân bón lá rơi xuống đất).","Chậu đất nung thấm nước qua thành nên mặt ngoài luôn ẩm — rêu mọc rất nhanh."],"ordered":false},{"type":"h2","text":"🔍 Rêu có hại cây không?"},{"type":"p","text":"Rêu mỏng không hại. Rêu, tảo dày đặc thành lớp nhầy làm mặt đất bí, nước khó thấm xuống, giữ ẩm lâu ở cổ rễ — với cây ưa khô như [lưỡi hổ](/san-pham/luoi-ho), [ngọc bích](/san-pham/ngoc-bich) thì dễ dẫn tới [thối rễ](/benh-cay/thoi-re)."},{"type":"h2","text":"🛠️ Xử lý rêu trên mặt chậu"},{"type":"list","items":["Cạo bỏ lớp mặt có rêu, phủ đất mới khô.","Tưới đẫm một lần rồi chờ mặt đất khô mới tưới tiếp, thay vì tưới ít mỗi ngày.","Dời chậu ra chỗ sáng, thoáng gió hơn.","Phủ mặt chậu bằng sỏi, đá trang trí giúp mặt đất khô nhanh.","Thành chậu đất nung: chà bằng bàn chải với nước pha giấm loãng, rửa sạch, phơi nắng."],"ordered":false},{"type":"h2","text":"💡 Khi nào nên giữ rêu?"},{"type":"p","text":"Với cây bonsai, tiểu cảnh, cây ưa ẩm như [dương xỉ](/san-pham/duong-xi), lớp rêu mỏng trên mặt chậu giữ ẩm và nhìn rất \"cổ\". Chậu đất nung bám rêu cũng là phong cách được nhiều người thích. Chỉ cần đảm bảo nước vẫn thấm nhanh xuống đất và cổ rễ không bị đọng nước."},{"type":"h2","text":"🔍 Rêu, tảo hay nấm?"},{"type":"table","rows":[["Hình dạng","Là gì","Gợi ý"],["Lớp xanh mượt như nhung, sợi nhỏ","Rêu","Không hại khi mỏng; giảm ẩm nếu dày"],["Lớp xanh nhớt, trơn, có mùi tanh","Tảo","Đất quá ướt — cạo bỏ, tưới thưa"],["Tơ trắng như bông","Nấm hoại sinh","Xem [mốc trắng trên mặt đất chậu](/goc-cham-cay/nam-moc-trang-tren-mat-dat-chau)"],["Váng trắng khô, sạn","Muối khoáng","Tưới rửa đất, dùng nước mềm hơn"]]},{"type":"h2","text":"🌿 Muốn nuôi rêu trang trí thì sao?"},{"type":"p","text":"Với bonsai, tiểu cảnh, nhiều người cố ý phủ rêu lên mặt chậu. Để rêu đẹp mà cây vẫn khỏe:"},{"type":"list","items":["Chỉ phủ một lớp mỏng, chừa khoảng trống quanh gốc thân để cổ rễ thoáng.","Phun sương nhẹ cho rêu thay vì tưới đẫm cả chậu mỗi ngày.","Dùng giá thể thoát nước tốt bên dưới để nước không đọng ở vùng rễ.","Cây ưa khô (sen đá, xương rồng, lưỡi hổ) không hợp phủ rêu."],"ordered":false},{"type":"h2","text":"🏺 Vệ sinh chậu đất nung định kỳ"},{"type":"list","items":["Khi thay chậu hoặc thay đất, ngâm chậu đất nung cũ vào nước pha giấm loãng vài giờ.","Chà sạch rêu, cặn trắng bằng bàn chải cứng.","Rửa lại bằng nước sạch, phơi nắng 1–2 ngày cho khô hẳn trước khi trồng."],"ordered":true},{"type":"p","text":"Cách này vừa làm sạch rêu, vừa giảm mầm bệnh còn sót trong chậu cũ."},{"type":"h2","text":"🚫 Sai lầm thường gặp"},{"type":"list","items":["**Dùng thuốc diệt rêu, chất tẩy mạnh** trên chậu đang trồng cây: hại rễ.","**Cạo rêu mà không đổi cách tưới**: rêu mọc lại nhanh.","**Để rêu phủ kín sát gốc cây ưa khô**: cổ rễ ẩm lâu, dễ thối."],"ordered":false},{"type":"h2","text":"📋 Tóm tắt cách xử lý theo mức độ"},{"type":"list","items":["**Rêu mỏng, cây khỏe**: giữ nguyên nếu thích, chỉ cần tưới thưa hơn một chút.","**Rêu dày, nước khó thấm**: cạo lớp mặt, xới nhẹ đất, đổi sang tưới đẫm rồi chờ khô.","**Tảo nhớt, đất có mùi**: cạo bỏ, kiểm tra lỗ thoát nước và rễ, dời chậu ra chỗ sáng thoáng.","**Thành chậu đất nung loang rêu**: chà rửa khi thay chậu, hoặc giữ lại nếu thích vẻ cổ."],"ordered":false},{"type":"h2","text":"❓ Câu hỏi thường gặp"},{"type":"h3","text":"Rêu trên chậu có làm cây thiếu dinh dưỡng không?"},{"type":"p","text":"Rêu mỏng dùng rất ít dinh dưỡng, gần như không ảnh hưởng. Vấn đề chính là rêu dày giữ ẩm quá lâu."},{"type":"h3","text":"Tảo xanh trong bình cây thủy sinh xử lý thế nào?"},{"type":"p","text":"Dời bình khỏi nắng trực tiếp, thay nước, rửa bình và giảm phân. Có thể dùng bình màu, bình mờ — xem [trồng cây thủy sinh trong bình nước](/goc-cham-cay/trong-cay-thuy-sinh-trong-nuoc)."},{"type":"h3","text":"Gạch, nền sân quanh chậu bị rêu trơn trượt thì sao?"},{"type":"p","text":"Chà rửa định kỳ, kê chậu lên kệ cho nước thoát, không để nước tưới đọng trên nền. Cẩn thận với người lớn tuổi và trẻ nhỏ khi đi lại."},{"type":"p","text":"Xem thêm [tưới cây trong nhà đúng cách](/goc-cham-cay/tuoi-cay-trong-nha-dung-cach) và [chọn chậu và cỡ cây](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c)."}]$j$::jsonb, "read_minutes" = 4, "updated_at" = now()
  WHERE "slug" = $j$reu-tao-moc-tren-dat-chau-cay$j$ AND "updated_by" = 'Hệ thống';
